window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-nefrologia-nef-3"]={"block":"medcurso:medcurso-nefrologia-nef-3","label":"Medcurso · NEF 3","count":422,"questions":[{"id":"medcurso-nefrologia-nef-3-345438","number":"345438","sourceNumber":"345438","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A taxa de filtração glomerular (TFG) é a medida da depuração de uma substância que é\nfiltrada livremente pelos glomérulos e não sofre reabsorção ou secreção tubular, sendo um\nindicador importante para detecção, avaliação e tratamento da doença renal crônica (DRC). Na\nprática clínica, o cálculo da TFG é feita por meio de equações que utilizam as medidas das\nconcentrações da:","options":{"A":"Glicosúria.","B":"Proteinúria urinária.","C":"Creatinina sérica.","D":"Microalbuminúria urinária."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-345442","number":"345442","sourceNumber":"345442","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente masculino com 37 anos, com peso informado de 65 kg, está internado com\nquadro grave após acidente ofídico. À\nadmissão apresentava creatinina sérica de 1,2 mg/dl, a qual\nse elevou para 3,7mg/dl, após 5 dias. Nas 24 horas prévias à coleta desse exame, o paciente teve\ndiurese de 440 ml. O paciente se mantém hemodinamicamente estável sem uso de drogas\nvasoativas. Considerando a diretriz do KDIGO (Kidney Disease Improvement Global Outcomes),\nassinale a alternativa CORRETA:","options":{"A":"O paciente apresenta injúria renal aguda estádio 1.","B":"O paciente apresenta injúria renal aguda estádio 2.","C":"O paciente apresenta injúria renal aguda estádio 3.","D":"O paciente apresenta injúria renal aguda, de origem pré-renal, não sendo possível, nenhum\nestadiamento."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-343846","number":"343846","sourceNumber":"343846","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 85 anos senilizado chega ao Pronto-Socorro acompanhado por familiares\nque relatam diarreia e piora progressiva do nível\nde consciência nos últimos dias. Ao exame ele\nestá desidratado, descorado, sonolento, sem sinais localizatórios. A gasometria arterial obtida em\nar ambiente revela: pH = 7,20; PCO2 = 32 mmHg; Po2= 85mmHg; Sat. = 93%; HCO3 = 12,0\nmEQ/l; BE = - 14,0. A mehor interpretação para esse distúrbio ácido básico é:","options":{"A":"Acidose metabólica compensada por uma alcalose respiratória.","B":"Acidose mista, respiratória e metabólica.","C":"Alcalose respiratória compensada por uma acidose metabólica.","D":"Acidose metabólica adequadamente compensada por hiperventilação alveolar."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-281094","number":"281094","sourceNumber":"281094","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente portador de insuficiência renal crônica, em fase pré-dialítica, apresentou\nem exame bioquímico de rotina para\nseguimento, ureia de 98mg/dL, creatinina de 3mg/dL e\npotássio de 6,3 mEq/L. É hipertenso, controlado com medicamentos, e apresentou-se taquicárdico,\nrespectivamente com PA = 145/95 mmHg e FC = 110 bpm. Referiu mal - estar geral, mas sem\nsinais ou sintomas específicos de alguma morbidade. O exame físico não revelou outras alterações.\nCom base nesse caso hipotético, a conduta deve ser complementar à avaliação com realização\nprioritária de:","options":{"A":"Ecocardiograma.","B":"Tomografia computadorizada renal.","C":"Angiorressonância renal.","D":"Eletrocardiograma.","E":"RX de Tórax."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-281108","number":"281108","sourceNumber":"281108","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Senhor de 78 anos dá entrada no pronto-socorro taquidispneico, sendo diagnosticado\ncom pneumonia. A gasometria arterial coletada na\nadmissão demonstra pH de 7,30 (VR 7,36-7,44);\npCO2 24 mmHg (VR: 35-45); HCO3: 10 mEq/L (VR: 22-26) e BE: -6 (VR: -2-+2). Neste caso há\n\nacidose...","options":{"A":"metabólica e alcalose respiratória.","B":"respiratória compensada.","C":"metabólica e acidose respiratória.","D":"metabólica compensada.","E":"respiratória e alcalose metabólica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-281114","number":"281114","sourceNumber":"281114","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Senhor de 88 anos é trazido por familiares ao pronto-atendimento apresentando\nsonolência e queda do estado geral.\nAcompanhante (cuidador) refere que paciente é portador de\nhipertensão arterial sistêmica e doença de Alzheimer. Faz uso diário de hidroclorotiazida,\nenalapril,\ndonepezila e olanzapina. Não há relato de mudança recente na posologia dos fármacos. Exames\nlaboratoriais coletados em avaliação inicial evidenciam: Na 120 mEq/L (VR: 135-145); K 3,8 mEq/L\n(VR 3,5-5,0) e função renal normal. Sobre a hiponatremia:","options":{"A":"Dentre as etiologias possíveis de hiponatremia, para o caso supracitado, estão: medicamentosa,\ninsuficiência cardíaca, hipotireoidismo e insuficiência adrenal.","B":"A correção com salina hipertônica deve ter como meta a concentração sérica de sódio de 140\nmEq/L em 12 horas.","C":"Hidroclorotiazida é a única medicação prescrita que pode levar à hiponatremia.","D":"Colesterol baixo, triglicérides baixo e hipoglicemia são causas de pseudo-hiponatremia.","E":"A concentração urinária de sódio não tem importância na investigação etiológica da\nhiponatremia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-281120","number":"281120","sourceNumber":"281120","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 85 anos, é trazido ao pronto atendimento por familiares, apresentando\nsonolência e queda do estado geral. Seu\ncuidador refere que o paciente é portador de hipertensão\narterial sistêmica e doença de Alzheimer e está em uso diário de hidroclorotiazida, enalapril,\ndonepezila e olanzapina, em doses estáveis há pelo menos dois anos. Os exames laboratoriais\ncoletados na avaliação inicial evidenciam: Na = 119 mEq/L (normal de 135 a 145 mEq/L); K 3,7\nmEq/L (normal de 3,5 a 5,5 mEq/L) e função renal normal. Assinale a afirmativa correta em relação\nao distúrbio hidroeletrolítico apresentado nesse caso.","options":{"A":"A concentração urinária de sódio não tem importância na investigação etiológica da\nhiponatremia.","B":"A correção com salina hipertônica deve ter como meta a concentração sérica de sódio de 140\nmEq/L, a ser atingida em 12 horas.","C":"Colesterol baixo, triglicérides baixos e hipoglicemia são causas comprovadas de\npseudo-hiponatremia.","D":"Dentre as etiologias possíveis de hiponatremia estão: medicamentosa, insuficiência cardíaca,\nhipotireoidismo e insuficiência adrenal.","E":"Hidroclorotiazida é a medicação prescrita que pode levar à hiponatremia, enquanto donepezila e\nolanzapina estão mais relacionados à ocorrência de hipernatremia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-281157","number":"281157","sourceNumber":"281157","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A alteração no eletrocardiograma - ECG que NÃO está relacionada a hiperpotassemia\né:","options":{"A":"Onda T em tenda e apiculada.","B":"Alargamento do complexo QRS.","C":"Fibrilação ventricular.","D":"Assistolia.","E":"Aumento da amplitude da onda P."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-251861","number":"251861","sourceNumber":"251861","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Das causas abaixo, qual a mais comum de hipopotassemia?","options":{"A":"Hiperaldosteronismo primário.","B":"Hiperaldosteronismo secundário.","C":"Síndrome de Gitelman.","D":"Diarreia infecciosa."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-251867","number":"251867","sourceNumber":"251867","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na reposição hidroeletrolítica por via parenteral, a necessidade básica de potássio de\num paciente adulto é de:","options":{"A":"1 MEq/Kg.","B":"3 MEq/Kg.","C":"5 MEq/Kg.","D":"12 MEq/Kg."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-251876","number":"251876","sourceNumber":"251876","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 45 anos, internada na UTI com quadro de choque séptico de foco urinário,\nencontra-se intubada sob ventilação mecânica, com fração inspirada de O2 de 0,5. Sua gasometria\narterial é a seguinte: pH: 7,30; pCO2: 60; pO?: 96; SatO?: 96%; HCO?: 24. Sobre o caso descrito,\nassinale a alternativa que apresenta o distúrbio acidobase primário e a conduta mais adequada.","options":{"A":"Alcalose metabólica, realizar hidratação.","B":"Alcalose respiratória, aumentar a sedação.","C":"Acidose metabólica, repor bicarbonato.","D":"Acidose respiratória, ajustar parâmetros do ventilador."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-247170","number":"247170","sourceNumber":"247170","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Paciente do\nsexo feminino, 52 anos, atendida no\nambulatório sem acompanhante, relata poliúria e fraqueza nas\núltimas semanas. Questionada sobre problemas de saúde e medicações, refere que é hipertensa,\nem uso de atenolol e de outro medicamento \"para os nervos\" que não recorda o nome. Em função\ndo quadro clínico, que medicação a paciente provavelmente estaria usando?","options":{"A":"Ácido valproico.","B":"Amitriptilina.","C":"Clonazepam.","D":"Clorpromazina.","E":"Lítio."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-217653","number":"217653","sourceNumber":"217653","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A coagulopatia da doença renal crônica é causada principalmente por:","options":{"A":"Consumo dos fatores da coagulação.","B":"Disfunção plaquetária.","C":"Menor concentração de eritropoetina.","D":"Plaquetopenia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-217703","number":"217703","sourceNumber":"217703","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um homem de 20 anos de idade procurou o pronto atendimento por ter notado quadro\nde fraqueza muscular importante e parestesia,\nsem conseguir se levantar da cama. Refere que, na\nnoite anterior, estava assintomático e que a fraqueza era mais importante em MMII, mas também\nacometia MMSS. No dia anterior, havia ido a uma festa da faculdade, onde ingeriu bastante bebida\nalcoólica e salgados. Quando perguntado sobre antecedentes, referiu que dois episódios\nsemelhantes já haviam ocorrido no passado, após brigas com sua namorada, e que tinham sido\ndiagnosticados como distúrbio de ansiedade, apresentando melhora espontânea após algumas\nhoras. Ao exame físico, o paciente estava calmo, lúcido, contactante, BEG, corado, afebril e\ndesidratado+/4. Sinais vitais normais. Paralisia flácida de MMII (força grau 1), paresia de MMSS\n(força grau 4), reflexos ausentes em MMII e reduzidos em MMSS. Considerando-se esse caso\nhipotético, a CONDUTA INICIAL seria:","options":{"A":"Administrar benzodiazepínico oral.","B":"Administrar KCI endovenoso.","C":"Pulsar com imunoglobulina.","D":"Pulsar com metilprednisolona."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-135927","number":"135927","sourceNumber":"135927","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um lactante com 1 mês e 20 dias de vida é atendido na Unidade de Pronto\nAtendimento de seu bairro com história de\nvômitos alimentares em jato após as mamadas.\nEncontra-se abaixo do peso esperado para idade e desidratado. Após investigação, a ecografia\nabdominal firmou o diagnóstico de estenose hipertrófica de piloro. Quais os distúrbios acidobásicos\nque se espera encontrar?","options":{"A":"Alcalose respiratória;","B":"Alcalose metabólica;","C":"Acidose respiratória;","D":"Acidose metabólica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-108625","number":"108625","sourceNumber":"108625","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com quadro de hiponatremia, sem edemas, água corpórea total aumentada,\nsódio corpóreo total normal e sódio urinário >\n20. Qual a provável causa da condição acima?","options":{"A":"Excesso de diuréticos;","B":"Vômitos;","C":"Insuficiência Renal Aguda;","D":"SSIADH."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-84505","number":"84505","sourceNumber":"84505","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 65 anos admitido com história de ser portador de hipertensão arterial\nfazendo uso de hidroclorotiazida e losartana,\né admitido no pronto-socorro apresentando depressão\ndo segmento ST, achatamento das ondas T e ondas U proeminentes. Qual o distúrbio\nhidroeletrolítico mais provável:","options":{"A":"Hipocalcemia.","B":"Hiponatremia.","C":"Hipocalemia.","D":"Hipomagnesemia.","E":"Hipercalemia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-84545","number":"84545","sourceNumber":"84545","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O cálculo do Anion GAP pode ser útil em algumas condições clínicas, entre as quais\nintoxicações exógenas e acúmulo de lactato, cetonas e outros metabólitos. Quais os eletrólitos\nnecessários para esse cálculo e qual o valor normal do Anion Gap?","options":{"A":"Potássio, cloro, sódio. Valor normal: 3-6 meq/l;","B":"Sódio, cálcio, potássio. Valor normal: 0-2 meq/l;","C":"Sódio, cloro, bicarbonato. Valor normal: 8-12 meq/l;","D":"Cálcio, fósforo, proteínas. Valor normal: 28-32 meq/l;","E":"Cálcio, cloro, bicarbonato. Valor normal: 0-5 meq/l."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-84546","number":"84546","sourceNumber":"84546","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando um paciente na enfermaria com os seguintes parâmetros gasométricos:\npH= 7,28; PaCO2: 35 mmhg; HCO3: 16. Podemos\nafirmar que, muito provavelmente, o paciente é\nportador de: Fórmula de WINTER - pCO2 = 1,5 x HCO3 + 8 (+/- 2). Valores referencia: pCO2-\n\n35-45 (mmHg), HCO3- 22-26 mEq/L","options":{"A":"Acidose mista.","B":"Acidose metabólica.","C":"Acidose metabólica em fase inicial de compensação respiratória.","D":"Acidose respiratória.","E":"Alcalose Metabolica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-314202","number":"314202","sourceNumber":"314202","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação aos biomarcadores de insuficiência renal aguda assinale a alternativa\nincorreta.","options":{"A":"Um biomarcador ideal é o que viabiliza diagnóstico e prevenção da lesão renal, sinalizando sua\nlocalização, tipo e etiologia.","B":"Os biomarcadores de função renal, quando persistentemente alterados, apontam para a lesão\nrenal potencial, sem prejuízo da taxa de filtração glomerular.","C":"A análise de diferentes biomarcadores permite acompanhar os eventos associados ao\ndesenvolvimento da insuficiência renal aguda desde a exposição inicial até a instalação de lesão\ncelular com posterior desequilíbrio funcional renal.","D":"Os biomarcadores de parada do ciclo celular são ativados pelo estresse celular causado pela\nexposição a agentes de lesão renal potencial."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-313443","number":"313443","sourceNumber":"313443","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação à Insuficiência Renal Aguda (IRA), assinale a alternativa correta.","options":{"A":"A IRA é uma situação clínica de etiologia variada, mais comum em pacientes com doenças\nleves.","B":"A IRA esta associada à morbidade em longo prazo.","C":"O diagnóstico de IRA deve ser ativamente buscado em pacientes susceptíveis.","D":"A busca pelo diagnóstico de IRA não tem relação com o índice de angina renal."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-231357","number":"231357","sourceNumber":"231357","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na insuficiência renal aguda:","options":{"A":"Alterações no EAS não são frequentes.","B":"Anemia, normocítica, normocrômica, devido à falta de eritropoetina é um achado universal.","C":"Acidose metabólica hipoclorêmica é um achado laboratorial muito frequente.","D":"A retenção de sódio de forma intensa, a níveis abaixo de 10 mEq/L são achados típicos E\nUNIVERSAIS da necrose tubular aguda.","E":"Alterações anteriores dos marcadores da função renal; antecedentes patológicos de diabetes e\nhipertensão; presença de anemia normocítica normocrômica, alterações do cálcio, fósforo e PTH,\nsão dados que indicam a possibilidade da presença da doença renal crônica ao invés de lesão\nrenal aguda."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-231358","number":"231358","sourceNumber":"231358","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considere a imagem e responda a correta","options":{"A":"Caso o paciente apresente uma creatinina de 2,5 mg/dL deve se tratar de um caso de\nInsuficiência Renal Aguda obstrutiva","B":"Há uma grande chance de encontrarmos familiares acometidos pela mesma patologia","C":"A hematúria macroscópica é uma complicação que acomete mais de 80% dos pacientes\nportadores dessa patologia","D":"O surgimento de neoplasias renais nesses pacientes é um achado que supera os 50%","E":"É consenso que o uso de inibidores de SGLT2 são medicamentos úteis nessa patologia"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-201753","number":"201753","sourceNumber":"201753","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com quadro de diarreia e septicemia, com a seguinte gasometria: pH = 7,10;\nBicarbonato = 8; PaCo2 = 26; PaO2 = 100. Qual o distúrbio ácido básico associado?","options":{"A":"Acidose metabólica e acidose respiratória.","B":"Alcalose metabólica e acidose respiratória.","C":"Acidose metabólica e alcalose respiratória.","D":"Alcalose metabólica e alcalose respiratória.","E":"Acidose metabólica apenas."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-201760","number":"201760","sourceNumber":"201760","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Quais as causas relacionadas à acidose metabólica?","options":{"A":"Uso abusivo de antiácidos.","B":"Insuficiência respiratória crônica.","C":"Vômitos incoercíveis.","D":"Insuficiência renal.","E":"Hiponatremia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-219905","number":"219905","sourceNumber":"219905","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação aos distúrbios acidobásicos assinale a alternativa INCORRETA:","options":{"A":"A tentativa de compensação respiratória aos distúrbios metabólicos é quase instantânea.","B":"Depleção de volume e hipercalemia favorecem uma maior reabsorção de bicarbonato.","C":"Distúrbios metabólicos afetam primariamente a concentração plasmática de bicarbonato.","D":"Nos distúrbios respiratórios crônicos o pH sanguíneo pode permanecer praticamente normal\napesar de grandes variações da pCO2."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-212193","number":"212193","sourceNumber":"212193","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a Injúria Renal Aguda (IRA), assinale a alternativa CORRETA:","options":{"A":"O uso de aminoglicosídeos em dose única diária não causa nefrotoxicidade.","B":"Na prevenção da nefrotoxicidade por contraste é indicado hidratação endovenosa e\nanti-inflamatórios não esteroidais.","C":"Na IRA pós-renal há um aumento discreto da creatinina sérica, enquanto a ureia sérica\nencontra-se bastante elevada.","D":"A doença de Weil na leptospirose, frequentemente,\n\napresenta-se com IRA não oligúrica e potássio sérico com valor dentro da normalidade ou abaixo.","E":"Na IRA está indicado o uso de Inibidores da Enzima Conversora da Angiotensina (IECA) e\nBloqueadores dos Receptores da Angiotensina II (BRA), sendo considerados medicamentos\nnefroprotetores."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-201770","number":"201770","sourceNumber":"201770","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em pacientes com doença renal crônica, a falta de produção endógena da eritropoetina\ne outros fatores associados, como a\ndeficiência relativa ou absoluta de ferro, resultam no\ndesenvolvimento de anemia, que é uma condição associada à piora da qualidade de vida e ao\naumento na morbidade e mortalidade. A respeito do tratamento da anemia, do uso de eritropoetina\nrecombinante humana e da reposição do ferro nos pacientes em hemodiálise, assinale a opção\nCORRETA:","options":{"A":"No tratamento da anemia em hemodiálise, a hemoglobina alvo é 13 g/dl.","B":"De modo geral, a atividade inflamatória aumentada não interfere na resposta do paciente à\neritropoetina recombinante humana.","C":"Doses elevadas de eritropoetina para o tratamento da anemia em pacientes com doença renal\ncrônica estão associadas ao desenvolvimento ou à piora da hipertensão e ao aparecimento de\nacidentes vasculares cerebrais.","D":"Se, na avaliação laboratorial dos estoques de ferro, for verificado que a ferritina está abaixo\nde\n500 ng/ml, a administração de ferro endovenoso\ndeverá ser suspensa.","E":"A causa mais comum de resposta inadequada à eritropoetina recombinante humana é a\ndeficiência de folato."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-212170","number":"212170","sourceNumber":"212170","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente 58 anos, sexo masculino, diabético, hipertenso e portador de doença renal\ncrônica estágio V, deu entrada na emergência\ncom mal-estar e fraqueza muscular intensa. Foi\ncolhido exames laboratoriais e realizado eletrocardiograma que apresentou achatamento da onda\nP, onda T apiculada e QRS alargado. De acordo com essas informações, qual o provável distúrbio\nhidroeletrolítico apresentado pelo paciente?","options":{"A":"Hipocalemia.","B":"Hiponatremia.","C":"Hipercalemia.","D":"Hipercalcemia.","E":"Hiperfosfatemia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-219917","number":"219917","sourceNumber":"219917","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Pré-escolar de 4 anos com quadro de febre persistente, tosse produtiva, prostração e\ncansaço com evolução de 5 dias. Ao exame\nfísico, apresenta esforço respiratório com uso de\nmusculatura acessória, aumento de frequência respiratória e saturação de oxigênio de 88% em ar\nambiente. À ausculta pulmonar há redução do murmúrio à direita e macicez à percussão do mesmo\nlado. Pulsos estão finos e rápidos, a perfusão capilar é de 4 segundos e a frequência cardíaca é\n170 batimentos por minuto. O resultado da gasometria arterial está abaixo: O diagnóstico\nADEQUADO para o achado da gasometria nesse caso é:","options":{"A":"Acidose metabólica.","B":"Acidose respiratória.","C":"Alcalose metabólica.","D":"Alcalose respiratória."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215544","number":"215544","sourceNumber":"215544","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos doadores vivos no transplante\nrenal.","options":{"A":"A retirada do rim de um indivíduo sadio deve ser seguida de um cuidado especial, objetivando\numa morbidade mínima e máxima segurança.","B":"A doação deve ser desprovida de interesses e ser espontânea.","C":"A escolha do rim a ser retirado deve ser baseada na vontade do doador.","D":"Deixa-se sempre no doador o rim em melhores condições; na presença de rim ptótico, achado\ncomum em mulheres, este é o escolhido."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-219890","number":"219890","sourceNumber":"219890","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 20 anos, deu entrada no pronto-socorro obnubilado. Sem passado mórbido de\nimportância. Pressão arterial = 127 x 70 mmHg, sem hipotensão ortostática. As extremidades estão\nbem perfundidas. O exame neurológico não mostra deficit focais. Exames complementares: Na =\n138 mEq/L; K = 4,2 mEq/L; HCO3 = 5 mEq/L; CI = 104 mEq/L; creatinina = 1,0 mg/dl; ureia = 14\nmg/dl; cálcio total corrigido para albumina = 10 mg/dl; glicemia = 90 mg/dl; gasometria arterial (ar\nambiente): PO2 = 96 mmHg; PCO2 = 15 mmHg; pH = 7,02; urinálise: normal. Dentre as opções\nabaixo, qual é o distúrbio acidobásico MAIS PROVÁVEL?","options":{"A":"Acidose metabólica pura com hiato aniônico (ânion-gap) aumentado e compensação respiratória.","B":"Acidose respiratória pura e compensação metabólica.","C":"Distúrbio misto ? acidose metabólica e alcalose respiratória com hiato aniônico (ânion-gap)\nnormal.","D":"Distúrbio misto ? acidose metabólica e respiratória com hiato aniônico (ânion-gap) aumentado."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187759","number":"187759","sourceNumber":"187759","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação às alterações do cálcio no organismo, assinale alternativa ERRADA:","options":{"A":"A hipocalcemia aguda geralmente é frequente após reanimação do choque","B":"A infusão de gluconato de cálcio não pode ser pela mesmo via da infusão de bicarbonato","C":"A síndrome da lise tumoral inclui entre outras alterações eletrolíticas a hipercalcemia","D":"Na hipocalcemia o tratamento com infusão de gluconato de cálcio por via venosa deve ser feito\nlentamente, pelo risco de parada cardíaca"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187823","number":"187823","sourceNumber":"187823","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação às alterações do potássio no organismo, assinale alternativa ERRADA:","options":{"A":"A administração venosa de cálcio pode reduzir imediatamente o risco de arritmia cardíaca\nocasionada pela hipercalemia","B":"A hipomagnesemia pode determinar hipocalemia refratária","C":"A infusão de insulina e glicose diminui rápida e drasticamente o potássio corporal total","D":"Ondas T mais altas que ondas R indicam hipercalemia grave"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187836","number":"187836","sourceNumber":"187836","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação às hemorragias, assinale a alternativa CORRETA:","options":{"A":"A hipotermia afeta a \"cascata da coagulação\"","B":"Nas de origem venosa, as alterações importantes dos níveis de lactato e déficit de base se\ninstalam precocemente","C":"O hematócrito é um indicador fidedigno de hemorragia aguda","D":"Um dos primeiros mecanismos de compensação em resposta a uma queda de volume\nintravascular é a diminuição da atividade simpática"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-182817","number":"182817","sourceNumber":"182817","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"ECG compatível com Hiperpotassemia, somente NÃO apresenta o seguinte achado:","options":{"A":"as alterações dependem dos níveis séricos e ocorrem sequencialmente.","B":"onda T de grande amplitude, simétrica e de base larga.","C":"redução do intervalo QTc.","D":"distúrbio de condução intraventricular (QRS alargado)."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187829","number":"187829","sourceNumber":"187829","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"ERT, 60 anos, no 4° dia de pós operatório de gastrectomia, queixa-se de dor torácica\nem pontada na inspiração, tosse produtiva e\nfebre há 24 horas. Após avaliação inicial, o residente\nda cirurgia geral solicita gasometria arterial, ionograma e radiografia de tórax. O resultado da\ngasometria apresenta: pH: 7,2; PaCO?: 58mmHg; PaO?: 60mmHg; SaO?: 92%; Bic: 15mEq/L; BE:\n\n-9mEq/L. O ionograma apresenta: Na+: 136mEq/L; Cl: 107mEq/LA radiografia de tórax mostra\nimagem de condensação nos terços médio e inferior do pulmão direito. A partir da gasometria do\npaciente, é CORRETO afirmar que o desequilíbrio ácido base encontrado é:","options":{"A":"Acidose metabólica","B":"Acidose mista","C":"Acidose respiratória","D":"Alcalose metabólica"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-180155","number":"180155","sourceNumber":"180155","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual a complicação mais comum da ressuscitação volêmica com solução fisiológica\n0,9% e que difere da ressuscitação com Ringer\nlactate?","options":{"A":"Edema","B":"Acidose hiperclorêmica","C":"Coagulopatia","D":"Insuficiência renal","E":"Hiperosmolaridade"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187839","number":"187839","sourceNumber":"187839","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"HSC, sexo masculino, 65 anos, hipertenso em uso de losartana foi submetido a\nressecção transuretral de próstata por\nhiperplasia prostática benigna. Duas horas após o término do\nprocedimento iniciou com quadro de agitação, elevação da pressão arterial seguido de episódio de\nconvulsão. Exames laboratoriais: Sódio sérico: 126mEq/L; Potássio sérico: 3,3mmol/L. Baseado\nnestas informações assinale a conduta MAIS INDICADA para este paciente:","options":{"A":"Administração de Cloreto de potássio 10% intravenoso","B":"Administração de Glicose 5% intravenoso","C":"Administração de Gluconato de cálcio 10% intravenoso","D":"Administração de Cloreto de sódio 0,9% intravenoso"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-182743","number":"182743","sourceNumber":"182743","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A diminuição da função renal, avaliada pela taxa de filtração glomerular (TFG)\nmensurada ou calculada, está associada à maior\nmortalidade CV. Sendo INCORRETO, apenas, o\nseguinte:","options":{"A":"presença de doença renal crônica (DRC), em especial nos estágios mais avançados, é\nconsiderada risco-equivalente à DAC, e a redução de LDL-C deverá ser o objetivo principal no\ntratamento destes pacientes.","B":"nas fases iniciais da doença renal (estágios 1 e 2), as modificações lipídicas preponderantes são\nhipertrigliceridemia e HDL-C elevado.","C":"com a evolução da DRC, torna-se mais comum a elevação do LDL-C.","D":"ocorre um estado pró-aterogênico por mudança no fenótipo da molécula de LDL (maior\nconcentração de moléculas pequenas e densas) e pelo próprio meio urêmico."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-183623","number":"183623","sourceNumber":"183623","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na população com doença renal crônica, a redução pressórica não apresenta o\nseguinte conceito como válido:","options":{"A":"Na população, a redução pressórica constitui a medida mais eficaz para a redução do risco CV e\natenuação da progressão do dano renal, independentemente do anti-hipertensivo utilizado.","B":"Atenção especial deve ser dispensada a pacientes com albuminúria elevada, pois essa é\ndeterminante de evolução desfavorável da doença renal, bem como de aumento do risco CV.","C":"Pacientes idosos com doença renovascular, DAC e com risco de hipotensão postural,\nfrequentemente, requerem a individualização do tratamento anti-hipertensivo.","D":"Recomendam-se valores pressóricos inferiores a 140/80 mmHg, especialmente naqueles com\nalbuminúria acima de 30 mg/g de creatinina e em diabéticos."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-183637","number":"183637","sourceNumber":"183637","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Levando-se em consideração os distúrbios do potássio, assinale a afirmativa\nCORRETA.","options":{"A":"A presença de ECG com aumento de amplitude da onda U indica um potássio sérico maior que\n6,0 mEq/L.","B":"A presença de onda T apiculada e o encurtamento do intervalo QT indica um potássio sérico\nentre 5,5-6,5 mEq/L.","C":"O emprego de salbutamol se faz somente por via endovenosa.","D":"A sintomatologia da hipocalemia é precoce e surge com níveis de potássio sérico menores que\n3,0 mEq/L."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-183606","number":"183606","sourceNumber":"183606","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à lesão renal aguda.","options":{"A":"A oferta diária de proteínas da dieta não afeta a geração de creatinina.","B":"Os níveis séricos de creatinina independem do volume de distribuição, isto é, da água corpórea\ntotal.","C":"Evidências recentes demonstram que, mesmo as alterações mínimas nos níveis de creatinina,\npodem se associar com alta taxa de\nmortalidade.","D":"A creatinina é o marcador mais utilizado para a avaliação da função renal e parece, também, ser\num marcador ideal em pacientes seriamente enfermos."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-183548","number":"183548","sourceNumber":"183548","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa INCORRETA.","options":{"A":"As medicações que interferem com a hemodinâmica renal e as doenças renais primárias são,\ntambém, causadoras de lesão renal aguda.","B":"A epidemiologia da lesão renal aguda vem se modificando ao longo das últimas décadas com os\navanços nos cuidados primários de saúde e\nnas tecnologias médicas.","C":"As causas de lesão renal aguda no período neonatal são multifatoriais.","D":"Após a alta hospitalar é desnecessária a monitorização dos recém-nascidos que apresentaram\nlesão renal aguda durante a\n\ninternação."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-182778","number":"182778","sourceNumber":"182778","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em pacientes em risco de desenvolver arritmia cardíaca a partir da hipercalemia,\nintervenções urgenciais são importantes. São elas, EXCETO:","options":{"A":"Gluconato de Cálcio 10%.","B":"Bicarbonato de Sódio 8,4%.","C":"Solução Polarizante.","D":"Tiazídicos."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-182825","number":"182825","sourceNumber":"182825","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sao sintomas de hipermagnesemia, EXCETO","options":{"A":"hiperreflexia.","B":"hipotensão.","C":"sonolência.","D":"hipoventilação."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161350","number":"161350","sourceNumber":"161350","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O Magnésio, um cátion essencial na célula, é o segundo ânion mais prevalente. É\ncofator crítico em qualquer reação\nimpulsionada pelo ATP, portanto as deficiências podem afetar o\nmetabolismo. Sobre o Magnésio e seus distúrbios, aponte a alternativa INCORRETA.","options":{"A":"Parato-hormônio, Glucagon e Hormônio Antidiurético aumentam a reabsorção de Magnésio na\nAlça de Henle.","B":"Mais de 90% do teor de Magnésio total do corpo é encontrado no Líquido Extracelular.","C":"O Magnésio pode bloquear a transmissão sináptica de impulsos nervosos. Pode ocorrer perda\ndos reflexos do tendão profundo, paralisia\nflácida e apneia.","D":"A hipermagnesemia aguda associada à disfunção renal grave deve ser tratada com diálise."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161154","number":"161154","sourceNumber":"161154","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A interpretação eletrocardiográfica é fundamental para o manejo do pós-operatório e de\npacientes gravemente enfermos. (Conforme imagem do caderno de questões). À qual condição\nclínica e a qual tratamento imediato mais adequado se refere, RESPECTIVAMENTE, o traçado\napresentado nessa imagem?","options":{"A":"Hipocalcemia ? Gluconato de Cálcio, Carbonato de Cálcio e Vitamina D.","B":"Hipercalcemia ? Soro Fisiológico, Furosemida e Hemodiálise.","C":"Hipercalemia ? Gluconato de Cálcio, Bicabornato de Sódio, Solução Glicoinsulina e Hemodiálise.","D":"Hipocalemia ? KCl 19,1% 10 meq/h e Reposição de Magnésio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-158787","number":"158787","sourceNumber":"158787","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente diabético, portador de insuficiência renal, faltou às sessões de diálise na\núltima semana. Vem à emergência com queixa de\nmal-estar, fraqueza e parestesias. Realizou ECG\nque tem o seguinte traçado (Conforme imagem do caderno de questões). Qual a primeira medida a\nser realizada nesse caso?","options":{"A":"Inalação de Beta 2 agonista.","B":"Investigação da causa do distúrbio.","C":"Administração de furosemida venosa.","D":"Administração de gluconato de cálcio 10% venoso.","E":"Administração de glicose a 50% com insulina regular."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-158768","number":"158768","sourceNumber":"158768","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Para realizar o tratamento de qualquer distúrbio hidroeletrolítico, é mandatória a\ndistinção da etiologia. Qual patologia é uma causa da hiponatremia euvolêmica?","options":{"A":"Nefropatia perdedora de sal.","B":"Insuficiência renal crônica.","C":"Hipoaldosteronismo.","D":"Hipotireoidismo.","E":"Diarreia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161255","number":"161255","sourceNumber":"161255","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em qual das seguintes situações NÃO há estímulo para o aumento da secreção do\nhormônio antidiurético?","options":{"A":"Hipervolemia.","B":"Dor.","C":"Bronquiolite aguda.","D":"Tumor cerebral."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161122","number":"161122","sourceNumber":"161122","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São causas de acidose metabólica com ânion gap aumentado, com EXCEÇÃO de:","options":{"A":"Acidose láctica.","B":"Intoxicação por metanol, etilenoglicol, salicilato.","C":"Intoxicação por tolueno.","D":"Insuficiência renal."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161125","number":"161125","sourceNumber":"161125","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São manifestações clínicas de acidose metabólica, com EXCEÇÃO de:","options":{"A":"Vasoconstrição arterial e vasodilatação venosa.","B":"Respiração profunda e rápida (ritmo de Kussmaul).","C":"Arritmias cardíacas.","D":"Distensão abdominal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161300","number":"161300","sourceNumber":"161300","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual dos hormônios a seguir absorve apenas água sem absorver eletrólitos?","options":{"A":"Cortisol.","B":"Aldosterona.","C":"Hormônio antidiurético.","D":"Adrenalina."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161261","number":"161261","sourceNumber":"161261","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São causas pré-renais de injúria renal aguda, com EXCEÇÃO de","options":{"A":"hipovolemia por perdas gastrointestinais, como vômitos e diarreia.","B":"estreitamentos da uretra.","C":"síndrome nefrótica.","D":"hemorragia pós trauma."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161269","number":"161269","sourceNumber":"161269","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em geral, a gravidade da insuficiência é fundamentada no grau de redução da taxa de\nfiltração glomerular, medida clinicamente por valores da ureia e creatinina séricas. No entanto, a\nureia, como indicador para terapia de substituição renal, é limitada, pois seus níveis podem ser\nalterados pelas seguintes situações, EXCETO por:","options":{"A":"Sangramentos do trato gastrointestinal.","B":"Uso de corticoides.","C":"Anabolismo proteico.","D":"Uso de diuréticos."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-161278","number":"161278","sourceNumber":"161278","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A diálise peritoneal é utilizada em pacientes com doença renal crônica ou doença renal\naguda. A realização desse procedimento tem contraindicação absoluta para pacientes com","options":{"A":"insuficiência renal crônica.","B":"hérnia diafragmática.","C":"doença renal crônica que apresente aderências abdominais pós cirúrgicas.","D":"doença inflamatória intestinal concomitante à doença renal aguda."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-134318","number":"134318","sourceNumber":"134318","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O quadro de hipercalemia pode ser desde assintomático até tornar-se emergência\nmédica potencialmente fatal. NÃO sendo determinante da emergência","options":{"A":"A repercussão muscular.","B":"As alterações no ECG.","C":"A quantidade total de potássio corporal.","D":"A alteração de repolarização muscular."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-109968","number":"109968","sourceNumber":"109968","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual é a manifestação clínica MAIS comum da Hipocalcemia?","options":{"A":"Tetania.","B":"Parestesia.","C":"Coma.","D":"Insuficiência renal."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-109979","number":"109979","sourceNumber":"109979","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual das soluções abaixo apresenta concentrações de sódio e cloro mais próximas das\nobservadas no plasma?","options":{"A":"Plasma fresco congelado.","B":"Soro glicosado a 5%.","C":"Ringer lactato.","D":"Soro fisiológico a 0,9%."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86786","number":"86786","sourceNumber":"86786","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação à acidose metabólica é incorreto afirmar:","options":{"A":"Caracteriza-se pela redução plasmática do pH e bicarbonato;","B":"A PaCO2 geralmente está elevada devido à\ncompensação respiratória;","C":"Pode resultar de acúmulo de ácido;","D":"Pode resultar da perda de base;","E":"Pode apresentar anion gap normal ou aumentado."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86793","number":"86793","sourceNumber":"86793","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São efeitos da acidose grave:","options":{"A":"Redução da contratilidade miocárdica.","B":"Redução das atividades das aminas plasmáticas.","C":"Vasodilatação.","D":"Hipotensão arterial.","E":"Todas as alternativas anteriores."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86796","number":"86796","sourceNumber":"86796","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"É causa comum de hiponatremia com volume extracelular aumentado:","options":{"A":"Diarreia;","B":"Uso de diuréticos;","C":"Síndrome perdedora de sal;","D":"Secreção inapropriada do hormônio antidiurético;","E":"Insuficiência cardíaca."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86799","number":"86799","sourceNumber":"86799","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em conformidade com o tratamento da hiponatremia é incorreto afirmar que:","options":{"A":"A correção rápida pode causar mielinólise\npontina central;","B":"Deve-se evitar velocidade de correção superior a 8-12 mEq/L ao dia;","C":"Deve-se evitar a correção de sódio para níveis superiores a 130 mEq/L nos primeiros dois dias;","D":"O tratamento básico para a síndrome da secreção inapropriada do hormônio antidiurético é a\nrestrição hídrica;","E":"A reposição hídrica está sempre indicada."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86597","number":"86597","sourceNumber":"86597","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"500 ml de solução fisiológica a 0,9% apresenta:","options":{"A":"38,9 mEq de sódio.","B":"190 mEq de sódio.","C":"154 mEq de sódio.","D":"340 mEq de sódio.","E":"60 mEq de sódio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86844","number":"86844","sourceNumber":"86844","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A concomitância de uso de diurético de alça e vômitos gera:","options":{"A":"Alcalose metabólica simples;","B":"Alcalose mista;","C":"Acidose mista;","D":"Acidose metabólica simples;","E":"Acidose respiratória e acidose metabólica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86885","number":"86885","sourceNumber":"86885","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Escolar de\nsete anos de idade, em tratamento de enurese noturna com DDAVP intranasal há uma semana, é\ntrazido emergência por apresentar, subitamente, crise tonicoclônica generalizada com perda de\nconsciência. Qual o provável diagnóstico?","options":{"A":"Desidratação hipertônica;","B":"Hipocalcemia;","C":"Hipoglicemia;","D":"Hiponatremia;","E":"Hipomagnesemia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-86867","number":"86867","sourceNumber":"86867","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança portadora de tumor de Wilms, nefrectomizado há seis meses e fora de\ntratamento há três meses, chega ao PS com\nquadro de vômitos incoercíveis há 5 horas e\ndistensão abdominal importante. Quando estava sendo atendida, começou a apresentar crise\nconvulsiva tônico-clônica, entrando em mal convulsivo e sendo encaminhada à UTI. O distúrbio\neletrolítico provável nesse caso é:","options":{"A":"Hipofosfatemia;","B":"Hiponatremia;","C":"Hipocalcemia;","D":"Hipomagnesemia;","E":"Hipocalemia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-158385","number":"158385","sourceNumber":"158385","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um homem de 50 anos, em tratamento conservador para doença renal crônica, procura\na emergência com queixas de fraqueza, parestesia\ne dificuldade respiratória progressiva há 4 dias.\nO ECG apresentava, entre outras alterações, achatamento das ondas P e alargamento dos\ncomplexos QRS e ondas T apiculadas, clearance estimado de creatinina de 9 ml/minuto e\nbicarbonato de 9 mEq/L. A conduta inicial mais indicada é:","options":{"A":"Bicarbonato de sódio.","B":"Gluconato de cálcio.","C":"Glico-insulina.","D":"Diálise.","E":"Resina de Troca (Sorcal®)."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-13147","number":"13147","sourceNumber":"13147","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Enfermo, 44 anos, etilista com elevada ingestão de álcool, é admitido no serviço de\nemergência com hiperêmese crônica. Seus pulmões e rins são previamente normofuncionantes.\nNesta situação NÃO se encontra:","options":{"A":"Alcalose metabólica.","B":"Hipercloremia.","C":"Bicarbonato sérico elevado.","D":"Osmolaridade urinária > 300mOsm.","E":"Hipopotassemia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-286724","number":"286724","sourceNumber":"286724","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 50 anos, vítima de atropelamento por caminhão, é trazido ao\n\npronto-socorro, apresentando lesão tipo esmagamento do membro inferior direito associado à\nfratura de bacia. Foi submetido à cirurgia ortopédica para fixação das fraturas e hidratado com\nRinger lactato com reposição de sódio, potássio e glicose. Também foram transfundidos 3\nconcentrados de hemácias devido ao sangramento abundante. No pós-operatório, o paciente\nevoluiu de forma desfavorável, apresentando insuficiência renal aguda, fraqueza muscular\nimportante e dor torácica. À ausculta cardíaca, observamos ritmo irregular, sendo realizado um\nECG que evidenciou onda T apiculada e alargamento do complexo QRS. Sobre o distúrbio\neletrolítico mais provável, assinale a alternativa CORRETA:","options":{"A":"Os dados disponíveis nos permitem afirmar que a hemodiálise está contraindicada neste\nmomento.","B":"Por tratar-se de provável hipopotassemia, o tratamento desse paciente deve incluir a\nadministração de insulina e soro glicosado a 5% na tentativa de mobilização do potássio para o\nmeio intracelular.","C":"Pelo risco de parada cardíaca, está indicada a administração de gluconato de cálcio como\nmedida inicial.","D":"A melhor medida para o tratamento da emergência descrita acima é a administração oral de\nresina de troca iônica para a rápida depleção intestinal de potássio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-327247","number":"327247","sourceNumber":"327247","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente do sexo masculino, 34 anos, vítima de atropelamento em via pública,\napresentando fratura de bacia e lesão tipo\nesmagamento de membro inferior direito com fraturas de\nfêmur e tíbia. Foi submetido a cirurgia ortopédica para fixação da fratura de bacia e estabilização\ndas fraturas, sendo hidratado com Ringer lactato e transfundido 3 concentrados de hemácias.\n\nEvoluiu com insuficiência renal aguda no pós-operatório, sendo solicitado parecer do nefrologista. O\npaciente, porém, apresentou quadro de fraqueza muscular importante e dor torácica. À ausculta\ntorácica, observamos ritmo cardíaco irregular (arritmia), sendo realizado um ECG que evidenciou\nonda T apiculada e bloqueio atrioventricular. Sobre o provável distúrbio eletrolítico deste\npaciente e\nsua condução, assinale a alternativa INCORRETA:","options":{"A":"No caso acima, é provável que a administração de enzimas de troca catiônica a nível intestinal\nseja mais efetiva que a hemodiálise no\ntratamento da urgência descrita acima.","B":"Podemos inferir que a intensa lise celular ocorrida associada à inadequada compensação\nhidroeletrolítica renal foram eventos que\ncontribuíram para a descompensação cardíaca descrita.","C":"A medida clínica imediata para tratamento deste paciente inclui a administração endovenosa de\ngluconato de cálcio a 10%.","D":"A administração de solução polarizante composta por glicose hipertônica e insulina atua na\ncorreção rápida do distúrbio descrito acima."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-362474","number":"362474","sourceNumber":"362474","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"É considerada uma indicação dialítica de urgência:","options":{"A":"Diurese >2000ml em uso de furosemida.","B":"Hiperpotassemia refratárias às medidas clínicas.","C":"Hiperpotassemia em paciente com boa diurese em uso de Espironolactona.","D":"Retenção urinária com bexiga palpável \"\"bexigoma\"\"."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-362473","number":"362473","sourceNumber":"362473","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre o diurético Furosemida de uso frequente na conduta do paciente edemaciado\ne/ou com hiperpotassemia sabemos que:","options":{"A":"Bloqueia no rim o SRAA (Sistema Renina Angiotensina Aldosterona).","B":"Bloqueia na alça de Henle os transportadores NaK2Cl.","C":"É um diurético poupador de potássio que antagoniza Aldosterona.","D":"É um diurético de escolha nos pacientes anúricos."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-298201","number":"298201","sourceNumber":"298201","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A hipercalemia apresenta algumas manifestações eletrocardiográficas. Qual a\nafirmativa a seguir é VERDADEIRA em relação a concentração de Potássio?","options":{"A":"Ondas U proeminentes são características da hipercalemia.","B":"O alargamento do complexo QRS é comum na hipercalemia grave.","C":"As inversões de onda T simétrica profunda são características da fase precoce de hipercalemia.","D":"O sinal eletrocardiográfico mais precoce de hipercalemia é a redução na amplitude da onda P."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-298203","number":"298203","sourceNumber":"298203","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"As 3 principais causas de Doença Renal Crônica no Brasil são:","options":{"A":"Diabetes Mellitus, Insuficiência Renal Aguda e Glomerulopatias.","B":"Hipertensão Arterial, Diabetes Mellitus e Litíase Renal","C":"Diabetes Mellitus, Hipertensão Arterial e Doença Real Policística","D":"Hipertensão Arterial, Diabetes Mellitus e Glomerulopatias"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-286718","number":"286718","sourceNumber":"286718","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a Fibrose Nefrogênica Sistêmica assinale a alternativa CORRETA:","options":{"A":"Pode ocorrer pelo uso do Gadolínio na Ressonância Magnética em nefropatas.","B":"No estudo urodinâmico em nefropatas.","C":"Em pacientes nefropatas oligo-anúricos pós-Tomografia contrastada.","D":"É uma complicação pelo uso do contraste iodado em pacientes nefropatas."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-176054","number":"176054","sourceNumber":"176054","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São consideradas toxinas urêmicas:","options":{"A":"Ureia, proteinúria, hematúria.","B":"Ureia, glicemia e transaminases.","C":"Hiperamonemia, uremia, hiperuricemia.","D":"PTH ou paratormônio, ureia, beta-2-microglobulinas, fósforo."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-176005","number":"176005","sourceNumber":"176005","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São consequências hematológicas da uremia:","options":{"A":"Plaquetose e policitemia.","B":"Elevação do hematócrito e hemoglobina.","C":"Deficiência de eritropoetina, redução da sobrevida das hemácias.","D":"Aumento da creatinina e ureia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-151960","number":"151960","sourceNumber":"151960","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A filtração glomerular depende do:","options":{"A":"Débito cardíaco e diurese nas 24h.","B":"Balanço hídrico em paciente oligúrico (diurese < 800 ml/d).","C":"Fluxo plasmático por néfron de acordo com o clearance de ureia diária.","D":"Coeficiente de permeabilidade glomerular, da superfície da membrana filtrante e da pressão de\nultrafiltração e do fluxo plasmático glomerular."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-151969","number":"151969","sourceNumber":"151969","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São critérios para definição de nefropatia crônica:","options":{"A":"Lesão renal tubular(necrose tubular aguda).","B":"Lesão renal por > 3 meses com redução mantida da taxa de filtração glomerular.","C":"Lesão renal por < 3 meses com necessidade dialítica.","D":"Necessidade dialítica por período < 3 meses e creatinina sérica < 1,2."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-107662","number":"107662","sourceNumber":"107662","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Nos casos de acidose metabólica temos os tampões fisiológicos: tampões bicarbonato\ne não bicarbonato. Qual elemento abaixo\nparticipa dos tampões Não bicarbonato:","options":{"A":"Lipideos;","B":"Fósforo;","C":"Sódio;","D":"Cálcio."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-81000","number":"81000","sourceNumber":"81000","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Nos casos de acidose metabólica temos os tampões fisiológicos: tampões bicarbonato\ne não bicarbonato. Qual elemento abaixo\nparticipa dos tampões não bicarbonato?","options":{"A":"Sódio","B":"Lipídeos","C":"Fósforo","D":"Carboidrato","E":"Cálcio"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-81012","number":"81012","sourceNumber":"81012","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Lactente eutrófico, alimentado somente com leite materno, iniciou quadro de diarreia\nlíquida, há 03 dias, acompanhada de febre e\nvômitos. Evoluindo com taquipneia, diminuição de\ndiurese (oligúria), sonolência. Com sinais de desidratação grave. Após etapa de expansão (3x),\napresentou diurese em pequena quantidade. Colhido os exames observou-se: Na= 115, K=1,5;\nCa= 0,9; Mg+ 2; e Fósforo= 4mg/dl. Com relação aos distúrbios hidroeletrolíticos devemos corrigir:","options":{"A":"O quadro de Hiponatremia e Hipopotassemia e ambos devem ser corrigidos, pois são\nconsiderados graves e com risco de vida.","B":"Não há distúrbios eletrolíticos para corrigir.","C":"O quadro de Hipofosfatemia e Hipomagnesemia e ambos devem ser corrigidos, pois são\nconsiderados graves e com risco de vida.","D":"Não há necessidade de correção da Hiponatremia.","E":"Os distúrbios em questão não são de natureza aguda não precisam de correção."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-61528","number":"61528","sourceNumber":"61528","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Analise as seguintes definições relacionadas ao equilíbrio ácido-base. I. pH sanguíneo\n\n> 7,45; II. pH sanguíneo < 7,35; III. Distúrbio com tendência à alcalemia; IV. Distúrbio com\ntendência à acidemia. As definições se referem respectivamente, à:","options":{"A":"Acidemia, alcalemia, acidose, alcalose.","B":"Alcalemia, acidemia, alcalose, acidose.","C":"Alcalemia, acidemia, acidose, alcalose.","D":"Acidemia, alcalemia, alcalose, acidose.","E":"Alcalose, acidose, alcalemia, academia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-34128","number":"34128","sourceNumber":"34128","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual alteração eletrolítica, leva ao quadro de agitação, letargia, taquicardia,\nhipotensão,\noligúria, rubor cutâneo?","options":{"A":"Hiperpotassemia.","B":"Hipernatremia.","C":"Hipofosfatemia.","D":"Hiponatremia.","E":"Hipocalcemia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-26648","number":"26648","sourceNumber":"26648","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente internado por 30 dias, vítima de politraumatismo, em coma devido TCE,\nrecebendo nutrição nasoenteral, vem evoluindo\ncom diarreia e apresentando distensão abdominal.\nAchado eletrocardiográfico de onda T achatada, o aparecimento de onda U. O quadro descrito é\ncompatível com:","options":{"A":"Hiponatremia.","B":"Hipercalemia.","C":"Hipercalcemia.","D":"Hipocalemia.","E":"Hipovolemia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-13289","number":"13289","sourceNumber":"13289","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 65 anos, internada na U.T.I. com diagnóstico de pancreatite grave, é\nportadora de miocardiopatia e hipertensão. O\nexame físico revela paciente com confusão mental.\nPA= 100x70mmHg; FC= 100bpm e diurese normal. Gasometria arterial com máscara de O2\n10L/min; pH = 7,15; PaCO2 = 39; Pa O2 = 47; HCO2 = 13, BE = -15,3; saturação arterial de O2 =\n72%. Assinale a correta:","options":{"A":"A diurese normal afasta o diagnóstico de choque.","B":"A ventilação mecânica não está indicada porque a PaCO2 está normal.","C":"Nessa situação, a primeira medida terapêutica é a correção do bicarbonato.","D":"A gasometria revela quadro de acidose por distúrbios metabólicos.","E":"A queda nos valores de bicarbonato decorre da tentativa de compensar a acidose respiratória."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-62807","number":"62807","sourceNumber":"62807","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A análise bioquímica de urina pode ser útil para distinguir a Insuficiência Renal Aguda\n(IRA) de etiologia pré-renal da IRA\nintrínseca. Das situações descritas a seguir, a que geralmente\napresenta níveis de fração de excreção de sódio sugerindo lesão renal intrínseca é:","options":{"A":"Nefrotoxicidade por contraste.","B":"Glomerulonefrite aguda.","C":"Necrose tubular aguda.","D":"Obstrução bilateral ureteral aguda.","E":"Insuficiência cardíaca congestiva."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-49403","number":"49403","sourceNumber":"49403","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 65 anos de idade, internado para tratamento de insuficiência cardíaca\ncongestiva, em uso de furosemida EV, digoxina\noral e betabloqueador, vem apresentando náuseas\ncom vômitos há dois dias. Realizou exames que mostram pH: 7,46, PaO2: 80 mmHg, HCO3: 32\nmEq/L, PCO2: 50 mmHg, BE: 5 saturação de O2: 91%, cloro: 90 mEq/L, K: 3,2 mEq/L. O\ntratamento desse paciente deve ser feito com:","options":{"A":"Administração de amônia oral e vitamina C.","B":"Solução fisiológica a 0,9% e administração de KCl.","C":"Administração de O2 e ventilação assistida.","D":"Solução de HCI e ventilação assistida.","E":"Administração de lactato de sódio."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-34991","number":"34991","sourceNumber":"34991","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre o íon potássio, é correto afirmar:","options":{"A":"É o ânion predominante no espaço intracelular.","B":"Salbutamol é eficaz para corrigir hipocalemia.","C":"Causas importantes de hipocalemia são a injúria traumática aguda e o período pós-operatório\nimediato.","D":"Pequenas alterações nos níveis de potássio intracelular determinam grandes repercussões nos\nsistemas cardiovascular e neuromuscular.","E":"Na hiperpotassemia, predominam queixas cardíacas e neurológicas."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-35002","number":"35002","sourceNumber":"35002","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, sexo feminino, 25 anos de idade, com fissura anal posterior crônica, já tendo\nfeito uso de formadores de bolo fecal, nifedipina e nitrato tópicos anais, sem melhora. Realizou\nmanometria anorretal com acentuada hipertonia esfincteriana. São causas de acidose metabólica\ncom hiato aniônico normal, exceto:","options":{"A":"Perdas digestivas não gástricas;","B":"Acidose tubular renal;","C":"Nutrição parenteral total;","D":"Anastomoses ureterais;","E":"Acidose lática."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-27497","number":"27497","sourceNumber":"27497","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210U/dl, ALT:102U/dl\ngamaglutamiltransferase: 92U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82mg/dl. AntiHCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850mcg/dl. Anticorpos antimitocôndria, antimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. Após uma semana de tratamento, o\nionograma e a hemogasimetria arterial da paciente apresentaram os seguintes achados, pH: 7,3,\nPC02: 31mmHg, HC03: 19mEq/l, PaO²: 83mmHg, BE: -12, sódio sérico: 137mEq/l, CI: 104mEq/l, K:\n6,0mEq/l. O distúrbio metabólico apresentado é:","options":{"A":"acidose mista respiratória e metabólica, descompensada.","B":"acidose respiratória crônica agudizada, descompensada.","C":"acidose respiratória com alcalose metabólica, compensadas.","D":"acidose metabólica descompensada.","E":"acidose metabólica com alcalose respiratória, descompensada."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-27498","number":"27498","sourceNumber":"27498","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210 U/dl, ALT: 102\nU/dl gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2 g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82 mg/dl. AntiHCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850 mcg/dl. Anticorpos antimitocôndria,\nantimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. A paciente passou a apresentar onda T\napiculada no ECG. A medida mais imediata é:","options":{"A":"bicarbonato de sódio EV.","B":"nebulização com fenoterol.","C":"resina de troca iônica e manitol oral (sorcal).","D":"gluconato de cálcio EV.","E":"solução de glicose e insulina EV."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-13309","number":"13309","sourceNumber":"13309","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 37 anos de idade, com diagnóstico prévio de urolitíase, com dor lombar à\ndireita há 20 dias, fazendo uso de\ndiclofenaco, evoluiu há 48 horas com piora da dor abdominal,\ncom náuseas, vômitos e redução do volume urinário. Exames de laboratório mostram ureia: 120\nmg/dl, creatinina: 3,0 mg/dl, hemogasimetria arterial: pH: 7,33; HCO3: 11 mEq/l; PCO2: 26 mmHg,\nPaO2: 87 mmHg. BE: -4; Cl: 106 mEq/l, Na: 140 mEq/l, SaO2: 94%. K: 6,0 mEq/l; glicemia: 104\nmg/dl. Cálcio: 8,5 mg/dl. Sódio urinário em amostra isolada: 19 mEq/l. A ultrassonografia de\nabdome mostra dilatação pielocalicial à direita, sem outras alterações. O distúrbio acidobásico\napresentado é:","options":{"A":"acidose metabólica com acidose respiratória","B":"acidose metabólica parcialmente compensada","C":"acidose metabólica com alcalose respiratória","D":"alcalose respiratória hipercompensada","E":"alcalose respiratória parcialmente compensada"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215594","number":"215594","sourceNumber":"215594","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que apresenta o tratamento CORRETO para um paciente de 12\nanos, que apresenta íleo paralítico e ECG com onda U proeminente e inversão de onda T.","options":{"A":"Resina de troca de potássio (sorcal).","B":"Solução polarizante + salbutamol.","C":"Correção de sódio com NaCl 20%\n5 meq/Kcal/hora.","D":"Correção de potássio com cloreto de potássio 19,1% endovenoso."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-181181","number":"181181","sourceNumber":"181181","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O potássio é o principal íon intracelular, e o sódio o principal íon extracelular. Com\nbase\nnessas informações, assinale a alternativa\nINCORRETA em relação à Hipocalemia:","options":{"A":"Paralisia flácida com comprometimento respiratório pode ocorrer quando potássio esta abaixo de\n2 mmol/L.","B":"Hipermagnesemia pode ser a causa de hipocalemia refratária.","C":"No eletrocardiograma pode ocorrer depressão de onda T e ondas U.","D":"Sintomas clínicos são fadiga, fraqueza e íleo."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-157580","number":"157580","sourceNumber":"157580","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre os distúrbios hidroeletrolíticos e acidobásicos em cirurgia, podemos afirmar que:","options":{"A":"As causas de hipernatremia são: perda exagerada de água nos queimados, sudorese excessiva\nou estados febris, TCE com diabetes insipidus de\norigem central, insuficiência adrenal.","B":"As alterações eletrocardiográficas de hipercalemia são: onda U, achatamento de onda T,\ndepressão do segmento ST, arritmias.","C":"A principal causa de alcalose metabólica nos pacientes cirúrgicos é a hipovolemia, pois os rins,\nao tentarem reabsorver sódio, reabsorvem também bicarbonato.","D":"Na cetoacidose, insuficiência renal, intoxicações exógenas e acidose lática, o ânion-gap\nencontra-se diminuído."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-157682","number":"157682","sourceNumber":"157682","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Idosa com dificuldade de caminhar e de se alimentar foi trazida por familiares,\ndesidratada e muito prostrada. Utilizava\ncaptopril para controle de hipertensão, e já havia ocorrido\npreviamente aumento dos níveis de creatinina. Além de desidratação, foi suspeitado de\nhipercalemia. Diante de tal quadro clínico, assinale a alternativa que determina a gravidade\nimediata da hipercalemia.","options":{"A":"Alteração de repolarização ventricular, alterando também o complexo QRS.","B":"Redução de amplitudes de ondas T.","C":"Aumento da FC.","D":"BRE novo."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-139769","number":"139769","sourceNumber":"139769","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"PH = 7,38; PaCO2 = 12; BE = ? 23. Ao interpretar os dados desta gasometria arterial,\nqual é a condição mais provável para estes\nachados?","options":{"A":"Choque.","B":"Acidose metabólica compensada com alcalose respiratória.","C":"Alcalose respiratória compensada com acidose metabólica.","D":"Insuficiência ventilatória."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-139776","number":"139776","sourceNumber":"139776","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual das soluções abaixo apresenta concentrações de sódio e cloro mais próximas das\nobservadas no plasma?","options":{"A":"Plasma fresco congelado.","B":"Soro glicosado a 5%.","C":"Ringer lactato.","D":"Soro fisiológico a 0,9%."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-139748","number":"139748","sourceNumber":"139748","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual é o distúrbio hidroeletrolítico e ácido-básico MAIS comumente observado nos\ncasos de desidratação por vômitos\nincoercíveis?","options":{"A":"Acidose metabólica com hipocalemia.","B":"Alcalose metabólica e hipocloremia.","C":"Acidose metabólica e hipercloremia.","D":"Alcalose metabólica e hipercalemia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-139773","number":"139773","sourceNumber":"139773","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Quadros de desequilíbrio eletrolítico podem se tornar graves e ameaçar a vida. Das\nalternativas apresentadas, aponte aquela que PODE ser considerada inadequada.","options":{"A":"Para fins de conduta clínica, não é o potássio corporal total que determina a gravidade da\nalteração do potássio.","B":"Ventilação influencia no valor sérico do potássio.","C":"Outras situações metabólicas podem também alterar a repolarização, além de variações séricas\ndo potássio.","D":"Gluconato de cálcio abaixa os valores séricos do potássio."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-111927","number":"111927","sourceNumber":"111927","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Além do sistema tampão Bicarbonato ? Ácido Carbônico ? existem três outros sistemas\ntampões disponíveis no organismo e que estão nas alternativas abaixo. Assinale a alternativa que\nNÃO faz parte desse grupo.","options":{"A":"Hidrossulfetos ? Sulfatos.","B":"Hemoglobina reduzida ? Oxiemoglobina.","C":"Fosfato ácido ? Fosfato básico.","D":"Proteína ácida ? Proteína básica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-259717","number":"259717","sourceNumber":"259717","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher, 68 anos, com diagnósticos de hipotireoidismo, em uso de levotiroxina 75\nmcg/dia, e depressão, há sete dias em uso\nde sertralina 50mg/dia, é admitida no pronto-socorro\ncom sonolência e rebaixamento do sensório. Exame físico: estado geral regular, sonolenta,\ndesorientada, hidratada, incursões por minuto, Saturação de oxigênio 91% em ar ambiente; sem\noutras alterações. Exames: Hemoglobina 11,0 g/dL (Valor de referência (VR) > 12 g/dl),\nHematócrito 34%, (VR 36-48%), leucócitos 7500/mm³(3600-11000/mm³), plaquetas 250mil (VR\n150-450 mil), Ureia 40 mg/dL (VR 16-40 mg/dl), Creatinina 0,8 mg/dL (VR 0,6-1,2 mg/dl), sódio\nsérico 113 mEq/L (VR 135-145 mEq/L), potássio sérico 4,0 mEq/L (VR 3,5-5,5 mEq/L), TGO 16U/L\n(5-40 U/L), TSH 3,5 mU/L (VR 0,4 a 4,5 mU/L), sódio urinário 80 mEq/L; eletrocardiograma,\nradiografia de tórax e tomografia computadorizada de crânio: sem alterações. Diante dos aspectos\napresentados, qual provável fator desencadeante do quadro clínico e que conduta deve ser\ninstituída?","options":{"A":"hipotireoidismo ? solução de NaCl 3% 20 ml/h e ajuste da dose de levotiroxina.","B":"hipotireoidismo ? solução de NaCl 0,9% 250 ml/h e ajuste da dose de levotiroxina.","C":"uso de sertralina ? solução de NaCl 3%, via endovenosa, 20 ml/h e suspensão da medicação.","D":"uso de sertralina ? solução de NaCl 0,9%, via endovenosa, 250 ml/h e suspensão da\nmedicação."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-234041","number":"234041","sourceNumber":"234041","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um senhor de 57 anos, diabético e hipertenso mal controlado de longa data, portador\nde doença arterial periférica e aterosclerose\ndifusa é acompanhado por doença renal crônica não\ndialítica classificada como estágio G2A3. Ele comparece em consulta de retorno com queixa de dor\nem região de segundo metacarpo e região interfalangiana proximal. Realizou radiografia (imagens a\nseguir). Cálcio iônico = 1,04 (VR = 1,1?1,4 mmil/L); fósforo = 6,5 mg/dl (VR = 2,5?4,5 mg/dl); PTH =\n354 pg/dl (VR = 10?60 pg/dl). LEGENDA: VR = Valor de Referência; PTH = Paratormônio. Qual\nmedicação poderia ter prevenido o surgimento da lesão na IMAGEM 1 se iniciada precocemente e\nqual poderia precipitar a lesão da IMAGEM 2, respectivamente?","options":{"A":"Acetato de cálcio e lanthanum.","B":"Carbonato de cálcio e sevelâmer.","C":"Sevelâmer e carbonato de cálcio.","D":"Lanthanum e hidróxido de alumínio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-199725","number":"199725","sourceNumber":"199725","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, 68 anos, sexo masculino, hipertenso, foi admitido no pronto-socorro com\npneumonia grave. Nos exames admissionais, constavam: creatinina = 1,8 mg/dl (VR: 0,7?1,2);\nureia = 157 mg/dl (VR: 10?50) e potássio = 7,2 mEq/L (VR: 3,5?5,0). Foi, então, realizado\neletrocardiograma, que evidenciou presença de onda T apiculada difusamente, encurtamento do\nintervalo QT e achatamento da onda P. LEGENDA: VR = Valor de Referência. Qual é o mecanismo\nde ação do primeiro medicamento a ser administrado nesse paciente?","options":{"A":"Estimular a caliurese.","B":"Estabilizar a membrana miocárdica.","C":"Trocar cálcio por potássio no trato gastrointestinal.","D":"Translocar potássio do meio extracelular para o intracelular."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-172974","number":"172974","sourceNumber":"172974","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem de 35 anos, 70 kg, alcoolista, recém-admitido na UTI com diagnóstico de\npancreatite grave. O quadro clínico é de\nletargia, muita dor abdominal, vômitos incontroláveis há 48\nhoras e dieta zero. Enquanto aguardava vaga de UTI, foi hidratado na emergência, nas últimas 24\nhoras, com soro glicosado 5%, 2.500 ml. Solicitados exames laboratoriais, chama a atenção sódio\nsérico = 120 mEq/L. Diante do exposto, qual o deficit de sódio desse paciente considerando uma\nmeta de sódio de 140 mEq/L?","options":{"A":"420 mEq.","B":"630 mEq.","C":"840 mEq.","D":"1.400 mEq."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-172965","number":"172965","sourceNumber":"172965","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente internado, devido febre de origem obscura e fadiga. Exame físico apresentava\nPA = 120/80 mmHg, FC = 100 bpm, T = 38,5°C,\ne ausculta cardíaca com estalido e sopro\nmesotelessistólico em foco mitral. Os exames evidenciaram leucocitose com desvio para esquerda,\nCr = 0,9 mg/dl (VR: 0,8-1.3 mg/dl), provas de função hepática e glicemia normais e hemocultura\npositiva em duas amostras. Foi tratado com gentamicina e ampicilina endovenosas. No 9º dia de\nterapia, apresentava-se hemodinamicamente estável, assintomático, afebril. Novos exames\nlaboratoriais revelaram: Ur = 70 mg/dl (VR: 16-40 mg/dl), Cr = 2,2 mg/dl (VR: 0,8-1.3 mg/dl), Na =\n143 mg/dl (VR: 135-145 mg/dl), K = 3,8 mEq/L (VR: 3,5-5,1 mEq/L). Sumário de urina: proteína\n(+/4+) e presença de cilindros granulares. Legenda: PA: pressão arterial; FC: frequência cardíaca;\nT: temperatura; Cr: creatinina; Ur: ureia; Na: sódio; K: potássio; VR: valor de referência.\n\nConsiderando a complicação renal mais provável apresentada pelo paciente, qual alteração é\ngeralmente encontrada nessa condição?","options":{"A":"Hipermagnesemia.","B":"Densidade urinária > 1020.","C":"Fração de excreção de sódio > 1 %.","D":"Diminuição do complemento sérico."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-126948","number":"126948","sourceNumber":"126948","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Diversos pacientes internados em unidade de terapia intensiva desenvolvem distúrbios\ndo equilíbrio acidobásico. O correto diagnóstico\ndestes distúrbios é fundamental para a instituição\nde terapêuticas apropriadas. Paciente masculino, 65 anos, internado na UTI, em ventilação\nmecânica, no 1º pós-operatório de gastrectomia total. Permanece instável hemodinamicamente,\nmesmo após reposição volêmica. Na gasometria arterial: pH = 7,21; PaCO2 = 35 mmHg; HCO-3 =\n18 mEq/L; BE = -8 mEq/L; PaO2 = 170 mmHg (FIO2 40%); Na+ = 130 mEq/L; K+ = 4 mEq/L; Cl- =\n\n102 mEq/L. Hb 8,0 g/dl e SvO2 75%. Sobre esse caso, assinale a alternativa CORRETA.","options":{"A":"Trata-se de acidose mista e o tratamento com bicarbonato está recomendado.","B":"A hiper-hidratação com solução salina a 0,9% pode levar à piora da acidose metabólica.","C":"Trata-se de acidose metabólica hiperclorêmica e o tratamento deve se basear na correção da\ninstabilidade hemodinâmica com drogas vasoativas.","D":"Como o paciente permanece instável hemodinamicamente após reposição volêmica, a causa\nmais provável da acidose é anemia e a transfusão de concentrado de hemácias está indicada."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-126999","number":"126999","sourceNumber":"126999","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Você é chamado para avaliar idoso que está em observação na emergência com\nquadro de diarreia há 48h. Seu peso é 50 kg\ne tem antecedentes de hipertensão arterial sistêmica e\netilismo. No momento, ele queixa-se de sede. Nas últimas 6h, seu débito urinário foi de 100 ml. Ao\nexame físico, é emagrecido, tem mucosas secas, frequência cardíaca de 108 bpm e pressão\narterial de 110 x 60 mmHg. Avaliação laboratorial mostrou ureia de 40 mg/dl, creatinina de 1,0\nmg/dl, potássio de 3,0 mEq/L, tempo de protrombina 40% e albumina 2,5 g/dl. Qual dos itens\nabaixo contém o melhor fluido para ser administrado por via endovenosa, no momento atual desse\npaciente?","options":{"A":"Albumina.","B":"Hidroxietilamido.","C":"Solução de Ringer lactato.","D":"Plasma fresco congelado."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-81247","number":"81247","sourceNumber":"81247","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 47 anos foi admitido em serviço de emergência terciária com abdome\nagudo e sepse grave. Durante o tratamento\ncirúrgico, constatou-se diverticulite aguda com\nperitonite fecal. No pós-operatório, realizado na UTI, manteve-se em estado grave, com acidose\nmetabólica grave, anúria e níveis crescentes de creatinina. Em decorrência de Insuficiência Renal\nAguda (IRA), está em curso de hemodiálise. Considerando a situação descrita, qual alternativa\ncorresponde ao distúrbio hidroeletrolítico mais comumente relacionado à hemodiálise?","options":{"A":"Hipocalemia.","B":"Hipercalemia.","C":"Hiponatremia.","D":"Hipernatremia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-65786","number":"65786","sourceNumber":"65786","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem de 80 anos apresenta, há três dias, quadro de vômitos incoercíveis em\ninúmeros episódios ao dia. Não consegue se\nalimentar nem ingerir líquidos. Encontra-se apático,\ncom diurese bastante diminuída nas últimas 24 horas. O paciente foi hidratado com solução salina\nisotônica e suplementação com KCl a 10%. Qual o indicador de que o paciente foi adequadamente\nreanimado?","options":{"A":"pH urinário ácido.","B":"pH urinário alcalino.","C":"Potássio sérico > 4 mEq/L.","D":"Cloreto sérico > 100 mEq/L.","E":"pH do sangue arterial < 7,4."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-65752","number":"65752","sourceNumber":"65752","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 80 anos, com queixa de dor epigástrica há 6 meses, há cerca de 3 dias\ncomeçou a apresentar vômitos, inicialmente pós-prandiais e atualmente com conteúdo claro, não\nbilioso em vários episódios e sem melhora com tratamento medicamentoso. O exame de raio X de\nabdome apresenta imensa distensão gástrica com pobreza de imagens de gases no restante da\ncavidade abdominal. Considerando os distúrbios hidroeletrolíticos e acidobásicos mais frequentes\nnessa situação, qual das seguintes propostas de reposição hidroeletrolítica é mais aplicável?","options":{"A":"Ringer Simples seguida de NaCl 19,1%.","B":"Ringer Lactato seguido de salina isotônica.","C":"Salina hipotônica seguida de Ringer Lactato.","D":"Salina isotônica seguida de solução com KCl.","E":"Salina hipertônica seguida de Ringer Lactato."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-51267","number":"51267","sourceNumber":"51267","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No pós-operatório de uma cirurgia abdominal, um homem de 42 anos, 65 kg, sem\ncomorbidades associadas à patologia cirúrgica, foi inadvertidamente hiperidratado com solução\nfisiológica de NaCl a 0,9%. Considerando-se que esse paciente apresenta função renal normal,\nqual substância o seu organismo secreta para manter a homeostase da água extracelular?","options":{"A":"Aldosterona.","B":"Vasopressina.","C":"Noradrenalina.","D":"Peptídios natriuréticos."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-51225","number":"51225","sourceNumber":"51225","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem de 46 anos, pedreiro, foi diagnosticado como hipertenso há 2 meses. Seu pai e\ndois irmãos mais velhos são hipertensos. O paciente está em uso de enalapril (20 mg/dia). Ao\nexame, apresentou pressão 150 x 90 mmHg em ambos os braços e 160 x 100 mmHg em membros\ninferiores. Os exames complementares apresentaram: creatinina 0,9 mg/dl; potássio sérico 3,2\nmEq/L; sódio sérico 142 mEq/L; colesterol total 250 mg/dl; LDL 150 mg/dl; triglicerídeos 200 mg/dl;\nglicemia 110 mg/dl. O eletrocardiograma revelou sobrecarga de ventrículo esquerdo. A radiografia\nde tórax não evidenciou alteração. Qual achado sugere hipertensão arterial secundária?","options":{"A":"Potássio sérico baixo.","B":"Sódio sérico elevado.","C":"ECG com sobrecarga de ventrículo esquerdo.","D":"Pressão arterial mais alta nos membros inferiores."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-45395","number":"45395","sourceNumber":"45395","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São alterações eletrocardiográficas que podem ser encontradas em pacientes com\nhipercalemia:","options":{"A":"Onda T alta, apiculada, estreita e simétrica.","B":"Onda T alta de base larga e assimétrica.","C":"Onda P aumentada e complexo QRS estreito.","D":"Inversão de onda T.","E":"Onda P alta, apiculada, estreita e simétrica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-45396","number":"45396","sourceNumber":"45396","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Pacientes com quadro clínico característico de obstrução intestinal alta podem\napresentar:","options":{"A":"alcalose metabólica hiperclorêmica e hipocalêmica.","B":"acidose metabólica hipoclorêmica e hipocalêmica.","C":"acidose metabólica hiperclorêmica e hipocalêmica.","D":"alcalose metabólica hipoclorêmica e hipocalêmica.","E":"alcalose metabólica hipoclorêmica e hipercalêmica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-36977","number":"36977","sourceNumber":"36977","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A hidratação adequada e a reposição de eletrólitos no pós-operatório são fundamentais\npara a recuperação do paciente. Sobre a\ncomposição de água e eletrólitos no organismo, qual a\nopção correta?","options":{"A":"Sódio, cloro e bicarbonato perfazem 90% das partículas osmoticamente ativas do líquido\nextracelular.","B":"O magnésio é o principal íon positivo osmoticamente ativo do meio intracelular.","C":"A porcentagem de água corporal total aumenta com a idade.","D":"O trato gastrointestinal é a principal via de controle do sódio corporal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-32541","number":"32541","sourceNumber":"32541","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na maioria dos adultos, a água é responsável por 45 a 60% do peso corporal total.\nConsidere a notação seguinte: ACT = água corporal total; AIC = água intracelular; AEC = água\nextracelular. Diante do exposto, é correto afirmar:","options":{"A":"AEC > AIC.","B":"AIC = ACT + AEC .","C":"AEC responde por 20% do peso corporal.","D":"ACT das mulheres > ACT dos homens.","E":"As membranas celulares são seletivamente permeáveis à água."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-32546","number":"32546","sourceNumber":"32546","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a bioquímica e fisiologia da regulação acidobásica, é correto afirmar que:","options":{"A":"A alcalemia é a perturbação grave mais comum no equilíbrio acidobásico.","B":"A flutuação tolerável de H+ é bem mais aceita pelo organismo que as flutuações dos níveis\nséricos de Na+, K+ e Cl-.","C":"As proteínas são importantes tampões na AEC (Água Extracelular).","D":"O principal tampão na AEC (Água Extracelular) e na AIC (Água Intracelular) é o bicarbonato.","E":"A concentração de H+ na AEC e AIC é maior em relação aos outros solutos (Na+, K+, CI-\ne HCO3-)."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-32549","number":"32549","sourceNumber":"32549","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre os distúrbios acidobásicos, podemos afirmar corretamente que:","options":{"A":"As células renais captam o lactato e um próton e os convertem de volta em glicose, em um\nprocesso enzimático denominado gliconeogênese.","B":"Fístula duodenal ou diarreia podem fazer perder bicarbonato o suficiente para induzir acidemia.","C":"O nível de gás sanguíneo arterial de um paciente em cetoacidose diabética mostra alto pH e\nconcentração de bicarbonato deprimida.","D":"A cetoacidose diabética geralmente cursa com hipercalemia associada.","E":"Nos pacientes alcoólicos que desenvolvem uma síndrome de cetoacidose o\nmecanismo fisiopatológico é a deficiência de insulina."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-37000","number":"37000","sourceNumber":"37000","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 30 anos é avaliado por sonolência. Refere que há 2 semanas vem usando\nfurosemida por conta própria (para emagrecer ? sic) e há alguns dias apresenta astenia crescente.\nO exame físico evidencia PA = 90 x 40 mmHg, pulso = 105 ppm, sem outras alterações. Os exames\nlaboratoriais mostram: Gasometria arterial - pH = 7,57 ; PaCO2 = 49 mmHg ; HCO3 = 45 mmol/L ;\nPaO2 = 96 mmHg ; SaO2 = 96% ; Creatinina sérica = 1,5 mg/dl; Sódio sérico = 140 mmol/L; Cloro\nsérico = 90 mmol/L; Cloro urinário = 10 mmol/L. Os demais exames resultam sem alterações\nsignificativas. Qual a conduta mais apropriada?","options":{"A":"Iniciar droga vasoativa","B":"Iniciar infusão de solução salina isotônica.","C":"Iniciar infusão de HCl.","D":"Iniciar infusão de NaCl a 3%."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-30913","number":"30913","sourceNumber":"30913","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 45 anos alcoolista, no quarto dia de internação hospitalar com diagnóstico\nde pancreatite aguda, apresenta-se apático,\nsonolento, pele fria, com pressão arterial de 85 x 40\nmmHg, frequência cardíaca de 145 bpm, diurese de 20 ml na última hora. Exames laboratoriais:\ngasometria arterial pH = 7,15; PaO2 = 55 mmHg; PaCO2 = 28 mmHg; bicarbonato = 15 mEq/L;\nexcesso de base = -9; SatO2 = 93%; Na+ = 145 mEq/L ; K+ = 6,1 mEq/L; Cl- = 118 mEq/L. Qual a\nmelhor hipótese diagnóstica?","options":{"A":"Alcalose hiperclorêmica.","B":"Acidose metabólica.","C":"Acidose metabólica com ânion-gap diminuído.","D":"Alcalose respiratória.","E":"Acidose metabólica e hipoxemia."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-24298","number":"24298","sourceNumber":"24298","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A água é o principal componente da massa corporal e tem múltiplos compartimentos no\nser humano. Sobre essa distribuição, assinale a alternativa FALSA:","options":{"A":"A água corporal total constitui entre 40 e 60% do peso na maioria dos adultos.","B":"A obesidade diminui a proporção de água corporal total.","C":"O compartimento intracelular é o maior e é estimado ter 55% da água corporal total.","D":"A mulher tem uma maior proporção de água corporal quando comparada com o homem."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-24299","number":"24299","sourceNumber":"24299","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Hipercalemia de início rápido causa arritmias cardíacas que podem ser fatais. A\nprincipal causa desse distúrbio é:","options":{"A":"Pós-operatório de grandes procedimentos com rabdomiólise","B":"Cetoacidose diabética","C":"Disfunção ou falência renal","D":"Grandes queimados"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-27705","number":"27705","sourceNumber":"27705","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando que o tratamento da hiponatremia aguda é consideravelmente diferente\ndo tratamento da hiponatremia crônica, responda: a\npartir de quanto tempo a hiponatremia é\nconsiderada crônica?","options":{"A":"24h","B":"48h","C":"72h","D":"1 semana","E":"2 semanas"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-24323","number":"24323","sourceNumber":"24323","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Karla, 12 anos, com quadro de insuficiência renal aguda, realizou um eletrocardiograma\nque evidenciou uma diminuição do intervalo QT,\nassociada a uma onda T alta e apiculada, sinal de\nrepolarização ventricular precoce. Posteriormente, ocorreu achatamento da onda P, alargamento de\nQRS, até o desaparecimento da onda P. Com essa patologia, o provável distúrbio que gerou as\nalterações eletrocardiográficas foi:","options":{"A":"Hipercalemia","B":"Hipocalemia","C":"Hipomagnesemia","D":"Hiperglicemia"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-25402","number":"25402","sourceNumber":"25402","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Os pacientes que menos toleram hiponatremia e que devem ser tratados mesmo\nnos casos leves são aqueles que apresentam as\nseguintes patologias:","options":{"A":"Trauma cranioencefálico","B":"Intoxicação aguda pela água (ex. RTU próstata)","C":"Cirrose hepática com ascite refratária","D":"Síndrome inapropriada do hormônio antidiurético","E":"Insuficiência Renal Crônica"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-27786","number":"27786","sourceNumber":"27786","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um bebê de 2 meses do sexo feminino, recém-diagnosticada com estenose pilórica é\nadmitida na unidade de pediatria do hospital de sua comunidade para administração de fluidos\nintravenosos por causa de vômitos prolongados e incapacidade de manter ingestão oral adequada.\nAssinale a alternativa que mostra o melhor resultado da análise de eletrólitos séricos e gasometria\narterial deste paciente.","options":{"A":"Hipercalemia","B":"Hipernatremia","C":"Hipocloremia","D":"Acidose metabólica","E":"Acidose respiratória"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-25364","number":"25364","sourceNumber":"25364","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 59 anos, obesa (IMC 33), vem em uso de várias medicações para\nemagrecer, dentre elas Sibutramina,\nFluoxetina e Espironolactona, orientada por uma ?amiga?.\nComparece ao ambulatório com quadro de letargia, voz arrastada e quedas frequentes. Traz alguns\nexames de laboratório que revelaram Na = 112 mEq/L / TSH = 3,54 mU/L / K = 5,1 mEq/L. O\nexame físico mostrou leve ataxia de marcha com reflexos tendinosos, tônus e força muscular\nnormais. Não havia edema ou desidratação e os sinais vitais eram normais. Marque a afirmação\ncorreta quanto ao caso:","options":{"A":"Trata-se de caso compatível com síndrome de Serotonina onde a hiponatremia se acompanha\nde tônus muscular e reflexos normais.","B":"É um caso típico de hipotireoidismo por falência hipofisária secundária à associação de\nFluoxetina e Sibutramina.","C":"Se a osmolalidade sérica efetiva for menor que 275 mOsm/Kg de água e o ácido úrico sérico for\nmenor que 4 mg/dl o melhor diagnóstico é Secreção Inapropriada de ADH (SIADH).","D":"Mesmo que o cortisol basal seja normal o melhor diagnóstico é Insuficiência Adrenal causada\npela Espironolactona.","E":"O quadro é compatível com Diabetes Insipidus, que se confirma com melhora da hiponatremia\napós uso de DDAVP."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-9019","number":"9019","sourceNumber":"9019","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Dependendo da rapidez da queda da concentração plasmática do sódio, hiponatremia\npode causar convulsões e coma. Hiponatremia é\nclassificada como severa quando:","options":{"A":"Sódio sérico menor que 130 mEq/L","B":"Sódio sérico menor que 120 mEq/L","C":"Sódio sérico menor que 135 mEq/L","D":"Sódio sérico menor que 125 mEq/L"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-13395","number":"13395","sourceNumber":"13395","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Larissa Aparecida, 18 anos, jogadora de basquete da seleção do colégio São João,\nrefere fraqueza e fadiga com muita frequência.\nPreocupada com a possibilidade de estar doente,\nresolveu fazer uma consulta médica. Exame físico sem anormalidades. Exames laboratoriais: Os\nresultados dos exames de sangue e urina solicitados são relatados abaixo:\n\nSangue: Hb 12.00 g/dL Ht 46%\n\nSuor: 25 mmol/L\n\nNa+ 141 mEq/L - Cl? 85 mEq/L - K+ 2.1 mEq/L - HCO3 ? 35 mEq/L\nUrina - Na+ 80 mEq/24 h - K+ 170 mEq/24 h\n\nÍndice de massa corporal - -20 kg/m2.\n\nQual o diagnóstico mais provável fundamentado exclusivamente no exame físico e nos exames\nlaboratoriais realizados?","options":{"A":"Deficiência de aldosterona.","B":"Ansiedade reacional a esportes 2eróbicos com hiperventilação.","C":"Cetoacidose diabética.","D":"Ingestão de anabolizantes esteroides.","E":"Uso indevido de diuréticos."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-8826","number":"8826","sourceNumber":"8826","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual das alternativas é causa de acidose metabólica com anion gap normal?","options":{"A":"Cetose.","B":"Intoxicação por salicilatos.","C":"Uremia.","D":"Sepse.","E":"Fístula entérica."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-8834","number":"8834","sourceNumber":"8834","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em um paciente com síndrome de obstrução pilórica, esperamos encontrar os\nseguintes distúrbios eletrolíticos e acidobásicos:","options":{"A":"Hipocalemia, hipomagnesemia e alcalose metabólica.","B":"Hipocloremia, hipocalemia e alcalose metabólica.","C":"Hiponatremia, hipocalemia e acidose metabólica.","D":"Hipocalemia, hipercloremia e alcalose metabólica.","E":"Hipocloremia, hipomagnesemia e alcalose metabólica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-6941","number":"6941","sourceNumber":"6941","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Lactente masculino, 6 semanas, apresenta desde os 15 dias de vida vômitos não\nbiliosos, em jato, perda de peso e ondas peristálticas visíveis. O distúrbio mais provável de ser\nencontrado é:","options":{"A":"Acidose metabólica hipocalêmica.","B":"Alcalose metabólica hiponatrêmica.","C":"Alcalose metabólica hipoclorêmica.","D":"Acidose metabólica hiperclorêmica.","E":"Alcalose mista hipercalêmica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-6961","number":"6961","sourceNumber":"6961","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com história de litíase renal de repetição chega ao Pronto-Socorro com\ndispneia. Exames de urgência mostram: sódio 135\nmEq/L, creatinina 0,9 mg/dL, potássio 1,8\nmEq/L, cloro 115 mEq/L, pH 7.08, PaCO2 40 mmHg, bicarbonato 11 mEq/L. Marque a alternativa\ncorreta:","options":{"A":"O ânion gap do paciente está normal, devendo-se pedir um gap urinário que, se estiver positivo,\nindica perda de bicarbonato na urina.","B":"O ânion gap do paciente está normal, devendo-se pedir um gap urinário que, se estiver positivo,\nindica perda de bicarbonato nas fezes.","C":"O ânion gap do paciente está normal, indicando intoxicação exógena, cetoacidose diabética ou\nacidose láctica.","D":"O ânion gap do paciente está aumentado, sendo necessário pedir o gap urinário para prosseguir\nna investigação etiológica.","E":"Trata-se de acidose metabólica e respiratória mista, sendo que apresenta ânion gap aumentado,\nprovavelmente por retenção de ácidos pela IRA."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-13479","number":"13479","sourceNumber":"13479","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança, 3 anos que há 2 dias sofreu traumatismo crânio-encefálico tem os seguintes\ndados laboratoriais: Sódio sérico 121mEq/L,\ndensidade urinária elevada, sódio urinário alto e baixa\nosmolaridade. Nesse caso a conduta mais apropriada é:","options":{"A":"Correção da hiponatremia com NaCl 3%.","B":"Expansão com 50mL/Kg de Soro Fisiológico 0,9%.","C":"Expansão com Soro Fisiológico 0,9% e Soro glicosado 5% 1:1.","D":"Uso de diuréticos de alça.","E":"Restrição Hídrica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-322155","number":"322155","sourceNumber":"322155","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma mulher de 71 anos, com histórico de DPOC, procura atendimento médico com\nqueixa de falta de ar. O resultado da\ngasometria arterial é o seguinte: ? pH: 7,25; ? CO?: 62; ? BIC:\n\n35. Nesse caso, é CORRETO afirmar que:","options":{"A":"Trata-se de uma alcalose metabólica.","B":"A gasometria está normal.","C":"Trata-se de uma acidose metabólica.","D":"Trata-se de uma acidose respiratória crônica, provavelmente agudizada.","E":"Está indicada reposição de bicarbonato EV."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-305318","number":"305318","sourceNumber":"305318","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre o Ânion-Gap (AG) e sua condição mais esperada nas causas de acidose\nmetabólica, assinale a alternativa INCORRETA.","options":{"A":"AG plasmático normal ocorre nas perdas de bicarbonato sem perda de cloro, como ocorre nas\ndiarreias e fístulas.","B":"AG plasmático normal ocorre na acidose tubular renal.","C":"AG plasmático aumentado ocorre na hipoalbuminemia, pois a albumina contribui em grande\nparte para reduzir o AG plasmático.","D":"AG plasmático aumentado ocorre quando há adição de carga ácida ao organismo, como ácidos\norgânicos (cetoacidose), acidose lática e na uremia.","E":"AG plasmático diminuído ocorre na presença de cátions não mensuráveis, como na\nhiperlipidemia, na qual se superestima a concentração de cloro."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-261242","number":"261242","sourceNumber":"261242","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente de 42 anos de idade evolui com convulsões de início recente do tipo\nparciais complexas. Foi realizada uma tomografia\nde crânio com contraste que evidenciou uma\nmassa em lobo parietal direito, com contornos regulares, sugestivo de neoplastia primária. Durante\na internação, foram efetuadas mais três tomografias com contraste para verificar a existência de\noutros sítios de tumor cerebral. Após 72 horas de internação, apresentou piora da diurese com\nureia = 280 mg/dl e creatinina = 1,4 mg/dl. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. O paciente provavelmente apresenta insuficiência renal\ndo tipo pré-renal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-349734","number":"349734","sourceNumber":"349734","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 68 anos, acompanhada da filha, foi encaminhada para nefrologia pela\nunidade básica de saúde (UBS) devido à alteração\nno exame de creatinina. Trouxe exames\nlaboratoriais que evidenciavam: Hb 8,7g/L; Creatinina 2,8 mg/dL; Ureia 92 mg/dL; Gasometria\narterial: pH 7,3, Bicarbonato 18 mmol/L, Na 140 mmol/L, K 5.2 mmol/L. Um exame realizado há 4\nanos já evidenciava creatinina sérica basal de 2,3 mg/dL. O peso da paciente é de 56 Kg.\n\nConforme o caso apresentado, assinale a alternativa correta.","options":{"A":"Está contraindicada vacina contra hepatite B para essa paciente.","B":"O clearence de creatinina pela equação de Cockcroft-Gault é de 20 ml/min. A paciente está em\nestágio 3 de doença renal crônica.","C":"Essa paciente não deveria ter sido encaminhada para a nefrologia, devendo ser acompanhada\nsomente em UBS.","D":"O tratamento para essa paciente deve ser classificado como conservador, pois ela está entre os\nestágios 1 e 3 de doença renal crônica.","E":"O clearance de creatinina pela equação de Cockcroft-Gault é de 17 ml/min. A paciente está em\nestágio 4 de doença renal crônica."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-365656","number":"365656","sourceNumber":"365656","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente de 35 anos de idade iniciou, sem prescrição médica, uso de furosemida\nem fórmula manipulada para redução do peso.\nProcurou o pronto-socorro com queixa de fraqueza\nmuscular, sendo observado potássio sérico de 2,7 mEq/L. A melhor conduta nesse caso, além da\nsuspensão da fórmula, é","options":{"A":"reposição de potássio via oral.","B":"prescrição de gluconato de cálcio.","C":"reposição de potássio endovenoso.","D":"hemodiálise de urgência."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-298850","number":"298850","sourceNumber":"298850","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. O principal distúrbio hidroeletrolítico que o paciente pode\napresentar no quadro de diarreia intensa é a alcalose metabólica hipopotassêmica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-298862","number":"298862","sourceNumber":"298862","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Nesse paciente,\na realização de diálise deve ser feita em um período de tempo mais curto e com maior\nultrafiltração.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274339","number":"274339","sourceNumber":"274339","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com SIADH (Síndrome de Liberação Inadequada de Hormônio Antidiurético) é\natendido no hospital com quadro de hiponatremia moderada crônica. Sobre essa condição e seu\ntratamento, é CORRETO afirmar que:","options":{"A":"O tratamento deve ser realizado com infusão rápida de soro glicosado 5%.","B":"A correção lenta do sódio pode gerar mielinólise pontina central.","C":"O índice de aumento do sódio sérico deve ser de no mínimo 12 mEq/kg por dia.","D":"Na hiponatremia prolongada, também pode haver depleção de potássio com necessidade de\nreposição.","E":"A taxa de correção do sódio deve ser de pelo menos 0,5 mEq/L por hora para evitar mielinólise\npontina."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274365","number":"274365","sourceNumber":"274365","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Durante visita à enfermaria, um médico verificou que um paciente internado com quadro\nde pneumonia evoluiu com piora clínica, sendo\nconstatadas taquidispneia, hipotensão arterial,\ntaquicardia, queda da saturação de oxigênio e oligúria nas últimas 24 horas. Após receber o\ndiagnóstico de choque séptico, o paciente foi encaminhado para a unidade de terapia intensiva.\n\nDepois de hidratação vigorosa e suporte com oxigênio, o paciente apresentou melhora e foram\nfeitos exames que mostraram alterações\nácido-base. Os exames estão descritos a seguir:\n(Hematócrito: 35%, leucócitos: 12.800, bastões: 7%, pH: 7,15, PaO2: 95mmHg, pCO2: 54mmHg,\nHCO3: 27,3mmol/L, lactato: 2,2mmol/dL, albumina: 2,9mg/dl, potássio: 5,1mmol/L, sódio: 146\nmmol/L, cálcio: 9,4 mmol/L, Cr: 2,2mg/dL, Ureia: 95 mg/dL). Considerando as informações\nmencionadas, a respeito do caso clínico apresentado, assinale a alternativa correta.","options":{"A":"A acidose é metabólica e o paciente deve ser encaminhado para hemodiálise com urgência.","B":"A acidose é respiratória e o tratamento é intubação endotraqueal.","C":"O distúrbio ácido-base, nesse caso, é secundário à insuficiência renal do paciente, já que o\nsistema compensatório do bicarbonato não está adequado.","D":"Não existe distúrbio ácido-base puro, portanto para o tratamento do quadro séptico deve ser\nindicado escalonamento de antibioticoterapia para amplo espectro.","E":"A acidose é respiratória, parcialmente compensada, e deve ser tratada como parte do manejo no\nquadro séptico."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274373","number":"274373","sourceNumber":"274373","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 55 anos é admitido na UTI devido a quadro de choque séptico decorrente\nde infecção de trato urinário. Na admissão, o\npaciente está com hipotensão (PA:100/60mmHg) e\nbradicardia (FC:50bpm), com necessidade de uso de droga vasoativa. Ao exame físico,\n\nconstatam-se palidez cutânea, ausculta pulmonar sem alterações e cardíaca com som de atrito. Foi\nrealizada tomografia de abdome com laudo de abcesso em rim direito. O ecocardiograma mostrou\nsinais de pericardite. Os exames de laboratório demonstraram alteração de função renal e são\napresentados a seguir: (Hemoglobina: 12,6mg/dL, hematócrito: 35,9%, bastões: 18%, uréia: 180\nmg/dL, creatinina: 2,8mg/dL, sódio: 138mEq/dL, potássio: 4,7mEq/dL, ph:7,38, pCO?: 40mmHg,\npO?: 86mmHg, HCO?: 20mmol/L, BE:-3, lactato: 1,2mMol/dL, SvcO2:50). Sobre esse quadro,\nassinale a alternativa correta.","options":{"A":"O uso de droga vasoativa deve ter provocado a insuficiência renal por mecanismo de\nvasoconstrição de arteríola eferente.","B":"A avaliação da nefrologia deve indicar diálise devido à presença de pericardite.","C":"A ausência de acidose, a hipercalcemia e a hipercalemia contraindicam hemodiálise no\nmomento.","D":"O choque séptico é o protótipo do choque distributivo e tem evolução inexorável para\ninsuficiência renal, por isso a conduta é expectante.","E":"A avaliação nefrológica deve indicar hemodiálise como depuração dos fatores inflamatórios\ndecorrentes do choque."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-239256","number":"239256","sourceNumber":"239256","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente de 52 anos de idade, hipertenso e diabético, vai ao consultório do\ncirurgião com queixa de emagrecimento e\nsangramento vivo pelo ânus há seis meses. Nega\nalterações de diurese ou hábito intestinal. Ao exame físico, o abdome estava pouco distendido, sem\nmassas palpáveis. Realizou-se toque retal, observando-se esfíncter normotônico, sem lesões\npalpáveis, sem hemorroidas, com sangue vivo em dedo de luva. O paciente apresenta exames\nlaboratoriais realizados na UBS que identificam Hb = 9,3, leucócitos = 11.000, plaquetas = 340.000,\nNa = 138, K = 4,2, U = 77 e Cr = 1,94. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. Se a disfunção renal for de causa\n\npós-renal por infiltração tumoral, deve-se indicar hemodiálise imediatamente, pois a presença de\nneoplasia contraindica a realização de procedimentos de desobstrução da via urinária, como a\npassagem de cateter duplo J.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-239274","number":"239274","sourceNumber":"239274","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Com base nos dados clínicos, há indicação de hemodiálise para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-211932","number":"211932","sourceNumber":"211932","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente hipertenso e diabético de 58 anos de idade vai ao consultório médico com\ncomprometimento de atividades de vida diária, queda no estado nutricional e dificuldades de\nhomeostasia hidroeletrolítica. O paciente apresenta-se com TGF (ml/min/1,73 m²) < 15 e\nmanifestando convulsões tônico-clônicas, irritabilidade, pequenos sangramentos e elevação da\nureia (ureia = 342 mg/dl). No que se refere à terapêutica indicada nesse caso clínico, assinale a\nalternativa CORRETA:","options":{"A":"Enzima trocadora para baixar a ureia.","B":"Hidratação venosa com melhora da função pré-renal.","C":"Melhora do controle glicêmico com metformina e retirada de IECA e (ou) BRA.","D":"Retirada de anti-hipertensivos, com hidratação e espera de recuperação da função renal.","E":"Terapia renal substitutiva."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-154352","number":"154352","sourceNumber":"154352","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente H.L.S., 52 anos de idade, é levado ao pronto-socorro por familiares,\napresentando quadro de rebaixamento do nível de\nconsciência e de agitação psicomotora. Os\ninformantes negam antecedentes patológicos, uso de medicação contínua ou alergia aos fármacos\nhabituais. Na sala de emergência, após as medidas iniciais, o paciente segue retirando-se aos\nestímulos dolorosos, desorientado e com abertura ocular aos estímulos dolorosos; PA = 84 x 62\nmmHg; FC = 97 bpm. A análise gasométrica arterial apresenta como valores: pH = 7,15; HCO3 = 6\nmEq/L; PCO2 = 18 mmHg; Na+ = 135 mEq/L; Cl- = 114 mEq/L e K+ = 4,5 mEq/L. Considerando o\ncaso apresentado, assinale a alternativa que indica a pontuação na escala de Glasgow após as\nmedidas iniciais, a PCO2 esperada para o distúrbio gasométrico, o valor do hiato iônico e o\ndiagnóstico gasométrico final:","options":{"A":"Glasgow = 10; PCO2 = 17 mmHg; hiato iônico = 15; acidose metabólica simples com hiato iônico\nnormal.","B":"Glasgow = 11; PCO2 = 18 mmHg; hiato iônico = 16; acidose metabólica simples com hiato iônico\nnormal.","C":"Glasgow = 12; PCO2 = 16 mmHg; hiato iônico = 17; acidose metabólica mista com hiato iônico\naumentado.","D":"Glasgow = 9; PCO2 = 15 mmHg; hiato iônico = 10; acidose metabólica simples com hiato iônico\nreduzido.","E":"Glasgow = 12; PCO2 = 18 mmHg; hiato iônico = 14; acidose metabólica mista com hiato iônico\nnormal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-140709","number":"140709","sourceNumber":"140709","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação à insuficiência renal crônica (IRC), julgue o próximo item. Pericardite,\nhipervolemia refratária a diuréticos, sangramentos\nassociados à uremia, acidose metabólica não\ncontrolável, náuseas e vômitos persistentes, manifestações clínicas de encefalopatia, hipercalemia\nnão controlada clínicamente e hipertensão arterial refratária a tratamento clínico são condições\nclínicas indicativas de início de terapia contínua de reposição renal em paciente com IRC.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-105570","number":"105570","sourceNumber":"105570","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente portador de insuficiência renal crônica, em fase pré-dialítica, apresentou,\nem exame bioquímico de rotina para seguimento,\nureia de 98 mg/dl; creatinina de 3 mg/dl e\npotássio de 6,3 mEq/L. É hipertenso, controlado com medicamentos, e apresentou-se taquicárdico,\nrespectivamente com PA: 145 x 95 mmHg e FC: 110 bpm. Referiu mal-estar geral, mas sem sinais\nou sintomas específicos de alguma morbidade. O exame físico não revelou outras alterações. Com\nbase nesse caso hipotético, a conduta deve ser complementar à avaliação, com realização\nprioritária de:","options":{"A":"Ecocardiograma.","B":"Tomografia computadorizada renal.","C":"Angiorressonância renal.","D":"Eletrocardiograma.","E":"RX de tórax."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-105560","number":"105560","sourceNumber":"105560","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A concentração de eletrólitos, nos compartimentos corporais, é fundamental para\nhomeostase. Com base nessa informação,\nassinale a alternativa que apresenta o cátion em maior\nconcentração no plasma de uma pessoa normal.","options":{"A":"potássio.","B":"cálcio.","C":"magnésio.","D":"cloro.","E":"sódio."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-52605","number":"52605","sourceNumber":"52605","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O exame de gasometria arterial, a despeito de ser invasivo, é de realização\nrelativamente simples; seu resultado é\nrapidamente obtido e possibilita a tomada de decisão em\nsituações de urgência e emergência médica. A tabela (VER IMAGEM), em que: pH = potencial\nhidrogeniônico, pO2 = pressão parcial de oxigênio (mmHg), pCO2 = pressão parcial de gás\ncabônico (mmHg), HCO3 - = nível de bicarbonato (mEq/L) e BE = excesso de bases (mEq/L),\nilustra os resultados dos exames dos pacientes hipotéticos A, B e C. Considerando que todas as\namostras foram colhidas de pacientes que respiram espontaneamente ? em ar ambiente e ao nível\ndo mar -, julgue o item a seguir. Os resultados do paciente B são compatíveis com acidose\nrespiratória, sem alterações metabólicas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-52610","number":"52610","sourceNumber":"52610","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O exame de gasometria arterial, a despeito de ser invasivo, é de realização\nrelativamente simples; seu resultado é\nrapidamente obtido e possibilita a tomada de decisão em\nsituações de urgência e emergência médica. A tabela (VER IMAGEM), em que: pH = potencial\nhidrogeniônico, pO2 = pressão parcial de oxigênio (mmHg), pCO2 = pressão parcial de gás\ncabônico (mmHg), HCO3 - = nível de bicarbonato (mEq/L) e BE = excesso de bases (mEq/L),\nilustra os resultados dos exames dos pacientes hipotéticos A, B e C. Considerando que todas as\namostras foram colhidas de pacientes que respiram espontaneamente ? em ar ambiente e ao nível\ndo mar -, julgue o item a seguir. Os achados do paciente C são indicativos de acidose metabólica\ncompensada por alcalose respiratória.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-45740","number":"45740","sourceNumber":"45740","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um jogador de futebol, 28 anos de idade, foi operado em um hospital geral por\nvideolaparoscopia, em virtude de uma colecistite crônica. Sua gasometria na sala de recuperação\nanestésica era: pH 7,31; saturação de 95%; pO2 de 85 mmHg; pCO2 de 39 mmHg; BE de - 6,5.\nQuanto ao distúrbio acidobase dessa gasometria, assinale a alternativa correta:","options":{"A":"A gasometria está normal (ausência de distúrbio metabólito ou respiratório).","B":"Trata-se de alcalose respiratória.","C":"Trata-se de acidose metabólica.","D":"Trata-se de alcalose metabólica.","E":"Trata-se de acidose respiratória."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-32152","number":"32152","sourceNumber":"32152","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"As manifestações clínicas mais comuns na IRA consistem em retenção de escórias\nnitrogenadas, oligúria, distúrbios\neletrolíticos e acidobásicos. Considerando um paciente que não\nrequeira emergência para a medida a ser tomada, assinale a alternativa que apresenta a prescrição\nmais eficaz para controlar a hiperpotassemia, comum na IRA, trazendo esse eletrólito de volta a\nníveis normais, de forma duradoura, com poucos efeitos colaterais e em curto espaço de tempo.","options":{"A":"Restrição dietética de potássio.","B":"Suspensão e/ou impedimento do uso de sais dietéticos.","C":"Dosagens altas de diurético de alça, em bolus.","D":"Injeção subcutânea de insulina, em baixas doses ao longo de 24 horas.","E":"Administração, por via oral ou por enema de retenção, de resina de permuta iônica com\npotássio."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-29745","number":"29745","sourceNumber":"29745","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considere que um paciente de 45 anos de idade, com diagnóstico de diabetes melito\ndo tipo 2, seja levado ao pronto-socorro com\nquadro clínico e laboratorial compatível com\ncetoacidose diabética. Acerca desse caso clínico emergencial, julgue o item seguinte. Um resultado\nde gasometria arterial (de amostra colhida em ar ambiente) com achados mostrados na tabela\nabaixo será compatível com a condição emergencial em tela. (VER IMAGEM)","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-29748","number":"29748","sourceNumber":"29748","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considere que um paciente de 45 anos de idade, com diagnóstico de diabetes melito\ndo tipo 2, seja levado ao pronto-socorro com\nquadro clínico e laboratorial compatível com\ncetoacidose diabética. Acerca desse caso clínico emergencial, julgue o item seguinte. Nessa\ncondição clínica, ainda que os níveis plasmáticos de potássio estejam normais ou mesmo\naumentados na abordagem inicial do paciente, verifica-se significativo déficit corporal desse\neletrólito. (VER IMAGEM).","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-7562","number":"7562","sourceNumber":"7562","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Lactente de quatro meses, previamente hígido, aleitamento materno exclusivo, pesando\n5 kg, é atendido na emergência com\ndesidratação grave. Foram feitas duas fases de expansão\nrápida, 1ª fase: 50 ml/kg em 1 hora e 2ª fase: 30 ml/kg em 1 hora de soro fisiológico, mas a criança\nnão apresentou diurese. Os exames solicitados apresentaram os seguintes resultados: Na = 118\nmEq/l, K = 3,5 mEq/l e Ca = 8,3 mg/dl. Assinale a alternativa que contém a conduta imediata a ser\nadotada.","options":{"A":"Prescrever a nova fase de expansão com SF 0,9% com 25 ml/kg em 1 hora, seguida de\nhidratação de manutenção caso a diurese esteja presente.","B":"Corrigir a hiponatremia com a infusão de NaCI a 3% em torno de 2 horas.","C":"Repetir fase rápida com acréscimo de bicarbonato.","D":"Iniciar fase de manutenção adicionando cálcio para corrigir o distúrbio de cálcio evidenciado.","E":"Iniciar fase de manutenção com KCI 15% em uma infusão de 4 mEq/100cal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-366217","number":"366217","sourceNumber":"366217","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma mulher de 68 anos de idade foi encontrada solitária em sua residência e\nconduzida ao pronto-socorro pelo Serviço de\nAtendimento Móvel de Urgência (SAMU). A equipe do\nSAMU foi acionada por vizinhos que a encontraram em estado de confusão. Informações adicionais\nsobre seu histórico não foram fornecidas. Após a realização dos cuidados iniciais, a paciente foi\ntransferida. No exame físico, observa-se confusão, sonolência e diminuição do nível de atenção,\ncom níveis de saturação de oxigênio em torno de 92% em ar ambiente, frequência respiratória\ndentro dos parâmetros normais e glicemia capilar de 99 mg/dL. De acordo com o caso clínico\nhipotético apresentado. Julgue o próximo item. A conduta imediata para a paciente em questão é\nfurosemida endovenosa após estabelecer acesso venoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-366216","number":"366216","sourceNumber":"366216","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma mulher de 68 anos de idade foi encontrada solitária em sua residência e\nconduzida ao pronto-socorro pelo Serviço de\nAtendimento Móvel de Urgência (SAMU). A equipe do\nSAMU foi acionada por vizinhos que a encontraram em estado de confusão. Informações adicionais\nsobre seu histórico não foram fornecidas. Após a realização dos cuidados iniciais, a paciente foi\ntransferida. No exame físico, observa-se confusão, sonolência e diminuição do nível de atenção,\ncom níveis de saturação de oxigênio em torno de 92% em ar ambiente, frequência respiratória\ndentro dos parâmetros normais e glicemia capilar de 99 mg/dL. De acordo com o caso clínico\nhipotético apresentado. Julgue o próximo item. Trata-se de principal causa de distúrbio\nhidroeletrolítico em pacientes internados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-343435","number":"343435","sourceNumber":"343435","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A Hiponatremia é o distúrbio hidroeletrolítico mais comum nos pacientes hospitalizados\ne sua ocorrência está associada a desfechos\nclínicos desfavoráveis. Sobre o exposto, é CORRETO\nafirmar:","options":{"A":"A concentração sérica de sódio é uma medida acurada da concentração do sódio corpóreo total,\nmas não reflete um valor relativo da quantidade de água livre no compartimento intravascular.","B":"Na maioria dos casos, a Hiponatremia é sintomática. Mesmo assim, pelo fato de os sintomas\nserem vagos, o seu diagnóstico não é algo simples.","C":"A Hiponatremia, quando se estabelece rapidamente, ou seja, em período de tempo inferior a 48\nhoras, é considerada aguda e pode, por isso, oferecer maior risco de edema cerebral.","D":"Um paciente com sódio sérico de 128 mEq/L apresenta Hiponatremia leve. Ainda assim, a\ncorreção está indicada até que o sódio sérico esteja em torno de 140 mEq/L."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-307099","number":"307099","sourceNumber":"307099","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considere um paciente de 57 anos de idade, etilista de duas latinhas de cerveja ao dia,\ndiabético insulinodependente controlado (hemoglobina glicada = 4,7% (valor de referência para\ndiabetes = 6,5% a 7,0%). Não apresentando nenhuma queixa, mas mantendo-se hipertenso de\ndifícil controle, compareceu à consulta com o cardiologista que, após conferir exames, encaminhou\no paciente ao colega nefrologista. Foram analisadas as parciais de ureia = 304 mg/dL (VR até 40\nmg/dL), Creatinina = 8,73 mg/dL (VR = 0,7 a 1,3 mg/dL) e potássio = 7,8 mmol/L (VR = 3,6 a 5,2\nmmol/L). O eletrocardiograma (ECG) mostrou o resultado a seguir. Com base nesse caso clínico e\nnos conhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"Em razão de o paciente estar estável, ele poderá ir para casa e aguardar consulta ambulatorial\ncom nefrologista.","B":"O paciente apresenta quadro clínico de doença renal crônica (DRC), mas ECG chama a atenção\npara a necessidade de terapia renal\nsubstitutiva.","C":"O paciente possui quadro compatível com tratamento conservador da DRC, podendo aguardar,\ncom propedêutica adequada, a confecção de fistula\npara início de hemodiálise.","D":"Com esse paciente, é importante abrir mão um pouco do controle glicêmico por estar bem\najustado e iniciar o controle de hipertensão arterial com inibidores da enzima conversora de\nangiotensina e melhorar a hidratação.","E":"Há boa evidência de que atividade física contribui ou evita a progressão da DRC diretamente no\nrim."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274609","number":"274609","sourceNumber":"274609","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O meio a partir do qual a hiponatremia é identificada é:","options":{"A":"Exame de sangue.","B":"Exame de urina.","C":"Exame de fezes.","D":"Exame de ultrassonografia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-273350","number":"273350","sourceNumber":"273350","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a investigação de poliúria, assinale a opção CORRETA:","options":{"A":"A presença de hipernatremia sela o diagnóstico de diabetes insipidus central.","B":"A intoxicação por lítio causa uma poliúria associada à hipernatremia totalmente arresponsiva à\ndesmopressina.","C":"A presença de hiponatremia pode estar relacionada à potomania dos bebedores de cerveja.","D":"Em pacientes com diminuição dos reflexos de tronco a presença de poliúria e hipernatremia sela\ndo diagnóstico de morte encefálica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-263422","number":"263422","sourceNumber":"263422","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma mulher de 58 anos de idade, portadora há longa data de diabete melito tipo 2 e de\nHipertensão Arterial Sistêmica (HAS), é internada em hospital terciário com queixas de náuseas,\nvômitos, soluços e dor precordial ventilatório-dependente. O quadro se iniciou na véspera, quando\nprocurou o pronto-socorro, onde realizou alguns exames complementares que revelaram glicose =\n145 mg/dl (valor de referência: 70 a 99 mg/dl), ureia = 264 mg/dl (valor de referência: 20 a 40\nmg/dl), creatinina = 12,8 mg/dl (valor de referência: 0,7 a 1,2 mg/dl) e potássio = 5,8 mEq/L (valor\nde referência: 3,5 a 5,2 mEq/L), além da presença, no eletrocardiograma convencional, de\nsupradesnivelamento difuso (exceto em AVR e V1) do segmento ST, com ondas T positivas (exceto\nas duas derivações anteriores) e infra do segmento PR. Foi administrado gluconato de cálcio e\nendovenoso e resina de troca catiônica Via Oral (VO), sendo solicitada transferência para\ninternação hospitalar. A paciente havia parado de fazer acompanhamento médico regular, não\ncomparecendo às consultas nos 2 últimos anos. Entretanto, continuava fazendo uso dos seguintes\nfármacos: metformina 500 mg VO duas vezes ao dia; hidroclorotiazida 25 mg/dia VO; e anlodipino\n10 mg VO duas vezes ao dia. Durante exame físico, a paciente se revela sonolenta, bradipsíquica,\ncom hálito desagradável e com soluços. Está hipocorada (2+/4+), com mucosas úmidas, acianótica,\nanictérica e afebril. O ritmo cardíaco é regular, em 2 tempos, sendo auscultado um ruído sistólico\nrude em borda esternal esquerda baixa, além de um sopro sistólico de baixa intensidade\npancardíaco. Há turgência jugular patológica, mas não há pulso paradoxal arterial ou venoso. Além\ndisso, apresenta PA = 180 x 100 mmHg; FC = 122 bpm; FR 26 irpm. A ausculta pulmonar evidencia\nredução no murmúrio vesicular nas bases, estendendo-se ao terço médio do hemitórax direito.\n\nMembros inferiores revelam edema 2+/4+, não havendo sinais de trombose venosa. Considerando\n\no caso apresentado, assinale a alternativa que indica CORRETAMENTE quais são as condutas que\n\no plano de cuidados dessa paciente deve incluir nesse momento.","options":{"A":"Iniciar terapia dialítica imediata por via de uma fístula arteriovenosa; melhorar o controle\nglicêmico através da associação de insulinização\nao fármaco hipoglicemiante já em uso; e ajustar\nos fármacos para controle da HAS, incluindo a associação de furosemida ao esquema em curso.","B":"Providenciar acesso venoso profundo com cateter duplo lúmen para início de terapia dialítica;\nsuspender o esquema antidiabético oral, mantendo controle glicêmico apenas através de\ninsulinização; e ajustar os fármacos para controle de HAS, incluindo a suspensão do uso da\nhidroclorotiazida.","C":"Puncionar o líquido pericárdico para definir a causa da pericardite, tratando-a adequadamente;\nmelhorar o controle glicêmico através da\nassociação de insulinização ao fármaco hipoglicemiante já\nem uso; e ajustar os fármacos para controle da HAS, incluindo a suspensão do uso da\nhidroclorotiazida.","D":"Encaminhar a paciente para a cateterismo coronário e possível revascularização percutânea;\nsuspender o esquema antidiabético oral,\nmantendo controle glicêmico apenas através de\ninsulinização; e ajustar os fármacos para controle da HAS, incluindo a associação de furosemida ao\nesquema em curso."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-230561","number":"230561","sourceNumber":"230561","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São causas de acidose respiratória todas as abaixo, EXCETO:","options":{"A":"Encefalopatia hepática.","B":"Doenças da parede torácica.","C":"Obesidade extrema com hipoventilação.","D":"Doenças do SNC ou do sistema musculoesquelético."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-230565","number":"230565","sourceNumber":"230565","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A abordagem tradicional do distúrbio acidobásico está voltada PRINCIPALMENTE em:","options":{"A":"Dados de pH, bicarbonato e CO?.","B":"Hiato iônico.","C":"Dados de base excesso.","D":"Ânion gap."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-230568","number":"230568","sourceNumber":"230568","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que NÃO apresenta uma etiologia de alcalose metabólica\nsalinorresponsiva:","options":{"A":"Perdas gástricas.","B":"Displasia óssea.","C":"Fibrose cística.","D":"Uso de diuréticos."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-230572","number":"230572","sourceNumber":"230572","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação ao tampão químico é CORRETO afirmar:","options":{"A":"O pK indica a acidez do tampão químico.","B":"A capacidade tamponante é independente do pK.","C":"Quando o pH equivale ao pK, então a concentração do ácido é maior do que o da base\nconjugada.","D":"É constituído por um par químico, em geral, um ácido fraco e o seu sal conjugado."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-175094","number":"175094","sourceNumber":"175094","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Durante avaliação de paciente com insuficiência renal crônica, foi suspeitado de\nhiperpotassemia, sendo que o ECG pode diagnosticar essa situação. Um dos itens se mostra\nINCORRETO quanto a descrição dos achados. Assinale-o:","options":{"A":"As alterações dependem dos níveis séricos do potássio e as alterações ocorrem\nsequencialmente.","B":"Onda T de grande amplitude, simétrica e de base alargada.","C":"Redução do intervalo QTc.","D":"Distúrbio de condução intraventricular (QRS alargado)."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-175105","number":"175105","sourceNumber":"175105","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São indicações formais de diálise, exceto:","options":{"A":"Hipercalemia Refratária.","B":"Hiponatremia Grave.","C":"Hipervolemia Refratária","D":"Acidose Metabólica Refratária."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-175116","number":"175116","sourceNumber":"175116","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Juliana, 9 anos, 20 Kg, retirou tumor de Sistema Nervoso Central e há um dia\napresenta diurese abundante, transparente, com\ndensidade urinária de 1003. Está sonolenta, muito\ndesidratada, com cefaléia, vômitos e apresentou um episódio de crise convulsiva. Nunca havia\nconvulsionado antes. Ao ser dosado o sódio sérico, ele era de 185 mEq/l. O diagnóstico da\npatologia surgida com a ressecção do tumor e o tratamento são:","options":{"A":"Diabetes Insipidus, deve-se oferecer hormônio antidiurético e água livre para a paciente.","B":"Síndrome da Secreção Inapropriada de ADH, deixar o paciente euvolêmica","C":"Diabetes Insípidus, deve-se oferecer NaCl3% e hormônio antidiurético para a paciente.","D":"Excreção aumentada de sódio urinário, manter a paciente euvolêmica com expansões."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-175117","number":"175117","sourceNumber":"175117","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Quando a Hiponatremia se instala de forma crônica e progressiva, os neurônios\neliminam seus solutos para ficarem com a mesma\nosmolaridade do plasma, sendo comum a falta\nde sintomas. Sobre isso, assinale a alternativa correta:","options":{"A":"Em tais pacientes é perigosa a correção lenta da natremia, podendo surgir edema cerebral.","B":"Pode surgir a Síndrome Osmótica Desmielinizante e a lesão que ela causa chama-se mielinólise\npontinha, se a natremia for corrigida rapidamente.","C":"A correção rápida da natremia pode causar déficits psiquiátricos justificados pela alteração de\nneurotransmissores dopaminérgicos.","D":"A correção lenta da natremia pode causar a síndrome da deflagração de Leuring Houller."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-175135","number":"175135","sourceNumber":"175135","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na situação onde o paciente apresenta densidade urinária de 1016, sódio sérico de 138\nmEq/L e poliúria, a principal hipótese diagnóstica é:","options":{"A":"Hidratação Excessiva.","B":"Diabetes Insipidus Central.","C":"Síndrome Perdedora de Sal.","D":"Secreção Inapropriada do Hormônio Antidiurético."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-168504","number":"168504","sourceNumber":"168504","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um homem com 27 anos de idade, vítima de acidente automobilístico, foi recebido na\nUnidade de Emergência após atendimento de equipe de ambulância em via pública, onde foi\nencontrado em choque hemorrágico. Após avaliação primária do trauma, realizada no atendimento\npré-hospitalar, iniciou-se a reanimação volêmica do paciente. No dia seguinte, contudo,\n\nobservou-se deterioração aguda de sua função renal. Exames complementares solicitados para a\ninvestigação do quadro de injúria renal aguda revelaram os seguintes achados: exame de urina tipo\nI: densidade de 1,035 e presença de cilindros hialinos; excreção fracionada de sódio: < 1%;\nexcreção fracionada de ureia: < 35%; relação ureia plasmática/creatinina plasmática: > 40. A\nexplicação mais provável para a retenção aguda de escórias nitrogenadas apresentada pelo\npaciente é","options":{"A":"necrose tubular aguda provocada pelo choque hemorrágico.","B":"azotemia pré-renal causada pelo choque hipovolêmico.","C":"injúria renal pós-renal devida a bexiga neurogênica.","D":"injúria renal aguda intrínseca por rabdomiólise."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-159551","number":"159551","sourceNumber":"159551","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No que tange à taxa de filtração glomerular, julgue o item seguinte. A taxa de filtração\nglomerular pode ser estimada pela equação de Cockcroft-Gault: (140 - idade em anos) x peso em\nquilos/ 72 x creatinina sérica. No caso de pacientes do sexo feminino, multiplica-se por 0,85.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-104757","number":"104757","sourceNumber":"104757","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Exame gasimétrico que mostra um HCO3 elevado e um pH de 6,8 indica:","options":{"A":"alcalose respiratória.","B":"alcalose respiratória compensada.","C":"acidose respiratória compensada.","D":"acidose respiratória.","E":"ânion-gap normal."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-111291","number":"111291","sourceNumber":"111291","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente séptico em ventilação espontânea encontra-se no momento com\n\na seguinte gasometria: pH = 7,27; PCO2= 35 mmHg; HCO3? = 10 mEq/L. O (s) distúrbio (s)\napresentado (s) nesse exame é (são):","options":{"A":"Acidose metabólica, somente.","B":"Alcalose respiratória, somente.","C":"Alcalose metabólica e acidose respiratória.","D":"Acidoses metabólica e respiratória.","E":"Acidose metabólica e alcalose respiratória."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-111307","number":"111307","sourceNumber":"111307","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Detectou-se em um paciente a presença, no eletrocardiograma, de onda T apiculada e\nQRS alargado. Tal alteração é decorrente de efeito colateral de um medicamento que o paciente\nvem usando nas últimas. Dentre as abaixo, a droga em questão mais provável é:","options":{"A":"Insulina.","B":"Captopril.","C":"Furosemida.","D":"Anfotericina B.","E":"Fenoterol."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-104748","number":"104748","sourceNumber":"104748","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O equilíbrio ácido-base é fundamental no pós-operatório, porém, nessa fase, diversos\ndistúrbios podem acometer os pacientes. Acerca dessas alterações, assinale a alternativa correta.","options":{"A":"No compartimento extracelular, o principal tampão é o íon bicarbonato.","B":"O valor do hiato aniônico é calculado pela soma das concentrações plasmáticas dos íons cloreto\ne bicarbonato e de proteínas.","C":"A acidemia grave é considerada sempre que os valores de pH estiverem abaixo de 7,35.","D":"O tratamento da acidose metabólica deve ser feito com a infusão de substâncias ácidas que\nprovocarão o efeito rebote.","E":"A hiperpotassemia tende a ocorrer com maior frenquência nos casos de alcalose metabólica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-111360","number":"111360","sourceNumber":"111360","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 28 anos, portador de úlcera duodenal estenosante, com vômitos\n\npós-alimentares não biliosos tardios, apresenta-se desidratado e com alterações do equilíbrio\nhidroeletrolítico e acidobásico. Estas alterações caracterizam-se por:","options":{"A":"Alcalose metabólica hipoclorêmica e hipocalêmica.","B":"Acidose respiratória hiponatrêmica e hiperpotassêmica.","C":"Acidose metabólica e acidose respiratória.","D":"Alcalose metabólica hipernatrêmica e hipercalêmica.","E":"Acidose respiratória hiperclorêmica e hipopotassêmica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-97764","number":"97764","sourceNumber":"97764","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um homem com 25 anos de idade, baterista de trio elétrico, deu entrada no\n\npronto-socorro há 24 horas, vítima de extensa queimadura elétrica em rede de alta tensão. Foi\ntransferido para Unidade de Terapia Intensiva após hidratação vigorosa e mantém estabilidade\nhemodinâmica com aminas vasoativas. Está evoluindo com redução do débito urinário e aumento\nda creatinina sérica. Está também em ventilação mecânica e o balanço hídrico de 24 horas é\npositivo em + 3.500 ml. A medida da pressão venosa central do paciente é de 20 cmH20. O\npotássio sérico dosado hoje é de 5.5 mEq/L. O pH sérico é de 7.6 mEq/L; e o pH urinário, 6.5. O\nECG está normal. Qual deve ser a conduta imediata a ser tomada para o paciente?","options":{"A":"Alcalinizar a urina.","B":"Aumentar a volemia.","C":"Prescrever diurético.","D":"Prescrever gluconato de cálcio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-138417","number":"138417","sourceNumber":"138417","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, com 45 anos de idade, sexo masculino, comerciante, vem a consulta na\nUnidade Básica de Saúde e informa que vem\napresentando dispneia progressiva a médios\nesforços, ?inchaço? nas pernas e diminuição da diurese. Relata que, em consultas anteriores, foi\norientado a realizar periodicamente medidas de sua pressão arterial, que se encontrava, na época,\nno limite da normalidade. Não realizou o procedimento solicitado, retornando, hoje, para consulta.\nHistória pessoal: tabagista desde os 14 anos, um maço de cigarro por dia. Dieta rica em gorduras e\npobre em frutas e vegetais. Informa que não é etilista e não usa drogas. História familiar: mãe\nhipertensa e pai falecido de infarto agudo do miocárdio. Ao exame: Pressão arterial 165 x 110\nmmHg, Frequência cardíaca: 55 bpm, Frequência respiratória 14 irpm, rítmo cardíaco regular em\ndois tempos, bradicárdico, sem sopros ou extrassístoles, murmúrio vesicular fisiológico, com\ndiscretas crepitações bibasais, abdome com ruídos hidroaéreos positivos, com hepatomegalia\ndolorosa a 2 cm do rebordo costal direito, membros inferiores com edema (++/++++). Os exames\ncomplementares demonstram que há uma sobrecarga de ventrículo esquerdo ao ECG; bloqueio\natrioventricular de primeiro grau; clearance de creatinina 45 ml/min (normal 90 -139 ml/min); urina\nde 24 horas com microalbuminúria de 250 mg/24h. Qual o tratamento farmacológico a ser prescrito,\nno que se refere à pressão arterial desse paciente?","options":{"A":"Captopril + losartana.","B":"Propranolol + enalapril.","C":"Lisinopril + espironolactona.","D":"Losartana + hidroclorotiazida.","E":"Alisquireno + furosemida."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-31037","number":"31037","sourceNumber":"31037","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando que, durante a investigação clínica de um paciente de 48 anos de idade\ncom acidose metabólica hiperclorêmica com hiato aniônico (ânion-gap) plasmático dentro da\nnormalidade, tenha-se obtido o diagnóstico de acidose tubular renal distal tipo 1, julgue o item a\nseguir. Nesse caso, o hiato aniônico (ânion-gap) urinário deve apresentar valor nulo ou positivo.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-31039","number":"31039","sourceNumber":"31039","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando que, durante a investigação clínica de um paciente de 48 anos de idade\ncom acidose metabólica hiperclorêmica com hiato aniônico (ânion gap) plasmático dentro da\nnormalidade, tenha-se obtido o diagnóstico de acidose tubular renal distal tipo 1, julgue o item a\nseguir: Hipercalciúria, nefrocalcinose e nefrolitíase são alterações que devem ser investigadas no\npaciente em tela, pois estão frequentemente associadas a essa nefropatia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-138683","number":"138683","sourceNumber":"138683","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, com 65 anos de idade, tabagista, internado com suspeita de trombose venosa\nprofunda, realizou tomografia de tórax e angiotomografia de membro inferior com contraste. Dois\ndias após o procedimento, houve redução de volume urinário para 400mL, em 24 horas. Exames\nsolicitados em caráter de urgência evidenciam creatinina = 2,5 mg/dL, K = 5,7 mEq/L e Ureia = 112\nmg/dL. O eletrocardiograma realizado mostra hemibloqueio de ramo esquerdo e alterações\ninespecíficas da repolarização ventricular. Para o caso, considerando os níveis de potássio sérico,\na intervenção apropriada, neste momento é","options":{"A":"furosemida EV.","B":"gluconato de cálcio EV.","C":"resina trocadora de potássio oral.","D":"betaadrenérgico inalatório.","E":"insulina com glicose EV."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-19220","number":"19220","sourceNumber":"19220","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O equilíbrio ácido-básico do organismo é mantido predominantemente pelos rins, que\nacidificam a urina, mantendo o pH sanguíneo em torno de 7,4, de modo a viabilizar as reações\nmetabólicas do organismo. O ânion gap (hiato de ânions) denota o equilíbrio de cátions e ânions,\nmantido também pelos rins, e pode ser utilizado para avaliação diagnóstica e prognóstica do\nprocesso patológico causador do distúrbio ácido-básico. A respeito desse assunto, julgue o item\nsubsequente. Em casos de cetoacidose diabética, é comum acidose metabólica com ânion gap\naumentado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-320456","number":"320456","sourceNumber":"320456","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A úlcera duodenal é uma doença com inúmeras causas. Os únicos requisitos são a\nsecreção de ácido e pepsina em combinação\ncom infecção por H. pylori ou a ingestão de AINEs. A\ninflamação aguda do duodeno pode levar à obstrução mecânica, com uma obstrução funcional da\nsaída do conteúdo gástrico manifestado por retardo no esvaziamento gástrico, anorexia, náuseas e\nvômitos. Das alternativas a seguir, qual o distúrbio associado a esse quadro?","options":{"A":"Acidose metabólica hipoclorêmica hipernatrêmica.","B":"Acidose metabólica hiperclorêmica hipercalêmica.","C":"Alcalose metabólica hipoclorêmica hipocalêmica.","D":"Alcalose metabólica hiperclorêmica hiponatrêmica.","E":"Alcalose respiratória hipocarbônica hipercalêmica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-321190","number":"321190","sourceNumber":"321190","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No controle do paciente cirúrgico no pós-operatório um cuidado que devemos ter é nos\ndistúrbios hidroeletrolíticos que podem ser fatais nos pacientes. Sobre esses distúrbios, assinale a\nalternativa CORRETA:","options":{"A":"A hiperpotassemia pode causar fraqueza muscular e a insuficiência respiratória é comum.","B":"Lesão tissular, hipoglicemia, acidose e aumento da ação da aldosterona são causas de\nhiperpotassemia.","C":"Ondas T em pico leva a pensar na possibilidade da hipocalemia.","D":"Pode-se tratar a hipercalemia com solução polarizante (insulina com glicose), bicarbonato de\nsódio ou agonista beta adrenérgico."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-359212","number":"359212","sourceNumber":"359212","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação à entidade Insuficiência Renal Aguda, assinale a alternativa INCORRETA.","options":{"A":"Um débito urinário < 0,5 ml/kg/h durante 6 horas é definição de Injúria Renal Aguda.","B":"Limitações quanto à avaliação etiológica estão presentes na classificação KDIGO, já que\ncondutas diferentes são definidas por etiologias diferentes.","C":"A classificação da KDIGO considera apenas Creatinina sérica, débito urinário e taxa de filtração\nglomerular em sua classificação.","D":"KDIGO se torna limitado em pacientes em que não se conhece creatinina de base, ficando difícil\nrealizar classificação da injúria."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-321159","number":"321159","sourceNumber":"321159","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma mulher de 68 anos está no 3º dia de pós- operatório de uma\npancreaticoduodenectomia. Seus gases arteriais\npós-extubação mostram: pH = 7,58, pCO? = 30,\nHCO? = 26, SatO? = 94% e EB = 2,2. Com base unicamente em seus gases arteriais, é CORRETO\nafirmar que o distúrbio acidobásico subjacente é:","options":{"A":"Alcalose metabólica.","B":"Alcalose metabólica compensada.","C":"Alcalose mista.","D":"Alcalose respiratória."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-320453","number":"320453","sourceNumber":"320453","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente masculino com 27 anos de idade, está internado com quadro grave de\nhemólise pós ataque de abelhas. À admissão\napresentava creatinina sérica de 1,1 mg/dl, a qual se\nelevou para 3,9 mg/dl, após 5 dias. Nas 24 horas prévias à coleta desse exame, o paciente teve\ndiurese de 340 ml. O paciente se mantém hemodinamicamente estável sem uso de drogas\nvasoativas. Considerando a diretriz do KDIGO (Kidney Disease Improvement Global Outcomes),\nqual a classificação de AKIN?","options":{"A":"O paciente apresenta injúria renal aguda estádio 1.","B":"O paciente apresenta injúria renal aguda estádio 2.","C":"O paciente apresenta injúria renal aguda estádio 3.","D":"O paciente apresenta injúria renal aguda estádio 4.","E":"O paciente apresenta injúria renal aguda, de origem pré-renal, não sendo possível, nenhum\nestadiamento."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-306723","number":"306723","sourceNumber":"306723","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São complicações relacionadas à hemodiálise nos pacientes portadores de doença\nrenal crônica, exceto:","options":{"A":"Reação mediada por IgE ao óxido de etileno","B":"Insuficiência cardíaca de alto débito","C":"Cãibras musculares em membros inferiores","D":"Reação imunomediada por IgA"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-305038","number":"305038","sourceNumber":"305038","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paraavaliaçãodafunçãorenalnacriançacomdiagnóstico clínico de doença renal crônica,\na International Pediatric Nephrology Association\nrecomenda utilizar o critério a seguir.","options":{"A":"Depuração de inulina.","B":"Medida da creatinina plasmática.","C":"Fórmula atualizada de Schwartz.","D":"Depuração de creatinina com coleta de urina de 24 horas."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-260697","number":"260697","sourceNumber":"260697","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O sódio é o principal íon extracelular, sendo que o seu metabolismo está\ncorrelacionado com o metabolismo de água no\norganismo. Acerca desse assunto, assinale a opção\ncorreta.","options":{"A":"Em casos de hiponatremia assintomática, o tratamento de escolha é a reposição de solução\nsalina a 3%.","B":"Pacientes com hipernatremia e instabilidade hemodinâmica devem receber hidratação vigorosa\ncom solução fisiológica a 0,45%.","C":"Uso prolongado de diurético.","D":"Correção rápida da hipernatremia pode causar mielinólise pontina.","E":"Hiponatremia hipotônica euvolêmica pode ser causada por hipotireoidismo descompensado."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-246725","number":"246725","sourceNumber":"246725","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O encontro de rins diminuídos à ultrassonografia, num paciente com insuficiência renal,\nsugere, dentre os abaixo:","options":{"A":"Mieloma múltiplo","B":"Diabetes mellitus","C":"Nefroesclerose maligna","D":"Amiloidose","E":"Doença policística"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-243033","number":"243033","sourceNumber":"243033","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma paciente internada na UTI por sepse abdominal desenvolve bradicardia\n(FC=40bpm). No ECG nota-se alargamento do QRS e\ndesaparecimento de ondas P. O débito\nurinário das últimas 24 horas foi de 200ml, a creatinina plasmática estava em 6,8 mg/dl, sódio de\n140 mEq/l e potássio de 7,8 mEq/l. Assinale a alternativa que indica a primeira medida a ser\ntomada:","options":{"A":"administrar resina de troca (Sorcal) de 8/8hs.","B":"infundir gluconato de cálcio a 10% intravenoso.","C":"solução com soro glicosado e insulina regular.","D":"bicarbonato de sódio a 8,4%.","E":"inalação com B2 agonista."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-243034","number":"243034","sourceNumber":"243034","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Quais seriam as formas de reduzir os níveis de potássio corpóreo deste paciente:","options":{"A":"diálise, diurético de alça e bicarbonato de sódio.","B":"glicoinsulinoterapia, bicarbonato de sódio e gluconato de cálcio.","C":"glicoinsulinoterapia, poliestirenossulfonato de cálcio e bicarbonato de sódio.","D":"diálise, diurético de alça e poliestirenossulfonato de cálcio.","E":"diurético de alça, gluconato de cálcio e diálise."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-243038","number":"243038","sourceNumber":"243038","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente masculino de 21 anos, com 60 kg de peso corporal, foi vítima de acidente\nbotrópico, tendo dado entrada na unidade de\nemergência normotenso e em boas condições\nclínicas, onde recebeu tratamento convencional para o caso. Trinta e seis horas mais tarde,\nobservou-se que a concentração da creatinina sérica do paciente era de 1,5 mg/dl, sendo que o\nexame na admissão mostrava valor de 0,9 mg/dl. Não se observou redução do volume urinário, que\nnas últimas 24 horas mostrava valor de 1.140 ml. A dosagem de creatinina sérica foi repetida,\nconfirmando-se a concentração de 1,3 mg/dl. Em relação à função renal assinale a alternativa\nCORRETA:","options":{"A":"O paciente deve estar apresentando somente injúria renal aguda pré-renal.","B":"A alteração laboratorial encontrada deve ser decorrente somente da lesão muscular associada à\nação do veneno botrópico, não havendo\ninjúria renal aguda.","C":"Os dados são compatíveis com diagnóstico de injúria renal aguda, que muito provavelmente é\nde origem renal.","D":"Os dados não são compatíveis com diagnóstico de injúria renal aguda, pois o valor da creatinina\né de 1,3.","E":"É necessária uma terceira dosagem da creatinina sérica para a confirmação de lesão renal\naguda."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-243039","number":"243039","sourceNumber":"243039","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 64 anos, portador de hipertensão arterial de longa data, apresentando taxa\nde filtração glomerular de 40ml/min. De acordo\ncom o último KDIGO como podemos classificar a\ndoença renal crônica?","options":{"A":"estagio 2A.","B":"estagio 2B","C":"estagio 3A.","D":"estagio 3B.","E":"estagio 4."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-243040","number":"243040","sourceNumber":"243040","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A principal causa da anemia da doença renal crônica é:","options":{"A":"presença de anticorpos circulantes anti-eritropoeitina.","B":"diminuição da produção de eritropoeitina.","C":"fibrose da medula óssea pela doença mineral e óssea.","D":"diminuíção do numero de receptores celulares de eritropoetina.","E":"Diminuição da meia-vida das hemáceas"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-227321","number":"227321","sourceNumber":"227321","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No paciente com insuficiência cardíaca, ao se prescrever espironolactona para uso\nprolongado deve-se estar atento para o seguinte efeito colateral:","options":{"A":"Ototoxidade.","B":"Hipercalemia.","C":"Hiperglicemia.","D":"Nefrocalcinose."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-199604","number":"199604","sourceNumber":"199604","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 45 anos de idade, sem histórico de doença neurológica prévia, em uso de\ncitalopram há 1 mês para transtorno do humor, deu entrada no pronto-socorro com história de duas\ncrises convulsivas nas últimas quatro horas, com duração de aproximadamente dois minutos. Ao\nexame físico apresenta-se consciente, orientada, sem deficit neurológico focal, hidratada, níveis\npressóricos de 130 x 88 mmHg, frequência cardíaca de 90 bpm, tempo de enchimento capilar de 2\nsegundos, ausculta cardiopulmonar sem alterações, peso = 80 kg. Exames complementares:\nglicose = 112 mg/dl; sódio = 120 mEq/L; potássio = 3,1 mEq/L; cloro = 90 mEq/L; magnésio = 1,1\nmEq/L; ureia = 33 mg/dl; creatinina: 0,8 mg/dl; osmolaridade urinária: 367 mOsm/L; ECG\n(Eletrocardiograma): ritmo sinusal, sem alterações; tomografia computadorizada de crânio: sem\nevidências de lesões. Assinale a alternativa CORRETA sobre o caso acima:","options":{"A":"A natremia deve ser corrigida com solução de NaCI a 3% e o deficit de sódio reposto nas\nprimeiras 6 horas.","B":"Deve ser administrada fludrocortisona por via oral para correção da natremia.","C":"É recomendada restrição hídrica para a paciente.","D":"Deve ser administrado KCI a 10% diluído em solução glicosada."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-199513","number":"199513","sourceNumber":"199513","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A Doença Renal Crônica (DRC) apresenta elevadas prevalência e morbimortalidade em\ndiversos países do mundo. É conceituada como alteração persistente (mais de 3 meses) da função\nrenal (estimada pelo clearance de creatinina) e/ou albuminúria moderada ou grave. Sobre o manejo\ndos pacientes portadores de doença renal crônica, assinale a alternativa INCORRETA:","options":{"A":"Os sintomas de hipervolemia podem ser tratados\ncom diurético de alça, ainda que o efeito dessas\ndrogas seja reduzido na DRC.","B":"O hiperparatireoidismo secundário pode ser tratado com reposição de vitamina D e fosfato, se os\nníveis séricos estiverem reduzidos.","C":"O estoque de ferro deve ser avaliado e reposto, se\n\nnecessário, antes da administração de eritropoetina no tratamento da anemia da DRC.","D":"A vacinação contra a influenza e a doença\npneumocócica está indicada nos pacientes com\nDRC em estágio final."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-220290","number":"220290","sourceNumber":"220290","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a propedêutica complementar, nos casos de Injúria Renal Aguda (IRA) e Doença\nRenal Crônica (DRC), assinale a alternativa INCORRETA:","options":{"A":"Nos casos de IRA por desidratação, geralmente há um aumento desproporcional da ureia em\nrelação à creatinina.","B":"A hiperfosfatemia e a anemia não ocorrem na IRA, mas indicam DRC quando presentes.","C":"O exame do sedimento urinário pode revelar células epiteliais livres, cilindros epiteliais e\ngranulosos na necrose tubular aguda.","D":"A identificação de cilindros hemáticos possui alta especificidade e baixa sensibilidade para o\ndiagnóstico de hematúria glomerular."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-212951","number":"212951","sourceNumber":"212951","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sra. Maria, 69 anos, diabética, hipertensa, dá entrada no PS com relato de fraqueza,\nnáuseas e fadiga muscular. Ao examiná-la,\nencontra-se: desorientada, Glasgow 14 sem déficit\nfocais, TAx: 36,8°C, sem rigidez de nuca. RCR 2T BNF sem sopros, PA 170/95 mmHg, FC 90 bpm\nMV presente bilateralmente, com crepitações finas em ambas as bases, FR 24 irpm, sem esforço\nrespiratório. Abdome flácido, indolor, ruídos hidroaéreos presentes, sem sinais de irritação\nperitoneal. Pele sem maiores alterações. MMII sem sinais de TVP. Dentre as alternativas, a medida\nque deve ser a primeira a ser tomada é:","options":{"A":"Implantação de marcapasso transcutâneo.","B":"Cardioversão elétrica sincronizada.","C":"Encaminhamento imediato para unidade de hemodinâmica.","D":"Ácido acetilsalicílico 200 mg mastigado VO.","E":"Gluconato de cálcio."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215183","number":"215183","sourceNumber":"215183","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O Sr. J.A.M. tem 67 anos e usa hipoglicemiantes orais, mas não apresenta controle\nadequado das glicemias. Há 6 anos, lida com\nulcerações varicosas em MMII e estas estão\nfrancamente infectadas. Por isso, deu entrada no HEVV, e os seguintes resultados foram obtidos:\nEm relação à abordagem terapêutica, assinale a alternativa CORRETA:","options":{"A":"A correção da glicemia e controle da infecção não são o bastante para correção da anemia,\nsendo necessária a reposição de ferro parenteral.","B":"O uso de hemocomponentes (concentrado de hemácias) se faz necessário.","C":"O uso de eritropoietina associada a ferro parenteral objetiva transpor os defeitos\nfisiopatológicos.","D":"A utilização de ferro oral faz parte desta abordagem.","E":"O uso de ferro parenteral não é necessário, pois a ferritina está normal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215117","number":"215117","sourceNumber":"215117","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 60 anos, hipertenso e diabético, em uso de losartan 50 mg 12/12 horas\niniciado recentemente pelo cardiologista, vem ao pronto-socorro com quadro de edema de\nmembros inferiores e dispneia leve. Refere volume urinário > 2 L/24 horas. Na investigação\nlaboratorial foi detectado creatinina 2 mg/dl, ureia 70 mg/dl, potássio 7,0 mEq/L. Qual seria a\nconduta mais CORRETA, referente a condução do caso?","options":{"A":"Hemodiálise de urgência.","B":"Gluconato de cálcio IV apenas se houver alteração eletrocardiográfica.","C":"Manter a medicação em uso e prescrever solução de glicose e insulina.","D":"Administração de bicarbonato de sódio 8,4% IV.","E":"Furosemida IV isoladamente."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-220328","number":"220328","sourceNumber":"220328","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Analise a proposição e sua razão. Proposição: Paciente operado de uma gastrectomia.\nNo pós-operatório, apresenta quadro clínico de\nnáuseas, astenia, queda do volume urinário e, em\nseguida, episódio de convulsão, com suspeita de diagnóstico de uma hiponatremia; PORQUE;\nRazão: é raramente um distúrbio iatrogênico e pode ser tratado com restrição hídrica e reposição\nde solução de sódio hipotônico em pequenas quantidades. Com base na análise, é CORRETO\nafirmar que:","options":{"A":"A proposição e a razão são afirmativas verdadeiras e a razão é realmente a causa da\nproposição.","B":"A proposição e a razão são afirmativas verdadeiras, mas a razão não é a causa da proposição.","C":"A proposição é uma afirmativa falsa, mas a razão é uma afirmativa verdadeira.","D":"A proposição é uma afirmativa verdadeira e a razão é uma afirmativa falsa."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-196799","number":"196799","sourceNumber":"196799","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Dentre as opções, assinale aquela capaz de corrigir o distúrbio hidroeletrolítico\npresente\nno paciente do ECG a seguir:","options":{"A":"Gluconato de cálcio.","B":"Solução salina a 0,45%.","C":"Poliestirenossulfonato de cálcio.","D":"Cloreto de potássio a 10%."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-196743","number":"196743","sourceNumber":"196743","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 54 anos, com hipotireoidismo em tratamento com levotiroxina 75 mcg/dia,\nchega ao pronto-socorro após dois dias de\ndiarreia e vômitos. Fora diagnosticada com\ngastroenterocolite aguda e medicada com soro de hidratação oral, mas não tolerou o tratamento\npor causa dos vômitos. Relata diminuição do débito urinário. Exames laboratoriais evidenciaram\npotássio sérico = 5,4 mEq/L; ureia = 62 mg/dl e creatinina = 2,3 mg/dl. Eletrocardiograma normal.\nAssinale a melhor opção terapêutica.","options":{"A":"Expansão com soro fisiológico 0,9%.","B":"Expansão com coloide.","C":"Expansão com cristaloide. Beta-2-agonista inalatório. Poliestirenossulfonato de cálcio.","D":"Expansão com soro fisiológico 0,9%. Solução de insulina com glicose, ciprofloxacino."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187474","number":"187474","sourceNumber":"187474","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente IDM, sexo masculino, 55 anos, ex-tabagista, com história de tosse, dispnéia e\nhemoptoicos há cerca de 3 meses. Foi investigado quanto a possibilidade de tuberculose pulmonar\nporém o resultado foi negativo. Há 1 semana evoluiu com náuseas, vômitos, perda ponderal,\nirritabilidade, confusão mental e convulsões. Foi internado para investigação. Exames laboratoriais\nde entrada revelaram anemia e hiponatremia. Foi diagnosticado com câncer de pulmão avançado e\nfoi descartada a presença de metástase cerebral. Dentre as alternativas abaixo, assinale a\nsíndrome paraneoplásica que é compatível com o quadro clínico desse paciente acima:","options":{"A":"Síndrome de Cushing.","B":"Síndrome miastênica de Lambert-Eaton.","C":"Síndrome de Trousseau.","D":"Síndrome da secreção inadequada do hormônio antidiurético (SIADH).","E":"Osteoartropatia hipertrófica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-149154","number":"149154","sourceNumber":"149154","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"De posse do conhecimento de que os distúrbios do sódio representam na verdade uma\ndesordem no balanço corporal da água e que o hormônio antidirético (vasopressina) tem papel\ncentral nesse equilíbrio, qual das afirmativas abaixo é CORRETA?:","options":{"A":"Nas hiponatremias em pacientes hipovolêmicos a vasopressina não tem participação importante\nna fisiopatologia, uma vez que a causa central é a\nperda maior de sódio em relação à perda de\nágua. Isto ocorre por exemplo nos casos de diarréia ou vômitos (causas gastrointestinais) ou de\nperda renal de sódio.","B":"A hiponatremia hipovolêmica é considerada uma hiponatremia diluicional e hipotônica, até\nmesmo nos casos onde há perda renal ou gastrointestinal de sódio. Isso porque apesar da\nhipotonicidade inibir a liberação osmótica de vasopressina, o estímulo baroreceptor se impõe\nliberando vasopressina e levando a retenção renal de água e consequente hiponatremia.","C":"A SIADH (secreção inapropriada de hormônio antidiurético) é caracteristicamente hipervolêmica,\numa vez que os níveis sempre elevados e\n\ninapropriados e vasopressina induzem a uma grande retenção renal de água.","D":"Na Cirrose Hepática e na Insuficiência Cardíaca, surge uma hiponatremia hipotônica\nhipervolêmica apesar da supressão quase total da ação da\n\nvasopressina, causada portanto exclusivamente pelo Sistema Renina Angiotensina-Aldosterona.","E":"Na polidipsia primária, um distúrbio psiquiátrico onde existe uma ingestão absurda de água,\nsurge uma hiponatremia hipotônica, pois a\ngrave hipotonicidade produzida pelo excesso de água\nproduz um potente estímulo à liberação de vasopressina."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-149158","number":"149158","sourceNumber":"149158","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, 75 anos, portador de insuficiência renal em acompanhamento ambulatorial, é\nadmitido no Hospital Evangélico e já na emergência é vítima de Parada Cardiorrespiratória (PCR)\nsendo prontamente reanimado pela equipe SAVI. São prontamente iniciados os cuidados\n\npós-ressuscitação onde são achados os seguintes exames: ECG: ritmo sinusal. Ondas T\napiculadas. Ureia = 349; creatinina = 10; K = 8,2; pH = 7,1; bicarbonato = 8; glicose = 380. No\nmanejo desse paciente é INCORRETO afirmar que:","options":{"A":"A administração de insulina venosa, além do controle glicêmico, deve contribuir\npara a redução parcial da calemia.","B":"O gluconato de cálcio deve ser administrado, apesar de não reduzir a calemia.","C":"A furosemida será provavelmente pouco útil, em virtude da avançada disfunção renal.","D":"O bicarbonato é contraindicado nesse caso, pois, em pacientes pós-PCR e com acidose\nmetabólica, pode corrigir a acidose mas agravar a hipercalemia.","E":"Após as medidas iniciais de controle emergencial da hipercalemia, uma\nhemodiálise de urgência deve ser tentada assim que possível."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-162570","number":"162570","sourceNumber":"162570","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Marque, dentre as opções abaixo, qual a principal causa de morte nos pacientes com\ndoença renal crônica:","options":{"A":"Doença cardiovascular.","B":"Hipercalemia.","C":"Infecções oportunistas.","D":"Uremia.","E":"Acidose metabólica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-149159","number":"149159","sourceNumber":"149159","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Ainda sobre o tema hipercalemia é CORRETO afirmar:","options":{"A":"A solução glicoinsulina reduz o potássio corporal total.","B":"O bicarbanato de sódio é indicado em todos os casos de hipercalemia.","C":"A furosemida quando usada e efetiva, apenas desloca o potássio do intravascular\npara o intracelular reduzindo a calemia.","D":"As resinas de troca iônica apenas deslocam o potássio para o intracelular, diferentemente da\nhemodiálise que efetivamente reduz o potássio corporal total.","E":"As resinas de troca iônica (ex: Sorcal), apesar de reduzirem o potássio corporal total não são\ngeralmente capazes de reduzir rapidamente o nível sérico de potássio."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-148526","number":"148526","sourceNumber":"148526","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que não representa causa de hipercalemia.","options":{"A":"Uso de inibidores da enzima conversora de angiotensinas.","B":"Síndorme neuroléptica maligna.","C":"Insuficiência renal terminal.","D":"Hiperaldosteronismo.","E":"Hemólise."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-149139","number":"149139","sourceNumber":"149139","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente 18 anos, internada para realização de parto cesáreo de urgência devido\noligodramnia grave, com cerca de 35 semanas\nde gestação. Não realizou pré-natal adequado,\napenas duas consultas, internada em anasarca e com ganho ponderal 25 kg na gestação. Cirurgia\nrealizada sem intercorrências sendo encaminhada à maternidade para segmento. No manhã do dia\nseguinte, recebeu diagnóstico de pneumonia devido queixas de tosse produtiva, febre, leucocitose,\nRx de tórax com consolidação e broncograma aéreo. Encaminhada ao CTI na tarde deste dia\ndevido taquipnéia e hipotensão, com boa evolução após ventilação não invasiva e hidratação, além\nda monitorização habitual de CTI. No dia seguinte, notada diurese clara e abundante pela sonda\nvesical de demora (mais de 8 litros em 24 h), persistindo com poliúria no dia seguinte e com\nelevação rápida do sódio de valores normais para o máximo de 193 mg/dl num intervalo de 48\nhoras. Qual a principal hipótese diagnóstica e estratégia a ser adotada para esta puérpera:","options":{"A":"Provável Secreção Inapropriada do Hormônio Antidiurético, como complicação da Pneumonia,\nsendo recomendada a restrição de fluidos para no\nmáximo 1l/dia para tratamento.","B":"Provável Secreção Inapropriada do Hormônio Antidiurético, como complicação da Pneumonia,\nsendo recomendada a administração de soluções\nhipotônicas, água por via oral e administração de\nanálogo do hormônio antidiurético (DDAVP).","C":"Provável Diabetes Gestacional. Realizar glicemia capilar, iniciar insulinoterapia venosa em\nbomba de infusão e hidratação com ringer\nlactato.","D":"Provável Diabetes Insipidus Nefrogênico. Hidratar com solução hipotônica e administrar DDAVP.\nA redução do volume urinário com aumento da\nconcentração urinária após a sua adminitração\nconfirma o diagnóstico.","E":"Provável Diabetes Insipidus Central. Hidratar com solução hipotônica e administrar DDAVP. A\nredução do volume urinário com aumento da concentração urinária após a sua adminitração\nconfirma o diagnóstico."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-148575","number":"148575","sourceNumber":"148575","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que pode cursar com acidose metabólica.","options":{"A":"Hiperaldosteronismo.","B":"Vômitos persistentes.","C":"Uso de furosemida.","D":"Diarreia crônica.","E":"Hipocalemia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-148581","number":"148581","sourceNumber":"148581","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente com taxa de filtração glomerular de 27 ml/min pode ser classificado como:","options":{"A":"Função renal normal.","B":"Insuficiência renal funcional.","C":"Insuficiência renal laboratorial.","D":"Insuficiência renal clínica.","E":"Insuficiência renal dialítica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-148558","number":"148558","sourceNumber":"148558","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente em pós-operatório de gastrectomia total evoluiu com elevação da creatinina\nassociada à hipercalemia importante. São medidas para o tratamento da hipercalemia com\nalteração eletrocardiográfica, EXCETO:","options":{"A":"Infusão endovenosa de gluconato de cálcio.","B":"Infusão de solução glico-insulínica.","C":"Uso de betabloqueadores.","D":"Hemodiálise.","E":"Uso de resinas gastrointestinais que se ligam ao potássio e sorbitol a 20%."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-127182","number":"127182","sourceNumber":"127182","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que não representa indicação para terapia de substituição renal\nem paciente com insuficiência renal aguda.","options":{"A":"Hipervolemia e insuficiência cardíaca.","B":"Potassemia de 7,3 mEq/L.","C":"Uremia em paciente torporoso.","D":"Hipertensão arterial.","E":"Acidose metabólica grave."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-127219","number":"127219","sourceNumber":"127219","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São medicamentos que podem levar à hiperpotassemia, EXCETO:","options":{"A":"Valsartana.","B":"Heparina.","C":"Trimetoprima.","D":"Espironolactona.","E":"Fenoterol."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-131615","number":"131615","sourceNumber":"131615","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Se 1 litro de solução de NaCl a 0.9% é administrado por via endovenosa, quanto será\ndistribuído para o espaço intersticial?","options":{"A":"100 cc","B":"250 cc","C":"350 cc","D":"500 cc","E":"750 cc"},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-126891","number":"126891","sourceNumber":"126891","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação aos distúrbios do equilíbrio acidobásico, analise as afirmativas abaixo e\nassinale V para as Verdadeiras e F para as Falsas. ( ) Os principais órgãos envolvidos na\nmanutenção do equilíbrio acidobásico são os rins e os pulmões. ( ) Independentemente da situação\nclínica, os estados de acidose são sempre acompanhados de pH < 7,35. ( ) A cetoacidose diabética\né uma acidose metabólica com ânion-gap aumentado. ( ) O tratamento com infusão intravenosa de\nbicarbonato de sódio deve sempre ser realizado nos casos de acidose metabólica. Assinale a\nalternativa que apresenta a sequência CORRETA:","options":{"A":"V, F, V, F.","B":"V, F, F, F.","C":"V, V, V, F.","D":"F, F, V, F."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-131625","number":"131625","sourceNumber":"131625","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual é o maior compartimento líquido do corpo?","options":{"A":"Plasma","B":"Fluido espinhal central","C":"Fluido intersticial","D":"Fluido intracelular","E":"nenhuma das anteriores"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-137816","number":"137816","sourceNumber":"137816","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A respeito do equilíbrio ácido-base e distúrbios respiratórios é correto afirmar:","options":{"A":"Nas acidemias, a pCO2 é superior a 40 mmHg, e nas alcalemias, a pO2 é inferior a 35 mmHg.","B":"Nas alterações primárias do padrão ventilatórios, os valores da pCO2 sanguínea estão normais.","C":"Para manter o pH na faixa da normalidade, a concentração de HCO3 - diminui na acidose\nrespiratória.","D":"As acidemias respiratórias ocorrem por hiperventilação.","E":"O uso de diurético de alça é uma das principais causas de acidose respiratória."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-127229","number":"127229","sourceNumber":"127229","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em um paciente masculino de 100 kg, o sódio sérico medido foi de 105 mEq/L. Quanto\nde sódio deve ser administrado para\nrecuperar este sódio para 120 mEq/L?","options":{"A":"600 mEq.","B":"900 mEq.","C":"1.200 mEq.","D":"1.500 mEq.","E":"1.800 mEq."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-100955","number":"100955","sourceNumber":"100955","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Entre os objetivos do tratamento na doença renal crônica, assinale a alternativa que\nnão tem impacto na evolução para\ninsuficiência renal:","options":{"A":"Dieta hipoproteica.","B":"Interrupção do tabagismo.","C":"Reposição de calcitriol.","D":"Uso de Inibidores da Enzima Conversora da Angiotensina (IECA).","E":"Controle de dislipidemia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-88841","number":"88841","sourceNumber":"88841","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação à solução de cloreto de sódio a 0,9%,","options":{"A":"1 litro contém 90 gramas de sódio.","B":"na solução, existe, 131mmol/L Na.","C":"na solução, encontram-se 154 mmol/L Na.","D":"tem um ph de 7,5.","E":"quando administrada em excesso, causa acidose hipoclorêmica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-77613","number":"77613","sourceNumber":"77613","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considere um paciente do sexo masculino, 55 anos, com quadro de lesão renal aguda\nsecundária à sepse de foco urinário, com os seguintes resultados de exames de sangue (sabe-se\nque sua creatinina de entrada era 0,8 mg/dl e a média de diurese de 2.500 ml/dia): ureia = 105\nmg/dl; potássio = 7,8 mEq/L; eletrocardiograma com onda T apiculada em todas as derivações;\nsódio = 132 mEq/L; pH = 7,32; creatinina = 3,2 mg/dl; hematócrito de 30% e glicemia = 110 mg/dl.\nSua diurese atual de 1.800 ml/24h. A primeira manobra terapêutica de urgência com relação à\nhipercalemia, dentre as alternativas abaixo, é:","options":{"A":"Diálise peritoneal.","B":"Administrar soro fisiológico.","C":"Administrar gluconato de cálcio endovenoso.","D":"Como a causa da lesão renal é sepse, a hemodiálise é a melhor abordagem.","E":"Resina trocadora sob a forma de enema, via retal."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-77347","number":"77347","sourceNumber":"77347","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Num paciente em pós-operatório de gastrectomia total, você é orientado a garantir um\nsuporte calórico de 400 kcal em 24 horas, pois o mesmo permanecerá em dieta zero. Dispondo,\npara isso, de ampolas de 10 ml de SG 50% (glicose anidra) para serem distribuídas na hidratação\ncom soro fisiológico que o paciente receberá. No dia seguinte, você identifica nos exames um nível\nde potássio de 2,1 mg/dl, sintomático, e com alteração eletrocardiográfica. Neste caso:","options":{"A":"É necessária reposição rápida de potássio, com velocidade superior a 40 mEq/h.","B":"Caso a reposição seja feita em veia periférica, deve-se usar idealmente soluções com\nconcentração inferior a 40 mEq/L.","C":"O cálculo da reposição deverá ser feito de maneira muito precisa, utilizando-se das fórmulas\ndisponíveis, validadas e confiáveis.","D":"Em hipótese alguma repor magnésio junto, ou antes, da correção do potássio sob risco de\nagravamento da hipocalemia.","E":"Devido à alteração eletrocardiográfica identificada, deve-se administrar imediatamente gluconato\nde cálcio para estabilização da membrana\ncelular e prevenção de arritmias graves."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-43336","number":"43336","sourceNumber":"43336","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Acerca da hipercalemia, marque a alternativa INCORRETA:","options":{"A":"As alterações eletrocardiográficas se devem ao fato da hipercalemia despolarizar a membrana\nda célula, retardar a condução ventricular e\ndiminuir a duração do potencial de ação.","B":"Eletrocardiogramas normais podem ser vistos mesmo em pacientes com hipercalemia grave.","C":"Os efeitos eletrofisiológicos da hipercalemia são diretamente relacionados ao nível de potássio\nsérico e inversamente relacionados à velocidade de instalação da hipercalemia.","D":"As metas terapêuticas na hipercalemia são: 1) estabilizar a membrana celular, 2) redistribuir o\npotássio extracelular para dentro das células e 3) aumentar a eliminação de potássio do corpo.","E":"Contribuem para a redistribuição do potássio as seguintes medidas terapêuticas: solução\nglicoinsulínica, salbutamol e o uso do bicarbonato em algumas situações."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-43297","number":"43297","sourceNumber":"43297","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Pré-escolar evoluiu no pós-operatório de um glioma óptico com: poliúria, polidipsia e\nhipernatremia por aproximadamente 24 horas. No dia seguinte, apresentou melhora da polidipsia e\npoliúria, porém com hiponatremia e osmolalidade urinária \"maior que\" 100 mOsm/kg por 5 dias.\n\nDepois, com quadro de desidratação, polidipsia, poliúria, hipernatremia, osmolidade do soro \"maior\nque\" 300 mOsm/kg e osmolidade urinária\n\"menor que\" 300 mOsm/kg. De acordo com as alterações\napresentadas por essa criança, podemos afirmar:","options":{"A":"Trata-se de um quadro clássico de estresse cirúrgico somado ao grande volume de fluidos\nadministrados e a perda de sangue durante a cirurgia. Comum em cirurgias complexas.","B":"Deve-se suspeitar da resposta trifásica após cirurgia, onde há uma fase inicial de Diabetes\nInsipidus transitória, seguida por uma fase de Síndrome de Secreção Imprópria do Hormônio\nAntidiurético e depois, por Diabetes Insipidus permanente.","C":"Deve-se suspeitar de Diabete Insípido Central devido ao glioma óptico, porém esse quadro terá\numa duração de aproximadamente 1 mês, sendo que o tratamento cirúrgico é eficaz.","D":"Deve-se suspeitar de uma Síndrome de Secreção Inapropriada de Hormônio Antidiurético, onde\nessa evolução é clássica no pós-operatório de\nglioma óptico."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-32451","number":"32451","sourceNumber":"32451","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Dentre as causas possíveis de estado confusional agudo em idosos, qual das opções\nabaixo é a menos provável?","options":{"A":"Hipercalemia grave.","B":"Hipomagnesemia.","C":"Hipovolemia.","D":"Quinolonas.","E":"Anticolinérgicos."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-273145","number":"273145","sourceNumber":"273145","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sintomas comuns no quadro de hiponatremia são:","options":{"A":"Perda de cabelo e enfraquecimento de unhas.","B":"Náuseas, dor de cabeça, confusão mental e fadiga.","C":"Sangue nas fezes e urina.","D":"Acne vulgar e dermatite atópica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-321555","number":"321555","sourceNumber":"321555","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente com taxa de filtração glomerular estimada de 17ml/min há mais de três\nmeses tem doença renal crônica em estágio:","options":{"A":"IIIA.","B":"IIIB.","C":"IV.","D":"V."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-334770","number":"334770","sourceNumber":"334770","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando a classificação de Doença Renal Crônica, que leva em consideração a\ntaxa de filtração glomerular, microalbuminúria e causa, em qual estágio o paciente apresenta pior\nprognóstico de evoluir para necessitar de terapia renal substitutiva, como diálise ou transplante\nrenal?","options":{"A":"G3a A3.","B":"G3b A1.","C":"G2 A3.","D":"G3a A2."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-362662","number":"362662","sourceNumber":"362662","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente feminina, 50 anos, apresenta fraqueza muscular e arritmias cardíacas.\nExames laboratoriais mostram potássio sérico elevado.\nQual é a desordem metabólica mais\nprovável?","options":{"A":"Hiperpotassemia","B":"Hipernatremia","C":"Hipopotassemia","D":"Hipercalcemia"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-354810","number":"354810","sourceNumber":"354810","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Beta agonistas seletivos, como salbutamol e terbutalina são medicamentos amplamente\nutilizados para o tratamento do broncoespasmo. Um importante efeito colateral dessas medicações\né a","options":{"A":"elevação da creatinina sérica.","B":"redução do nível sérico de potássio.","C":"redução do nível sérico de glicose.","D":"elevação do nível sérico de potássio."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-353830","number":"353830","sourceNumber":"353830","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A Doença Renal Crônica (DRC) é um problema de saúde pública em todo o mundo e,\nindependentemente da causa, o curso da doença é progressivo e irreversível. Porém, por meio de\nmedidas clínicas, pode-se atuar na redução da velocidade de progressão, no controle das\ncomorbidades, no tratamento das complicações e no preparo para Terapia Renal Substitutiva\n(TRS). Nesse contexto, ao analisar as proposições abaixo, é CORRETO afirmar: I. Nos estágios 1 e\n2 da DRC, o paciente pode queixar-se apenas de urina espumosa ou, até mesmo, estar\nassintomático. II. Quanto ao distúrbio mineral ósseo na doença renal crônica, em geral,\n\nencontram-se cálcio sérico normal ou reduzido, fósforo sérico normal ou elevado, PTH e fosfatase\nalcalina elevados. III. O uso de Inibidores da Enzima de Conversão da Angiotensina (IECA) é\ncontraindicado no tratamento da DRC pelo aumento expressivo do potássio nos pacientes.","options":{"A":"Apenas I e II estão corretas.","B":"Apenas III está correta.","C":"Apenas I e II estão incorretas.","D":"Todas estão corretas."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-354800","number":"354800","sourceNumber":"354800","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Entre os fatores de risco modificáveis que influenciam na progressão da doença renal\ncrônica, pode-se incluir","options":{"A":"a anemia e a obesidade.","B":"a dislipidemia e a hipertensão arterial.","C":"a proteinúria e a obesidade.","D":"a desnutrição e a anemia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-354845","number":"354845","sourceNumber":"354845","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um Médico de Família, durante o atendimento de um paciente hipertenso, recebe os\nexames complementares de rotina para Hipertensão\nArterial Sistêmica. Dentre os exames, com a\ncreatinina de 1.1 mg/dL foi possível estimar uma taxa de filtração glomerular pela equação\n\nCKD-EPI (revisada em 2021 pela National Kidney Foundation). Taxa de filtração encontrada de 72\nmLmin/1.73 m². Ademais, seu exame de urina dos elementos anormais do sedimento (EAS), não\nrevelou hematúria ou proteinúria. Todavia, o paciente mostrou o exame a um amigo, que trabalha\nna área da saúde, que o assustou com um possivel diagnóstico e o orientou a fazer mais alguns\nexames que traz hoje. O paciente fez uma ultrassonografia de rins e vias urinárias e uma relação\nalbumina/creatinina urinária (RAC) e relação proteína/creatinina urinária. A ultrassonografia\nmostrou\nrins de dimensões e morfologia normas. RAC estava em 6 mg/g de creatinina (valor de referência <\n30 mg/g de creatinina) e relação proteína / creatinina urinária de 0.06 (VR < 0.20). Sobre a\npreocupação do paciente com uma possível doença renal crônica (DRC) e ao nível de prevenção\nem saúde que poderia ter sido aplicado caso procurasse o médico antes, para mostrar os primeiros\nexames, tem-se que:","options":{"A":"o paciente não possui DRC e a prevenção secundária teria sido aplicada.","B":"o paciente possui DRC estágio II e a prevenção quaternária teria sido aplicada.","C":"o paciente possui DRC estágio I e a prevenção secundária teria sido aplicada.","D":"o paciente não possui DRC e a prevenção quaternária teria sido aplicada."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-366929","number":"366929","sourceNumber":"366929","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre desidratação com hipernatremia, é correto afirmar:","options":{"A":"Sintomas incluem letargia, fraqueza muscular e, em casos graves, convulsões e coma.","B":"Hipernatremia refere-se a uma baixa concentração de sódio no sangue.","C":"Hipernatremia resultante de desidratação geralmente ocorre devido a uma ingestão aumentada\nde água.","D":"É mais comum em pacientes jovens devido à sua alta capacidade de reter água."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-362624","number":"362624","sourceNumber":"362624","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em pacientes com DM2 e sem DM2, houve redução da mortalidade, tanto com o uso de\nespironolactona quanto de eplerenone. Podemos indicar com correto que:","options":{"A":"É desnecessário atentar-se para o risco de hipercalemia, que pode ocorrer principalmente em\npacientes com deterioração da função renal e já em uso de IECA ou BRA.","B":"É necessário atentar-se para o risco de hipocalemia, que pode ocorrer principalmente em\npacientes com deterioração da função renal e já em uso de IECA ou BRA.","C":"É necessário atentar-se para o risco de hipercalemia, que pode ocorrer principalmente em\npacientes com deterioração da função renal e já em uso de IECA ou BRA.","D":"É necessário atentar-se para o risco de hipercalemia, que pode ocorrer principalmente em\npacientes com deterioração da função renal e não em uso de IECA ou BRA."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-331968","number":"331968","sourceNumber":"331968","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 78 anos, avaliado por dor em joelho esquerdo. Antecedentes pessoais:\nhipertensão arterial, diabetes, cardiopatia\nisquêmica e doença renal crônica (creatinina 2,1 mg/dL,\nureia 70 mg/dL). Exame físico: PA 132x80 mmHg; FC 70 bpm. Medicado com ibuprofeno. Retorna,\napós 12 dias em tratamento, referindo dispneia e edema de extremidades. PA 178x102 mmHg.\n\nExames laboratoriais: ureia 140 mg/dL; creatinina 4,3 mg/dL; sódio urinário < 20 mEq/L; exame de\nurina: hemácias 2/campo, leucocitos 3/campo, proteinúria ausente. O mecanismo de injúria renal\naguda associada ao uso de anti-inflamatório neste caso é:","options":{"A":"Reação alérgica com nefrite intersticial por droga.","B":"Necrose aguda de papila renal com obstrução.","C":"Necrose tubular aguda induzida por droga.","D":"Vasoconstrição com redução de taxa de filtração glomerular."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-330073","number":"330073","sourceNumber":"330073","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a Insuficiência Renal Aguda (IRA), é CORRETO afirmar:","options":{"A":"A IRA é a interrupção súbita da função renal decorrente de obstrução, circulação aumentada e\ndoença parenquimatosa renal.","B":"A IRA isquêmica é caracterizada pela presença de glomerulopatias, associada à temperatura\nacima de 38o C, leucocitose e hemocultura\npositiva.","C":"A IRA pré-renal ocorre devido à redução do fluxo plasmático renal e queda da taxa da filtração\nglomerular.","D":"A IRA pós-renal é secundária à obstrução extrarrenal, à redução do fluxo plasmático renal e do\nritmo da filtração glomerular."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-339770","number":"339770","sourceNumber":"339770","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente com taxa de filtração glomerular estimada de 17ml/min há mais de três\nmeses tem doença renal crônica em estágio:","options":{"A":"IIIA.","B":"IIIB.","C":"IV.","D":"V."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-346431","number":"346431","sourceNumber":"346431","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Você está de plantão na UTI do hospital e existem 04 pacientes com quadro de lesão\nrenal aguda. Assinale qual destes pacientes possui indicação de hemodiálise de urgência?","options":{"A":"Paciente de 62 anos, admitido por sepse urinária, respirando em ar ambiente, com débito\nurinário de 300ml em 24 horas, potássio de\n5,9 mEq/L, sem edema periférico e com um pH de 7,25;","B":"Paciente de 54 anos admitido por quadro de choque séptico, no momento em ventilação\nmecânica com FiO2 de 80%, diurese 450 ml nas\núltimas 24 horas, com um potássio de 6,6 mEq/L e\numa gasometria com PH de 7,18;","C":"Paciente de 35 anos com quadro de dengue hemorrágica, em ventilação mecânica com uma\nFIO2 de 35%, com uma diurese de 200ml nas últimas 24 horas, com um pH de 7,32, Potássio de\n5,8mEq/L e sem edema periférico;","D":"Paciente com quadro de rabdomiólise pós choque elétrico, respirando com cateter nasal a\n4l/min, com uma diurese em 24 horas de 120mL, um pH de 7,25 e um potássio de 5,5 mEq/L."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-342624","number":"342624","sourceNumber":"342624","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a nutrição do paciente com doença renal crônica do diabetes, é correto afirmar\nque:","options":{"A":"o gasto energético de pacientes em hemodiálise é semelhante ao de indivíduos saudáveis e\naumenta durante e até 2 horas após a diálise","B":"está indicada a manutenção da dieta com 0,8g/kg/d de proteína para reduzir a acidose da IRC","C":"não há necessidade de restituição de sódio no paciente dialítico porque o procedimento retira o\nsal em excesso","D":"a oferta de fósforo não é mais preocupação quando o paciente inicia o tratamento dialítico,\ndevendo ser liberada a dieta e dispensado o uso de quelante de fósforo"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-334129","number":"334129","sourceNumber":"334129","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação à alteração da diurese, assinale a alternativa correta.","options":{"A":"O álcool estimula a secreção da arginina vasopressina (AVP) e, por isso, reduz a diurese.","B":"Os AINEs aumentam a ação da AVP e, por isso, aumentam a diurese.","C":"O álcool inibe a secreção da AVP e, por isso, aumenta a diurese.","D":"Os AINES inibem a ação da AVP e, por isso, reduzem a diurese."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-302830","number":"302830","sourceNumber":"302830","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente de 70 anos, renal crônico em tratamento conservador (última creatinina =\n4,8 mg/dl) foi submetido à cirurgia de urgência devido à diverticulite perfurada. No segundo dia de\npós-operatório, desenvolveu oligúria e queixas de fraqueza muscular, embora estivesse com níveis\npressóricos estáveis e sem sinais de níveis de infecção. Exames laboratoriais mostraram creatinina\n\n= 6,7 mg/dl e potássio = 7,5 mEq/l, ECG mostrava ondas T simétricas e apiculadas, com intervalo\nQRS discretamente alargado. Foram administrados,\nde imediato, gluconato de cálcio e solução de\nglicose e insulina. Qual a próxima medida a ser tomada?","options":{"A":"Hemodiálise","B":"Resinas de troca sônica","C":"Bicarbonato de sódio.","D":"Furosemida","E":"Expectante, monitorizando diariamente os níveis séricos de potássio"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-302838","number":"302838","sourceNumber":"302838","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 3 anos, 17 kg, masculino, sabidamente diabético há 6 meses, foi admitido\nno pronto-socorro com quadro de desidratação, dor\nabdominal, hálito cetônico e os seguintes\nexames: Glicose = 620 mg/dl; Na = 131 mEq/l; K = 4,2 mEq/ l. Recebeu 1.500 ml de soro fisiológico\n(SF 0,9%) e insulina regular contínua por 6 horas. Os exames após esse período são: pH = 7,1;\npCO = 20; Bic = 12; Na = 138; 2 C? = 117; K= 3,5; glicose = 180. A provável etiologia da acidose ao\nfinal das 6 horas do tratamento inicial é:","options":{"A":"Acidose por acúmulo de ácidos não mensurá veis, pois ânion gap é normal.","B":"Acidose hiperclorêmica, pois ânion gap é aumentado.","C":"Acidose hiperclorêmica, pois ânion gap é normal.","D":"Acidose por acúmulo de ácidos não mensuráveis pois ânion gap é aumentado.","E":"Acidose mista: hiperclorêmica + cetoacidose."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-294273","number":"294273","sourceNumber":"294273","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em um caso de paciente com doença renal policística autossômica dominante com taxa\nde filtração glomerular estimada em 28\nml/min, pode-se dizer que ele tem doença renal crônica no\nestágio:","options":{"A":"II.","B":"IIIa.","C":"IIIb.","D":"IV."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-317947","number":"317947","sourceNumber":"317947","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na doença renal policística autossômica dominante, é fator de risco para progressão\npara estágio 5 da doença renal crônica:","options":{"A":"volume renal 1000 cm³.","B":"proteinúria 100 mg/24h.","C":"dois cistos em cada rim aos 30 anos de idade.","D":"urina tipo 1 com hemácias = 8000/ml."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-317948","number":"317948","sourceNumber":"317948","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente do sexo feminino, de 23 anos de idade, 60 kg de peso, apresenta há dois dias\nquadro de febre 39 ºC, calafrios, dores no corpo, astenia, dispneia, urina turva, oligoanúria\n(diurese\n150 ml nas últimas 12 horas), disúria. Exames laboratoriais mostraram: no hemograma, leucócitos\n25000/ul; com 8% de bastões; plaquetas 50.000/ul; Hb 8,0 g/dL; na urina tipo 1, leucócitos\n1.000.000/mL; nitrito +; proteinúria ++; hemácias 1000/mL; creatinina 5,0 mg/dl; urocultura positiva\ncom 100.000 colônias/ml de E. coli, sensível a quinolonas, aminoglicosídeos e carbanepenêmicos.\nUltrassonografia dos rins normal. Pressão arterial 80/50 mmHg, mesmo com uso de dose alta de\ndrogas vasoativas. Saturação de O? 90% com O? nasal a três litros por minuto. Sem edemas, mas\nhidratada. Nesse caso, qual a causa da injúria renal aguda?","options":{"A":"Pré-renal.","B":"Pós-renal.","C":"Nefrotóxica.","D":"Mista."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-311918","number":"311918","sourceNumber":"311918","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"É causa comum de hiponatremia em idosos:","options":{"A":"uso de psicotrópicos e antidepressivos.","B":"hipodipsia do idoso.","C":"uso de diuréticos de alça.","D":"diabetes insipidus neurogênico."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-277393","number":"277393","sourceNumber":"277393","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No paciente com insuficiência renal crônica, a anemia que se desenvolve deve-se\nbasicamente a:","options":{"A":"atrofia da mucosa de corpo gástrico","B":"redução da ingesta alimentar","C":"deficiência de produção de eritropoietina","D":"aplasia da medula óssea"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-277397","number":"277397","sourceNumber":"277397","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A hipocalemia aguda, devido à perda renal de potássio e, acompanhada de alcalose\nmetabólica, deve ser mais provavelmente causada por:","options":{"A":"ureterossigmoidostomia e diuréticos","B":"diuréticos e mineralocorticoides","C":"mineralocorticoides e aminoglicosídeos","D":"diarréia e mineralocorticoides"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-277403","number":"277403","sourceNumber":"277403","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A coagulopatia da doença renal crônica é causada principalmente por:","options":{"A":"produção insuficiente dos fatores da coagulação","B":"disfunção plaquetária","C":"menor concentração de eritropoietina","D":"plaquetopenia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-273141","number":"273141","sourceNumber":"273141","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando o conceito de hiponatremia, é CORRETO afirmar:","options":{"A":"É a redução da glicose abaixo dos níveis considerados normais.","B":"É o aumento de sódio acima dos níveis considerados normais.","C":"É a redução de sódio abaixo dos níveis considerados normais.","D":"É o aumento da glicose acima dos níveis considerados normais."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274463","number":"274463","sourceNumber":"274463","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 33 anos, sexo feminino, branca, casada, G2P1A0 com idade gestacional\nde 36 semanas e 5 dias é encaminhada ao\npronto atendimento, onde você é o plantonista da\nclínica médica. Na chegada, paciente apresentava dor abdominal intensa há quatro horas e\nsangramento vaginal de coloração escurecida há menos de uma hora, sem perda de líquido. Não\napresentou caderneta da gestante ou exames complementares realizados durante o pré-natal.\n\nRefere realização irregular do mesmo, comparecendo apenas a uma consulta desde o diagnóstico\nde gravidez. Referiu que durante a gestação, não\napresentou nenhuma intercorrência, exceto\nalteração pressórica na consulta de pré-natal (IG 23 semanas, aproximadamente), entretanto a\npaciente não refere bem valores pressóricos. Tabagismo iniciado aos 17 anos de idade. Não refere\nnenhuma outra comorbidade. EXAME FÍSICO: ? Geral: Ansiosa e levemente confusa, desidratada\n1+/4+, em regular estado geral, hipocorada 3+/4+, anictérica, acianótica, ausência de\nlinfadenomegalia palpável e de lesões de pele ou mucosa, com edema 1+/4+ em membros\ninferiores, com sudorese em extremidades. ? Sinais Vitais: PA 85x55mmHg; FC: 138 bpm; FR: 30\nirpm; TAX: 35.6 ºC; SatO2: 95%; ? Pulmonar: taquidispnéia e MV+ sem ruídos audíveis. ?\n\nCardíaco: taquicárdica, 2BNF sem sopro audível. ? Sistema digestório: abdome gravídico, com dor\nem hipogástrio e tônus uterino aumentado. Abdômen muito doloroso em hipogástrio. ? Avaliação\nginecológica-obstétrica; ? Ausculta fetal: 112 bpm; ? Altura uterina: 33 cm. ? Tônus uterino:\nhipertonia uterina. ? Genitália externa: sangue no óstio vaginal; ? Especuloscopia: sangramento\nmoderado de origem uterina, sem coágulos em canal vagina. ? Toque Vaginal: colo amolecido e\ncentra, apagado, dilatação de 7 cm e bolsa protrusa. Baseado nos dados clínicos do caso descrito,\nresponda as questões que se seguem: O distúrbio ácido-base mais provável da chegada é:","options":{"A":"Acidose metabólica.","B":"Alcalose metabólica.","C":"Acidose respiratória.","D":"Alcalose respiratória."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274464","number":"274464","sourceNumber":"274464","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 33 anos, sexo feminino, branca, casada, G2P1A0 com idade gestacional\nde 36 semanas e 5 dias é encaminhada ao\npronto atendimento, onde você é o plantonista da\nclínica médica. Na chegada, paciente apresentava dor abdominal intensa há quatro horas e\nsangramento vaginal de coloração escurecida há menos de uma hora, sem perda de líquido. Não\napresentou caderneta da gestante ou exames complementares realizados durante o pré-natal.\n\nRefere realização irregular do mesmo, comparecendo apenas a uma consulta desde o diagnóstico\nde gravidez. Referiu que durante a gestação, não\napresentou nenhuma intercorrência, exceto\nalteração pressórica na consulta de pré-natal (IG 23 semanas, aproximadamente), entretanto a\npaciente não refere bem valores pressóricos. Tabagismo iniciado aos 17 anos de idade. Não refere\nnenhuma outra comorbidade. EXAME FÍSICO: ? Geral: Ansiosa e levemente confusa, desidratada\n1+/4+, em regular estado geral, hipocorada 3+/4+, anictérica, acianótica, ausência de\nlinfadenomegalia palpável e de lesões de pele ou mucosa, com edema 1+/4+ em membros\ninferiores, com sudorese em extremidades. ? Sinais Vitais: PA 85x55mmHg; FC: 138 bpm; FR: 30\nirpm; TAX: 35.6 ºC; SatO2: 95%; ? Pulmonar: taquidispnéia e MV+ sem ruídos audíveis. ?\n\nCardíaco: taquicárdica, 2BNF sem sopro audível. ? Sistema digestório: abdome gravídico, com dor\nem hipogástrio e tônus uterino aumentado. Abdômen muito doloroso em hipogástrio. ? Avaliação\nginecológica-obstétrica; ? Ausculta fetal: 112 bpm; ? Altura uterina: 33 cm. ? Tônus uterino:\nhipertonia uterina. ? Genitália externa: sangue no óstio vaginal; ? Especuloscopia: sangramento\nmoderado de origem uterina, sem coágulos em canal vagina. ? Toque Vaginal: colo amolecido e\ncentra, apagado, dilatação de 7 cm e bolsa protrusa. Baseado nos dados clínicos do caso descrito,\nresponda as questões que se seguem: Considerando o distúrbio acidobásico mais provável, sua\nfórmula de cálculo para avaliação compensatória é:","options":{"A":"0,4 x PCO2 + 8.","B":"1,5 x Bicarbonato + 8.","C":"Bicarbonato + 15.","D":"0,8 x PCO2 + 15."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-258178","number":"258178","sourceNumber":"258178","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A etiologia e um exemplo de lesão renal aguda intrínseca estão descritas\nrespectivamente em:","options":{"A":"Obstrução tubular e aciclovir.","B":"Nefrotoxina e glomerulonefrite rapidamente progressiva.","C":"Vasculite de pequenos vasos e poliarterite nodosa.","D":"Isquemia tubular e corticosteroide."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-285088","number":"285088","sourceNumber":"285088","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Menino, 42 dias de vida, é atendido na Unidade de Emergência Referenciada por\napresentar vômitos há cinco dias. Considerando\no diagnóstico de estenose hipertrófica de piloro o\nresultado esperado da gasometria e dosagem de eletrólitos é:","options":{"A":"Alcalose metabólica, hipocloremia, hipocalemia.","B":"Alcalose respiratória, hipercloremia, hipocalemia.","C":"Alcalose metabólica, hipercloremia, hipercalemia.","D":"Alcalose respiratória, hipocloremia, hipocalemia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274496","number":"274496","sourceNumber":"274496","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Referente à hiponatremia marque a CORRETA:","options":{"A":"No caso de hiponatremia hipertônica a associação mais comum é com a hiperglicemia e a\ncorreção deverá ser realizada de forma rápida com hidratação vigorosa.","B":"A hipoatremia hipotônica pode estar relacionada ao uso de diuréticos tiazídicos e a correção\ndeverá ser realizada de forma lenta elevando\no sódio entre 15 e 20mEq/L nas primeiras 24h.","C":"A hiponatremia hipovolêmica a correção de forma progressiva do sódio ocorre com o uso de\nsoro fisiológico a 0,9%.","D":"A hiponatremia grave está associada a valores de sódio entre 125 e 129mEq/L e rebaixamento\ndo nível de consciência."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-248898","number":"248898","sourceNumber":"248898","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem de 50 anos com quadro de confusão mental iniciada há 2 dias tem história de\nhipertensão arterial, artrite gotosa, hipotireoidismo e tabagismo de 20 anos/maço. Usa alisquireno\n150mg/d e tiroxina 100 microg/d. Os exames laboratoriais no sangue incluem sódio = 122mEq/L,\npotássio = 4mEq/L, cloro = 90mEq/L, bicarbonato = 23mEq/L, creatinina = 1,2mg/dL, glicose =\n130mg/dL e TSH normal. PA = 130x80 mmHg, sem hipotensão postural. Sua urina encontra-se\nconcentrada, com sódio urinário = 60 mEq/L. O paciente não tem edema. O dado da história\nrelevante que pode auxiliar na elaboração do diagnóstico desse paciente é:","options":{"A":"artrite gotosa","B":"uso de alisquireno","C":"hipertensão arterial","D":"tabagismo"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-254219","number":"254219","sourceNumber":"254219","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na evolução da doença renal crônica, qual achado é observado mais precocemente?","options":{"A":"Anemia.","B":"Hiperfosfatemia.","C":"Uremia.","D":"Acidose metabólica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-246536","number":"246536","sourceNumber":"246536","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com 33 anos, portador de insuficiência renal crônica, sem indicação dialítica,\nevoluindo com hiperpotassemia. O K+ sérico apresenta 6,5 mmol/ml (VR. 3,5-5,5 mmol/ml). O\neletrocardiograma não evidenciou anormalidades. Qual das seguintes alternativas é a mais efetiva\npara redução dos níveis séricos de potássio?","options":{"A":"Poliestireno sulfonato de sódio.","B":"Salbutamol.","C":"Bicarbonato de sódio.","D":"Insulina regular.","E":"Gluconato de cálcio."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-248916","number":"248916","sourceNumber":"248916","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São características típicas de pacientes com insuficiência renal pré-renal, exceto:","options":{"A":"osmolalidade de urina >500mOsm/kg","B":"presença de cilindros hialinos","C":"relação sérica ureia/creatinina >40","D":"fração excretada de sódio (FENA) >1%"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-254227","number":"254227","sourceNumber":"254227","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente apresenta o seguinte resultado de gasometria arterial: pH do plasma =\n7,28. HCO3- do plasma = 32 mEq/L e PCO2 do plasma = 70 mmHg. Valores de referência:\npH=7,35-7,45; pCO2=35-45 mmHg; HCO3=22-26 mEq/L. Qual é o distúrbio ácido-básico desse\npaciente?","options":{"A":"Acidose respiratória com compensação renal parcial.","B":"Acidose respiratória aguda sem compensação renal.","C":"Acidose metabólica aguda sem compensação respiratória.","D":"Acidose metabólica com compensação respiratória parcial."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-254228","number":"254228","sourceNumber":"254228","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente apresenta o seguinte resultado de gasometria arterial: pH do plasma =\n7,28. HCO3- do plasma = 32 mEq/L e PCO2 do\nplasma = 70 mmHg. Valores de referência:\npH=7,35-7,45; pCO2=35-45 mmHg; HCO3=22-26 mEq/L. Qual condição clínica pode ter causado o\ndistúrbio ácido-básico do paciente em questão?","options":{"A":"Doença pulmonar obstrutiva crônica.","B":"Uso de diuréticos inibidores da anidrase carbônica.","C":"Cetoacidose diabética.","D":"Diarreia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-229514","number":"229514","sourceNumber":"229514","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa CORRETA em relação aos distúrbios acidobásicos:","options":{"A":"Acidemia se refere ao pH sérico superior a 7,36.","B":"Acidose é definida como o processo patológico que gera alcalemia.","C":"Alcalemia se refere ao pH sérico superior a 7,44.","D":"Alcalose é definida como o processo patológico que gera acidemia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-248923","number":"248923","sourceNumber":"248923","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"É manifestação de hipopotassemia:","options":{"A":"íleo adinâmico","B":"supradesnivelamento do segmento ST nas precordiais direitas","C":"aumento da taxa de filtração glomerular","D":"acidose metabólica"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-234333","number":"234333","sourceNumber":"234333","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"J.L.V., de 65 anos, homem, pardo. Tem antecedentes de diabetes tipo 2 há vinte anos,\nhipertensão arterial há quinze anos e gota há cinco anos. Faz uso regular de anlodipino e\nmetformina, relatando uso ocasional de anti-inflamatórios não hormonais (na vigência de artrite\ngotosa). Passou em consulta médica de check-up com um clínico, que pediu alguns exames:\ncreatinina sérica: 1,6 mg/dl (TFG estimada (CKD-EPI): 46 ml/min), exame de urina: densidade\n1.020, pH 5,5, sem elementos anormais, 1 leucócito/campo, sem hemácias, relação\nalbumina/creatinina na urina: 100 mg/g, glicemia de jejum: 130 mg/dl. A respeito da alteração de\nfunção renal observada, este paciente:","options":{"A":"Possui doença renal crônica G3aA1.","B":"Apresenta creatinina sérica e taxa de filtração glomerular normais para a sua faixa etária, razão\npor que não tem doença renal crônica.","C":"Deve ser observado um maior período de tempo para determinar se ele tem ou não doença\nrenal crônica.","D":"Deve ser submetido a um controle glicêmico rigoroso e a uma dieta com aporte proteico < 0,6\ng/kg/dia, medidas recomendadas para o seu tratamento."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-232234","number":"232234","sourceNumber":"232234","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 47 anos, do sexo masculino, é levado ao pronto atendimento por\napresentar rápida deterioração do estado\nmental. À admissão, dosagem de sódio plasmática se\nencontrava em 110 mEq/L. Demais exames laboratoriais sem alteração. Após 24 horas, foi\nsolicitada avaliação do neurologista, pois o paciente apresentava tetraparesia grave e discurso\nincoerente, apesar da dosagem de sódio plasmático se encontrar mais próxima do fisiológico (142\nmEq/L). Reflexos osteotendíneos aumentados foram percebidos ao exame físico. Qual exame é\nmais adequado para elucidar as alterações motoras manifestadas por este paciente?","options":{"A":"Estudo eletrofisiológico (eletroneuromiografia), para avaliar polineuropatia e/ou miopatia do\ndoente crítico.","B":"Ressonância nuclear magnética, para avaliar desmielinização do trato corticoespinhal.","C":"Tomografia de crânio, para avaliar hemorragia lobar bilateral.","D":"Repetição de dosagem de eletrólitos, pois o sódio plasmático provavelmente voltou a níveis\ndiminuídos novamente."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-234334","number":"234334","sourceNumber":"234334","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 50 anos come um salgado que estava na prateleira do comércio há três dias,\nna temperatura ambiente. Horas depois, apresenta náuseas e vômitos, logo em seguida diarreia\nprofusa. Ela tenta tomar soro oral, mas não melhora. No dia seguinte, procura o pronto-socorro e\nrecebe hidratação venosa. Melhora um pouco e volta para casa. À noite, com febre alta, persistindo\na diarreia, procura um hospital onde acaba sendo internada na UTI. Então, estava com pressão\narterial = 80/42 mmHg, temperatura de 39 ºC, SAT O? 88% no ar ambiente. Submetida à\nhidratação rápida, ventilação não invasiva, foram colhidos exames que mostraram Hb = 16 g/dL,\nleucócitos 42.000/mm³, bastões 18%, plaquetas 35.000, lactato 25 mg/dl. Como a PA não\nmelhorou, iniciou-se noradrenalina. A creatinina, que dias antes era de 0,6 mg/dL, agora estava em\n3,5 mg/dl e a ureia, respectivamente, 21 mg/dl e 138 mg/dl. Nesse caso, qual é a causa do\naumento da creatinina?","options":{"A":"Necrose tubular aguda.","B":"Lesão renal aguda pré-renal.","C":"Lesão renal aguda pós-renal.","D":"Lesão renal aguda mista."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-229531","number":"229531","sourceNumber":"229531","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança com 4 anos de idade, previamente hígida, sem queixas recentes e deixada\ndesassistida em domicilio, é encontrada na garagem se sua casa, desacordada; levada ao pronto\nsocorro sem informações claras do que havia ocorrido. A gasometria revelou: pH= 7,1; pCO2=\n12mmHg; HCO3= 8mEq/L; Cl= 104mEq/L; Na= 140mEq/L. Sobre os diagnósticos etiológico e\ngasométrico mais adequados para o paciente, assinale a alternativa CORRETA:","options":{"A":"Intoxicação exógena; acidose metabólica e alcalose respiratória.","B":"Insuficiência respiratória aguda com acidose respiratória.","C":"Choque séptico com acidose metabólica hiperclorêmica.","D":"Cetoacidose por jejum prolongado: acidose metabólica com ânion gap aumentado."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-241736","number":"241736","sourceNumber":"241736","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O diabetes insipidus (DI) pode decorrer de deficiência na produção de vasopressina, no\nDI central, ou de insensibilidade a ela, no DI nefrogênico. Sua origem pode ser congênita ou\nsecundária a diversas causas. Sobre o DI, assinale a alternativa incorreta.","options":{"A":"Poliúria e polidipsia são apresentações clínicas comuns do DI, assim como no diabetes mellitus.","B":"No DI central de origem congênita, a herança é autossômica dominante; na DI nefrogênica\ncongênita, a herança pode ser autossômica dominante, recessiva ou ligada ao X.","C":"Algumas medicações podem ocasionar DI adquirida e ter repercussão tanto central como renal.","D":"O DI nefrogênico é mais comumente decorrente de causas genéticas e, normalmente, suas\napresentações são menos severas que aquele de causas adquiridas.","E":"A terapia hídrica no DI central de lactentes costuma apresentar boa resposta, devido às altas\nnecessidades de ingesta hídrica dessa faixa etária."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-229880","number":"229880","sourceNumber":"229880","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente admitido com quadro agudo de náuseas, vômitos, oligúria e confusão mental.\nLaboratório da admissão revelou aumento de escorias nitrogenadas, hiponatremia e hipocalemia.\nAssinale a alternativa que NÃO se enquadra nas causas do quadro clínico do paciente","options":{"A":"leptospirose.","B":"uso de Aminoglicosídeo.","C":"uso de anfotericina B.","D":"rabdomiólise."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-201908","number":"201908","sourceNumber":"201908","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma criança de 1 ano foi admitida na Emergência por febre e vômitos persistentes. Nas\núltimas 6 horas, não havia urinado. Ao exame físico, estava com taquicardia, taquipneia, pulsos\nfinos, palidez cutânea e má perfusão periférica. Sua pressão arterial era normal. Os exames\nlaboratoriais revelaram acidose metabólica, anemia, hipercalemia e hipernatremia. Nesse casso, a\ncorreção da desidratação com infusão rápida de volume pode provocar:","options":{"A":"diabetis insipidus","B":"edema cerebral","C":"hemorragia cerebral","D":"hipotensão arterial","E":"insuficiência renal aguda"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-210548","number":"210548","sourceNumber":"210548","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a investigação da insuficiência renal aguda por métodos de imagem, assinale a\nalternativa correta.","options":{"A":"Na ultrassonografia a relação córtex-medular identifica a cronicidade da alteração renal.","B":"Rins reduzidos de tamanho no ultrassom podem sugerir mieloma ou amiloidose.","C":"O contraste utilizado na ressonância pode levar à fibrose sistêmica nefrogênica, devendo ser\nevitado se clearance <30mL/min.","D":"A biópsia renal é indicada tardiamente na dúvida diagnóstica em quadro decorrente de vasculite\nsistêmica.","E":"A cintilografia é útil na pesquisa da função renal e pouco empregada para avaliar fluxo renal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-218226","number":"218226","sourceNumber":"218226","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O distúrbio eletrolítico mais comumente associado ao íleo paralítico e vômitos, no\npós-operatório de cirurgia abdominal, é:","options":{"A":"Hipocalemia.","B":"Hipocalcemia.","C":"Hipercalemia.","D":"Hiponatremia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-214943","number":"214943","sourceNumber":"214943","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considerando a gasometria arterial descrita a seguir, qual é o diagnóstico gasométrico\ne quais são as prováveis patologias causadoras?\npH = 7,2, pCO2 = 32mmHg, p02 = 69mmHg,\nbicarbonato = 9mEq/L, BE: -7, Saturação de 02 =83%.","options":{"A":"acidemia respiratória, enfisema pulmonar associado a pneumonia","B":"acidose respiratória, DPOC exacerbada por traqueobronquite aguda","C":"acidemia metabólica, sepse de origem pulmonar","D":"acidose mista, síndrome da angústia respiratória aguda por sepse"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-202723","number":"202723","sourceNumber":"202723","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente com nefropatia diabética apresenta clearance de creatinina de 16 ml/min.\nEle tem insuficiência renal crônica estágio:","options":{"A":"2.","B":"3a.","C":"3b.","D":"4."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-201654","number":"201654","sourceNumber":"201654","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente internado há três dias na UTI, devido à\ninsuficiência respiratória secundária a\npneumonia, encontra-se em ventilação mecânica, em uso de\ndroga vasoativa (noradrenalina), de meropenem e vancomicina, com indicação de início de terapia\nrenal substitutiva (TRS). Apresenta os seguintes exames laboratoriais, diurese e balanço hídrico a\ncada 24 horas: Neste caso clínico, o método dialítico a ser adotado e a principal indicação de\ninício\nda TRS são:","options":{"A":"Hemodiálise estendida, balanço hídrico positivo acumulado.","B":"Hemodiálise clássica, acidose metabólica.","C":"Hemodiálise clássica, hipercalemia.","D":"Diálise peritoneal ambulatorial contínua (CAPD), sintomas urêmicos."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-201662","number":"201662","sourceNumber":"201662","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A Injúria Renal Aguda (IRA) é uma condição comum e associada a piores desfechos\nclínicos. De acordo com as diretrizes de IRA KDIGO 2012, tendo em vista as medidas de\nprevenção da IRA:","options":{"A":"A utilização de coloides com albumina, o dextran ou gelatinas é preferível no manuseio inicial da\nexpansão volêmica em pacientes com IRA.","B":"O uso dos diuréticos de alça é uma estratégia consagrada para prevenção e tratamento da IRA,\numa vez que está bem estabelecido que a IRA não oligúrica apresenta prognóstico melhor que a\nIRA oligúrica.","C":"O uso da N-acetilcisteína na prevenção da IRA pós-contraste é questionável; no entanto, o seu\nbenefício na prevenção da IRA no pós-operatório de grandes cirurgias, como cirurgias cardíacas, é\nbem fundamentado.","D":"As formulações lipídicas de anfotericina B estão associadas a menor risco de nefrotoxicidade do\nque as formulações convencionais."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-216479","number":"216479","sourceNumber":"216479","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Marque a alternativa INCORRETA:","options":{"A":"A causa primária da anemia na doença renal crônica é a produção insuficiente de eritropoetina.","B":"Pacientes com insuficiência renal crônica possuem maior risco de sangramentos, por distúrbios\nda hemostasia.","C":"Na insuficiência renal crônica, podem ocorrer distúrbios do metabolismo do cálcio. Quando isso\nocorre, há redução dos níveis de PTH (paratormônio) e hipercalcemia.","D":"A doença cardiovascular é a principal causa de morte em pacientes com insuficiência renal\ncrônica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215465","number":"215465","sourceNumber":"215465","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual é o mecanismo natural de defesa contra a hiperosmolaridade e hipovolemia?","options":{"A":"Fome.","B":"Sede.","C":"Queda de PA.","D":"Aumento de PA."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215466","number":"215466","sourceNumber":"215466","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Quanto à excreção renal de sódio, assinale a alternativa INCORRETA.","options":{"A":"O duto coletor é o segmento onde acontece a reabsorção de sódio.","B":"A aldosterona dificulta a abertura de canais de sódio em casos de hipovolemia.","C":"Em situações de hipervolemia, ocorre liberação de peptídeo natriurético atrial.","D":"O peptídeo natriurético atrial inibe a reabsorção de sódio."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-215348","number":"215348","sourceNumber":"215348","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação à secreção inapropriada do HAD, assinale a alternativa INCORRETA.","options":{"A":"Quanto menor a natremia e mais rápida a sua queda, mais graves são os sintomas.","B":"Os sintomas mais frequentes decorrem de edema cerebral e consequente aumento da pressão\nintracraniana.","C":"Na maioria das vezes, ocorre hipervolemia e edema, pois a maior parte do líquido é retida no\ncompartimento extracelular.","D":"Em crianças, a hiponatremia aguda manifesta sinais de encefalopatias com concentrações\nplasmáticas de sódio mais elevadas em comparação aos adultos."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-205629","number":"205629","sourceNumber":"205629","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação à doação de rim inter vivos, qual das alternativas abaixo NÃO é uma\ncontraindicação?","options":{"A":"IMC > 40.","B":"Diabetes.","C":"Malignidade ativa.","D":"DPOC."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-214133","number":"214133","sourceNumber":"214133","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No portador de insuficiência renal crônica não é recomendado a exposição a:","options":{"A":"Aminoglicosídeos, anti-inflamatórios não hormonais (AINH).","B":"Cisplatina/Contraste de exames radiológicos.","C":"As alternativas A e B estão corretas.","D":"Somente a alternativa A está correta."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-178764","number":"178764","sourceNumber":"178764","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, internado em unidade de terapia intensiva devido\nà hemorragia subaracnoidea. Evolui com síndrome\ncerebral perdedora de sal (SCPS). Sobre a\nSCPS, leia as afirmativas. I- É uma condição clínica não totalmente compreendida do ponto de vista\nde sua patogênese.; II- A secreção inapropriada de hormônio diurético (SIADH) é o principal\ndiagnóstico diferencial da SCPS.; III- A apresentação clínica mais comum é: poliúria com natriurese,\nosmolalidade urinária elevada, osmolalidade plasmática baixa e hipovolemia. Está correto o que se\nafirma em:","options":{"A":"I, somente.","B":"II, somente.","C":"III, somente.","D":"I e II, somente.","E":"todas."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-182450","number":"182450","sourceNumber":"182450","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Durante procedimentos eletivos de cirurgia que requerem infusão moderada de volume\nnos pacientes, o uso de somente soro fisiológico a 0,9% pode causar:","options":{"A":"acidose metabólica hiperclorêmica com ânion-gap normal","B":"alcalose metabólica hipercalcêmica com ânion-gap normal","C":"calose metabólica hipoclorêmica com ânion-gap reduzido","D":"acidose metabólica hipocalêmica com ânion-gap aumentado"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187707","number":"187707","sourceNumber":"187707","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação à lesão renal aguda (LRA) pode-se afirmar que:","options":{"A":"A LRA mais comum é a de origem pré-renal.","B":"A LRA pré-renal é infreqüente dentro de unidades hospitalares.","C":"Os antiinflamatórios não hormonais não causam LRA pré-renal.","D":"Sepse e insuficiência cardíaca não representam etiologias de LRA pré-renal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-178786","number":"178786","sourceNumber":"178786","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A insuficiência renal aguda na sepse, conhecida como \"rim da sepse\", está relacionada\nà lesão:","options":{"A":"Pré-renal por hipovolemia.","B":"Pré-renal por deficiência do débito cardíaco e da pressão de perfusão renal.","C":"Renal por mediadores inflamatórios e alteração da função tubular e glomerular.","D":"Renal por mediadores inflamatórios e necrose tubular aguda precoce.","E":"Pós-renal por retenção vesical."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-173513","number":"173513","sourceNumber":"173513","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"O transplante renal deve ser realizado, preferencialmente, pelo uso do rim do lado\nesquerdo. O motivo desta preferência é:","options":{"A":"a artéria renal esquerda é mais longa que a direita.","B":"a veia renal esquerda é mais longa que a direita.","C":"o rim direito está em uma posição mais alta que o esquerdo.","D":"o rim esquerdo está em uma posição mais alta que o direito."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-186518","number":"186518","sourceNumber":"186518","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente do sexo masculino, 24 anos, alcoolista, pedreiro em um grande edifício, dá\nenrada em pronto-socorro após barra de ferro\nter caído sobre suas pernas há 6 horas. O paciente\nchegou estável hemodinamicamente. Foram realizados os cuidados elementares do trauma no\natendimento do paciente e posicionada sonda vesical de demora para monitoração do débito\nurinário, que era de 0,5 ml/kg/h. Após 36 horas do acidente, a enfermaria notou escurecimento\ndiscreto da urina e o débito urinário foi reduzido para 0,3 ml/kg/h por mais de 6 horas apesar de\nhidratação adequada. O exame sumário de urina evidenciou cilindros granulosos pigmentares.\n\nUreia de 70 mg/dL (referência: 10 a 50 mg/dL) e creatinina de 3,3 mg/dL (referências para homens:\n0,7 a 1,3 mg/dL); creatinofosfoquinase\nsérica total 12.000 U/mL. A fração excretória de sódio é de\n3%. Diante do quadro clínico exposto, a principal hipótese diagnóstica é:","options":{"A":"Injúria renal aguda intrínseca por rabdomiólise.","B":"Injúria renal aguda pré-renal por hemorragia decorrene do trauma.","C":"Injúria renal aguda intrínseca por hemorragia decorrente do trauma.","D":"Injúria renal aguda pré-natal decorrente de síndrome hepatorrenal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-182425","number":"182425","sourceNumber":"182425","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Analise as seguintes definições relacionadas ao equilíbrio acidobásico: I - pH\nsanguíneo > 7,45 ; II - pH sanguíneo < 7,35 ; III - Distúrbio com tendência a alcalemia ; IV -\nDistúrbio com tendência a acidemia. As definições referem-se, respectivamente, à:","options":{"A":"acidemia, alcalemia, acidose, alcalose","B":"alcalemia, acidemia, alcalose, acidose","C":"alcalemia, acidemia, acidose, alcalose","D":"acidemia, alcalemia, alcalose, acidose"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-174484","number":"174484","sourceNumber":"174484","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre os Distúrbios do Potássio, é correto afirmar que:","options":{"A":"A hiperpotassemia pode ser causada pela administração de antagonistas de receptor\nmineralocorticoide e beta-adrenérgicos.","B":"Na hipercalemia, observa-se aumento de amplitude das ondas P e U, no eletrocardiograma.","C":"Redistribuição para o espaço intracelular, acidose e estado anabólicos podem causar\nhipocalemia.","D":"A hiperpotassemia despolariza a membrana celular do miocárdio, torna mais lenta a condução\nventricular e reduz a duração do potencial de ação."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-174495","number":"174495","sourceNumber":"174495","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 13 anos, previamente hígido, chega a emergência com histórico de três\ndias de febre, adinamia e mialgia intensa e\ngeneralizada. Ao exame, encontra-se em regular estado\ngeral, acianótico, pálido, anictérico, afebril, eupneico, com boa perfusão periférica e pulsos\ncheios.\nAparelhos cardiovasculares e respiratórios sem alterações; abdome doloroso à palpação superficial\ne profunda, RHA +; dor à palpação da musculatura esquelética; sem sinais meníngeos; oroscopia\ncom hiperemia e aumento de tonsilas palatinas, sem placas. Seus exames laboratoriais são\npotássio de 7 mEq/l e gasometria com pH igual a 7,39. Já foi realizado gluconato de cálcio para\nestabilizar as fibras miocárdicas, na sequência, para dar continuidade ao tratamento da\nhiperpotassemia, decide-se utilizar medicamentos que promovam a entrada de potássio na célula,\naumentando sua concentração intracelular, tais como:","options":{"A":"Sorcal e Insulina Simples.","B":"Bicarbonato de Sódio e Furosemida.","C":"Furosemida e Nitroprussiato De Sódio.","D":"Insulina Simples e Salbutamol."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-174114","number":"174114","sourceNumber":"174114","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual dos imunossupressores usados atualmente em transplante renal tem maior\npotencial para causar dislipidemia?","options":{"A":"Tacrolimus.","B":"Ciclosporina.","C":"Everolimus.","D":"Micofenolatos."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-174515","number":"174515","sourceNumber":"174515","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Jonathan, 9 anos, encontra-se intubado em UTI pediátrica, com diagnósticos de choque\nhemorrágico/distributivo causado por dengue, associado à sangramento pulmonar profuso. A\ngasometria de hoje apresenta pH=7,29; pCO?=30; BIC=12. O distúrbio ácido-básico encontrado é:","options":{"A":"Acidose respiratória pura, pois o PCO2 deveria estar menor para deixar o ph mais próximo do\naceitável, e o BIC está tentando compensar o distúrbio.","B":"Acidose metabólica pura, pois PCO2 esperado é de 30 a 34.","C":"Acidose metabólica pura, com tentativa de compensação do distúrbio apresentado com\ndiminuição do PCO2, que está abaixo do valor da normalidade.","D":"Acidose mista com PCO2 esperado de 24 a 28."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-185148","number":"185148","sourceNumber":"185148","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na avaliação de um paciente com insuficiência renal aguda, a presença de cilindros\ngranulosos e células epiteliais é indicativo de","options":{"A":"necrose tubular aguda.","B":"glomerulonefrite proliferativa.","C":"nefrolitíase.","D":"mieloma múltiplo."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187579","number":"187579","sourceNumber":"187579","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São indicações de diálise de emergência na injúria renal aguda:","options":{"A":"pericardite urêmica e hipercalemia refratária.","B":"hipercalemia refratária e oligúria.","C":"sintomas urêmicos e oligúria.","D":"Oligúria e pericardite urêmica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187587","number":"187587","sourceNumber":"187587","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente portador de miocardiopatia dilatada de etiologia isquêmica em tratamento\nregular procura o ambulatório de cardiologia\ncom quadro de astenia importante, mal estar e\ntonturas. Na avaliação clínica, o paciente encontra-se com FC de 56 bpm e PA 96 x 58mmHg, sem\noutros achados significativos. Foi realizado um eletrocardiograma que evidenciou aumento do\nintervalo QT, depressão do segmento ST e da onda T, e surgimento de onda U. O diagnóstico é","options":{"A":"hiponatremia.","B":"hipercalcemia.","C":"hipopotassemia.","D":"intoxicação digitálica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187609","number":"187609","sourceNumber":"187609","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre a anemia na insuficiência renal crônica, tem-se que,","options":{"A":"decorre da hematúria macroscópica provocada pela insuficiência renal crônica.","B":"tem padrão hemolítico associada aos anticorpos anti-eritropoetina.","C":"geralmente é aplástica com pancitopenia.","D":"sua principal causa é a diminuição da produção de eritropoetina."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-187554","number":"187554","sourceNumber":"187554","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente 55 anos, com antecedente de cirurgias abdominais prévias, apresenta quadro\nde abdome agudo obstrutivo por aderências ao\nnível de ileo terminal e distensão de alças a\nmontante. Desfeita a causa mecânica do abdome agudo, porém manteve fistulização do intestino\ndelgado. Decide-se malaxar o conteúdo das alças para facilitar o fechamento da parede abdominal.\nApós drenagem de grande quantidade de líquido das alças do delgado, a paciente evoluiu com\nchoque hipovolêmico e","options":{"A":"hipocalemia e alcalose metabólica.","B":"hipocalemia e acidose metabólica.","C":"hipercalemia e alcalose metabólica.","D":"hipocalcemia e acidose metabólica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-174164","number":"174164","sourceNumber":"174164","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na conceituação de equilíbrio acidobásico:","options":{"A":"pH elevado e PaCO2 elevado = acidose respiratória.","B":"HCO3 diminuído e pH diminuído = acidose metabólica.","C":"pH diminuído e HCO3 elevado = alcalose metabólica.","D":"pH diminuído e PaCO2 diminuído = alcalose metabólica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-158477","number":"158477","sourceNumber":"158477","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual das alternativas abaixo apresenta somente causas de hiperfosfatemia?","options":{"A":"Lesão renal aguda e Síndrome de Fanconi.","B":"Lesão renal aguda e acromegalia.","C":"Acromegalia e alcoolismo.","D":"Síndrome de Fanconi e alcoolismo."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-149190","number":"149190","sourceNumber":"149190","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual das soluções abaixo apresenta concentrações de sódio e cloro mais próximas das\nobservadas no plasma?","options":{"A":"Plasma fresco congelado.","B":"Soro glicosado a 5%.","C":"Ringer lactato.","D":"Soro fisiológico a 0,9%."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-150857","number":"150857","sourceNumber":"150857","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Leia o caso clínico a seguir: Paciente de 27 anos submetido a transplante renal há\ncerca de seis meses, em uso de\nimunossupressão e com enxerto funcionante e creatinina normal.\nRetorna ao serviço de transplante queixando-se de astenia progressiva. É constatada anemia.\n\nPaciente evolui com piora progressiva da anemia associada à necessidade transfusional e queixa\nde episódios febris ocasionais, sem sinais de\nsangramento. Não tem adenomegalias ou\nvisceromegalias palpáveis. Hematologista optou por realizar aspirado de medula óssea, que\nevidenciou hipoplasia acentuada do setor eritroide com presença de proeritroblastos gigantes.\n\nNesse caso, qual é a hipótese diagnóstica?","options":{"A":"Hemólise microangiopática secundária a ciclosporina.","B":"Deficiência de eritropoetina.","C":"Infecção por Parvovírus B19.","D":"Anemia hemolítica autoimune."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-150696","number":"150696","sourceNumber":"150696","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"I.F.S., de 26 anos, branca, do sexo feminino, portadora de diabetes mellitus desde os\ndez anos, procura ambulatório para retorno\ncom exames. Peso: 52 kg; 1,68 de altura. Vem\napresentando nas últimas consultas precário controle glicêmico e com última HbA1 em 9,2%,\nglicemia de jejum 212 mg/dL e pós-prandial de 264 mg/dL. Eletrocardiograma normal e radiografia\nde tórax sem alterações. Ela apresenta microalbuminúria de 72 mcg/min com creatinina de 0,64\nmg/dL e é paciente orientada sobre necesidade de adesão ao tratamento face às alterações renais\napresentadas. Nesse caso, qual é o estágio de doença renal e qual medida adicional deve ser\ntomada?","options":{"A":"Estágio I, sem indicação de uso de inibidor da enzima de conversão da angiotensina.","B":"Estágio I, com indicação de uso de inibidor da enzima de conversão da angiotensina.","C":"Estágio II, com indicação de uso de inibidor da enzima de conversão da angiotensina.","D":"Estágio II, sem indicação de uso de inibidor da enzima de conversão da angiotensina."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-150704","number":"150704","sourceNumber":"150704","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"S.M.U., de 24 anos, é avaliado em parecer após politrauma grave. Vítima de acidente\nde moto, com fratura exposta de fêmur e lesão\nhepática com correção cirúrgica, durante o\ntransporte apresentou hipotensão grave com ressuscitação volêmica, voltando a apresentar\npressão sistólica acima de 100 mmHg após cinco horas do acidente, na recuperação anestésica.\nDurante pós-operatório, apresentou diminuição da diurese com urina escurecida. Houve piora dos\nníveis séricos de creatinina de 0,6 mg/dl do 1º pós-operatório para 6,2 mg/dl no 4º pós-operatório\ncom ureia de 210 mg/dl. A excreção fracionada de sódio estava em 7%. Com base no exposto,\ninfere-se como etiologia para perda de função renal a:","options":{"A":"Insuficiência renal pré-renal.","B":"Necrose cortical bilateral.","C":"Nefrite tubulointersticial aguda.","D":"Necrose tubular aguda."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-150711","number":"150711","sourceNumber":"150711","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um senhor de 58 anos, com doença renal crônica secundária à hipertensão arterial\nsistêmica e clearance de creatinina de 13\nml/min, apresenta-se no pronto atendimento com queixa\nde cefaleia, confusão mental e paresia do braço direito. Na tomografia de crânio, há um hematoma\nsubdural frontal esquerdo. Nesse caso, qual das seguintes condições têm maior associação com a\nhemorragia intracraniana?","options":{"A":"Deficiência de vitamina B12.","B":"Disfunção plaquetária urêmica.","C":"Mutação do fator V de Leiden.","D":"Anticorpo antifosfolipídeo."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-156531","number":"156531","sourceNumber":"156531","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"O distúrbio acidobásico metabólico apresenta, inicialmente, alteração da fração da PaCO2","B":"O distúrbio acidobásico respiratório apresenta, primariamente, alteração da fração HCO3","C":"Alcalose metabólica se define pela diminuição do pH plasmático","D":"Acidose respiratória se define pela incapacidade dos pulmões de eliminar adequadamente o\nCO2"},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-149212","number":"149212","sourceNumber":"149212","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em criança com hiperpotassemia, qual das medidas abaixo NÃO está indicada no\ntratamento?","options":{"A":"Inalação com beta-2-agonista.","B":"Furosemida.","C":"Solução polarizante (glicose + insulina).","D":"Expansão com soro glicosado."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-157367","number":"157367","sourceNumber":"157367","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre os biomarcadores precoces de Insuficiência Renal Aguda (IRA), é CORRETO\nafirmar que:","options":{"A":"A sua utilidade não foi demonstrada na IRA pediátrica.","B":"No período neonatal, sua excreção urinária pode estar relacionada à idade gestacional e ao\npeso de nascimento.","C":"Dificuldades técnicas, comprovadamente, impedem a sua avaliação na urina.","D":"Já foram incorporados à prática clínica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-157372","number":"157372","sourceNumber":"157372","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Entre as contraindicações absolutas de diálise peritoneal está:","options":{"A":"A síndrome de Prune Belly.","B":"A presença de derivação ventrículo-peritoneal.","C":"O período neonatal.","D":"O pós-operatório imediato de cirurgia abdominal."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-157378","number":"157378","sourceNumber":"157378","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A hemofiltração venosa contínua é melhor do que a diálise peritoneal porque:","options":{"A":"É tecnicamente mais fácil.","B":"Permite ultrafiltração mais precisa e melhor remoção de solutos.","C":"Não requer anticoagulação.","D":"Permite intrafiltração mais precisa e menor remoção de solutos."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-136556","number":"136556","sourceNumber":"136556","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Por que a solução fisiológica a 0,9% NÃO é de fato fisiológica?","options":{"A":"Devido à concentração de sódio e cloro ser maior que a concentração sérica do plasma.","B":"Devido à concentração de cálcio ser maior que a concentração sérica do plasma.","C":"Devido à concentração de potássio ser maior que o potássio plasmático.","D":"Devido à concentração de sódio e potássio ser maior que a concentração plasmática."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-127283","number":"127283","sourceNumber":"127283","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"PH = 7,38; PaCO2 = 12; BE = -23. Ao interpretar os dados desta gasometria arterial, a\ncondição MAIS provável para estes achados é","options":{"A":"Choque.","B":"Acidose metabólica compensada com alcalose respiratória.","C":"Alcalose respiratória compensada com acidose metabólica.","D":"Insuficiência ventilatória."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-136611","number":"136611","sourceNumber":"136611","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Distúrbios hidroeletrolíticos mostram um grande desafio para o dia a dia de quem lida\ncom os pacientes. Qual destas medicações NÃO interage com a concentração sérica do potássio?","options":{"A":"Succinil colina.","B":"Insulina.","C":"Gluconato de cálcio.","D":"Bicarbonato de Sódio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-138618","number":"138618","sourceNumber":"138618","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação à Doença Renal Crônica (DRC), é INCORRETO afirmar que:","options":{"A":"A taxa de filtração glomerular entre 15-29 ml/min traduz quadro de DRC grave ou clínica.","B":"Recomenda-se uso de inibidor da enzima conversora da angiotensina ou antagonista do\nreceptor da angiotensina II para controle da proteinúria.","C":"A anemia não é um fator de risco cardiovascular na DRC.","D":"O paratormônio é um marcador de doença óssea na DRC."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-137031","number":"137031","sourceNumber":"137031","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança com dez anos de idade encaminhada ao pronto-atendimento médico com\nquadro de cianose, tiragens subcostais e\nintercostais, taquidispneia. Solicitada gasometria que\nmostrou os seguintes valores: PH 7,30 HCO3 26; PCO2 50; PO2 90; Sat O2 97; BE - 3. Qual a\nprovável patologia dessa criança?","options":{"A":"Obstrução respiratória.","B":"Hiperaldosteronismo primário.","C":"Intoxicação Salicílica.","D":"Cetoacidose diabética."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-103633","number":"103633","sourceNumber":"103633","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Entende-se hipovolemia por um volume de sangue menor do que o normal, e que pode\nocorrer:","options":{"A":"Por perda de sangue total, plasma, água e sal, e dissecação.","B":"Somente por perda de sangue total.","C":"Às vezes por perda de sangue, água e sal.","D":"Duas acima estão certas."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-111401","number":"111401","sourceNumber":"111401","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São causas de hipopotassemia, exceto:","options":{"A":"Doença de Addison.","B":"Vômitos e diarreias.","C":"Tratamento com Anfotericina B.","D":"Diurese osmótica.","E":"Insulinoterapia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-101174","number":"101174","sourceNumber":"101174","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com doença renal crônica, anúrica, em hemodiálise há cinco anos, procura a\nemergência com queixas de fraqueza muscular generalizada e incapacidade para deambulação. A\navaliação laboratorial evidencia: creatinina = 5,0 mg/dl; ureia = 120 mg/dl; potássio = 7,5 mEq/L;\npH\n\n= 7,34; bicarbonato = 22. O eletrocardiograma apresenta ondas T apiculadas e achatamento da\nonda P. A conduta para reduzir mais\nrapidamente a concentração plasmática de potássio, nesse\npaciente, é a:","options":{"A":"Administração intravenosa de gluconato de cálcio.","B":"Administração intravenosa de diurético de alça.","C":"Administração por nebulização de agonista beta-2 adrenérgico.","D":"Administração oral e por enema retal de resina de troca."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-101234","number":"101234","sourceNumber":"101234","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma gestante com 40 semanas de idade gestacional e portadora de diabetes mellitus\ntipo 1 foi admitida para realizar uma\ncesariana devido ao pós-datismo. Na ocasião, apresentava\nhemoglobina glicosilada de 10% e diminuição dos movimentos fetais. Durante a cesariana, foi\nobservado que o líquido aminiótico era meconial +++/4+. O recém-nascido chorou logo que nasceu\ne, ao ser recebido, apesar do choro forte e da frequência cardíaca de 120 bpm, encontrava-se com\ncianose central. Após estabilização, o recém-nascido necessitou ser mantido em ventilação\nmecânica invasiva e, apesar da fração de oxigênio ofertada de 100%, ainda mantinha cianose\ncentral e saturava 60%. Foram realizadas radiografia de tórax e gasometria arterial, cujos\nresultados são apresentados a seguir (VER IMAGEM). Gasometria arterial: pH = 7,30; PCO2 = 42;\nPO2 = 40; bicarbonato = 15; BE = -10; Sat = 57%. Os resultados da gasometria arterial são\nindicativos de:","options":{"A":"acidose metabólica e hipóxia.","B":"acidose mista e hipóxia.","C":"acidose respiratória e hipóxia.","D":"gasometria venosa, devendo ser realizada nova coleta para a confirmação."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-103681","number":"103681","sourceNumber":"103681","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A dosagem de soro fisiológico administrada para iniciar a ressuscitação volumétrica em\nqualquer tipo de choque é de:","options":{"A":"10 ml/kg em10 minutos.","B":"20 ml/kg em 20 minutos.","C":"13 ml/kg em 15 minutos.","D":"25 ml/kg em 15 minutos."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-83657","number":"83657","sourceNumber":"83657","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um homem de 72 anos, em pós-operatório de cirurgia de grande porte, apresenta\nletargia progressiva e convulsão. Qual distúrbio\nprovavelmente é responsável por esse quadro?","options":{"A":"Hipopotassemia.","B":"Hipomagnesemia.","C":"Hipoglicemia.","D":"Hipocalcemia.","E":"Hiponatremia."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-84374","number":"84374","sourceNumber":"84374","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Considera-se hipomagnesemia neonatal quando os níveis plasmáticos de magnésio\nforem inferiores a:","options":{"A":"1,5 mg/dl.","B":"9 mg/dl.","C":"2,5 mg/dl.","D":"2 mg/dl.","E":"6 mg/dl."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-85355","number":"85355","sourceNumber":"85355","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale as duas complicações comuns do adenoma viloso de cólon.","options":{"A":"Diarreia/acidose metabólica.","B":"Constipação/malignização.","C":"Diarreia/alcalose metabólica.","D":"Constipação/acidose metabólica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-84413","number":"84413","sourceNumber":"84413","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Os distúrbios eletrolíticos associados ao Diabetes Insípido nefrogênico são:","options":{"A":"Hipercalcemia e hipopotassemia.","B":"Hipocalcemia e hiperpotassemia.","C":"Hipocalcemia e hipopotassemia.","D":"Hipercalcemia e hiponatremia.","E":"Hipocalcemia e hipernatremia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-63273","number":"63273","sourceNumber":"63273","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mauricio, 1 ano, lactente, apresenta distúrbio hidroeletrolítico classificado como\nhipernatremia hipovolêmica (desidratação grave;\nsódio sérico = 168 mEq/L). Após 24 horas de\ncorreção, o sódio sérico encontra-se em 146 mEq/L, os sinais clínicos de desidratação não mais\nexistem e reestabeleceu-se a diurese. Súbito, a criança apresenta convulsões. A provável causa do\nquadro convulsivo é?","options":{"A":"Hiperglicemia.","B":"Hipoglicemia.","C":"Meningoencefalite intercorrente.","D":"Edema cerebral.","E":"Hipocalcemia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-51004","number":"51004","sourceNumber":"51004","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Maurício, 28 anos, é trazido inconsciente ao Pronto-Socorro pelo SAMU, que o\nresgatou de um banco de praça. O\nprofissional do SAMU entregou ao médico do Pronto-Socorro\numa seringa vazia encontrada nos pertences de Maurício. Ao exame, o paciente apresenta pupilas\nmióticas puntiformes bilateralmente. Os pulmões são limpos. O paciente não apresenta sudorese,\ndiarreia ou aumento dos ruídos hidroaéreos. A frequência respiratória é de 8 movimentos\nrespiratórios por minuto. A equipe do Pronto-Socorro informa ao médico plantonista que Maurício\ntambém é médico e sofre de dependência química. O que se observará mais provavelmente na\ngasometria?","options":{"A":"acidose metabólica.","B":"alcalose metabólica.","C":"pH arterial normal.","D":"acidose respiratória.","E":"alcalose respiratória."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-48501","number":"48501","sourceNumber":"48501","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A concentração de sódio encontrada na solução comercializada com nome de ?soro\nglicofisiológico? é:","options":{"A":"40 mEq/L.","B":"75 mEq/L.","C":"150 mEq/L.","D":"200 mEq/L.","E":"500 mEq/L."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-48502","number":"48502","sourceNumber":"48502","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente com diurese de 5.000 ml/24 horas e Na plasmático = 140 mEq/L, K= 3,9\nmEq/L pode ter o seguinte diagnóstico:","options":{"A":"Diabetes insipidus.","B":"Secreção Inadequada de ADH.","C":"Insuficiência suprarrenal.","D":"Hiperidratação.","E":"Hipo-hidratação."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-48827","number":"48827","sourceNumber":"48827","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Você está atendendo a uma criança cujo distúrbio hidreletrolítico foi classificado como\nhipernatremia hipovolêmica (desidratação do 2º grau, Na+ sérico = 168 mEq/L). Com 24h de\ncorreção, o Na+ sérico encontra-se em 146 mEq/L, os sinais clínicos de desidratação não mais\nexistem e restabeleceu-se a diurese. Subitamente, a criança apresenta convulsões. É mais\nprovável que estas sejam devido, inicialmente, à:","options":{"A":"Meningoencefalite intercorrente.","B":"Hemorragia intracraniana.","C":"Hipocalcemia.","D":"Hiperglicemia.","E":"Edema cerebral."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-48483","number":"48483","sourceNumber":"48483","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente submetido à ressecção transuretral da próstata apresenta, uma hora após o\ntérmino da cirurgia, quadro de confusão mental, apatia, náuseas, vômitos, convulsões e coma.\n\nProvável causa dos sintomas:","options":{"A":"Hipernatremia.","B":"Hiperpotassemia.","C":"Hiponatremia.","D":"Hipopotassemia.","E":"Infarto agudo do miocárdio."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-48866","number":"48866","sourceNumber":"48866","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na reposição hidroeletrolítica é correto afirmar:","options":{"A":"A solução de glicose a 5% expande eminentemente o compartimento intersticial.","B":"Cerca de 1/4 da solução de cloreto de sódio a 0,9% permanece no compartimento intravascular.","C":"Uso de grandes volumes de solução fisiológica pode levar à acidose hiperclorêmica.","D":"O uso de solução cristaloide hipertônica poderá levar a aumento da pressão intracraniana.","E":"Nenhuma das alternativas é correta."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-35617","number":"35617","sourceNumber":"35617","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Serão encontrados com maior probabilidade o sinal de Chvostek e a respiração de\nKussmaul em pacientes que apresentam, respectivamente:","options":{"A":"pH de 7,12 e 7,61.","B":"bicarbonato de 38 e 24 mEq/L.","C":"pH de 7,55 e 6,95.","D":"pCO2 de 18 e 55 mmHg.","E":"bicarbonato de 12 e 38 mEq/L."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-27163","number":"27163","sourceNumber":"27163","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, AMC, 65 anos, chega ao PS com quadro comatoso. Após avaliação da\nneurologia são solicitados exames\nlaboratoriais e de imagem. Rapidamente o laboratório comunica\nque o sódio plasmático é de 110. O plantonista, então, infunde solução hipertônica em grandes\nvolumes e elevado fluxo. A complicação mais grave, dentre as opções abaixo, de uma correção\nrápida da hiponatremia deste paciente, é:","options":{"A":"Edema cerebral.","B":"Infarto agudo do miocárdio.","C":"Síndrome de desmielinização osmótica.","D":"Edema agudo de pulmão.","E":"Hipertensão maligna."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-27166","number":"27166","sourceNumber":"27166","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, LIS, 70 anos, apresenta desidratação aguda decorrente de vômitos\nincoercíveis. É solicitado exame gasométrico\npelo plantonista, observando-se distúrbio ácido-básico\ne eletrolítico. Qual das opções abaixo deve-se esperar no laudo da gasometria o seguinte\nresultado:","options":{"A":"Alcalose metabólica e hipocloremia","B":"Acidose metabólica e hiponatremia","C":"Acidose metabólica e hiperpotassemia","D":"Acidose respiratória e hipernatremia","E":"Alcalose respiratória e hipopotassemia"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-23038","number":"23038","sourceNumber":"23038","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Uma adolescente de 14 anos, do sexo feminino, procura atendimento médico,\nacompanhada de sua mãe, devido à perda de peso\nexcessiva. A mãe relata que a adolescente\npermanecia longos períodos no banheiro para induzir vômitos. A adolescente confirma a história e\nrefere uso de laxante. Ciclo menstrual irregular com amenorreia há quatro meses. Exame físico:\npeso: 35 Kg (< p3), Estatura: 168 cm (p 90), IMC: 12,41 Kg/m2 (<p3), PA 100/70 mmHg, FC: 70\nbpm. Considerando a provável hipótese diagnóstica, o principal sinal de gravidade é a:","options":{"A":"hiponatremia.","B":"alcalose hiperclorêmica.","C":"acidose hipoclorêmica.","D":"hipopotassemia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-342408","number":"342408","sourceNumber":"342408","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São fármacos que podem causar hipopotassemia, EXCETO:","options":{"A":"Anfotericina B.","B":"Carbenicilina.","C":"Inibidores da Enzima Conversora de Angiotensina (IECA).","D":"Teofilina.","E":"Hidroclorotiazida."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-263716","number":"263716","sourceNumber":"263716","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Das opções a seguir, qual a patologia que NÃO é causa de acidose metabólica com\nânion-gap aumentado?","options":{"A":"Acidose láctica.","B":"Cetoacidose diabética.","C":"Acidose tubular distal.","D":"Uremia.","E":"Intoxicação por metanol."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-250230","number":"250230","sourceNumber":"250230","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 63 anos, apresenta diabetes mellitus tipo 2 há 13 anos, dislipidemia e\ndoença arterial coronariana, vai à consulta\nde rotina com os seguintes exames: glicemia em jejum:\n190 mg/dl, glicemia pós-prandial: 196 mg/dl, hemoglobina glicada: 9,8%, hemoglobina: 11 g/dl,\nTaxa de Filtração Glomerular (TFG): 40 ml/min e albuminúria: 500 mg/g. Após otimizar o tratamento\ndo diabetes, o médico comenta que nos próximos exames irá incluir dosagens de fósforo, cálcio e\nalbumina. Sobre o caso clínico e a Doença Renal Crônica (DRC), assinale a alternativa CORRETA:","options":{"A":"É comum neste estágio da DRC a ocorrência de hiperparatiroidismo terciário.","B":"Os distúrbios hidroeletrolíticos esperados no caso clínico são hipercalcemia e hiperfosfatemia.","C":"Diabetes e doença renal policística são as principais causas de DRC no mundo.","D":"Com base na TFG e albuminúria, a paciente apresenta doença renal crônica em estágio G3BA3."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-250231","number":"250231","sourceNumber":"250231","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 23 anos, dá entrada na urgência devido à dispnéia, edema de membros\ninferiores e artrite em grandes articulações.\nApós avaliação, o médico constatou presença de\nderrame pleural bilateral, proteinúria em EAS e leucopenia; diante de sua hipótese diagnóstica,\nencaminhou a paciente ao especialista, que prescreveu 60 mg de prednisona ao dia. Após 15 dias\ne melhora do quadro, a medicação foi suspensa por conta própria. A paciente retorna à urgência\ndevido à tontura, náuseas e vômitos, Glasgow 14, apresentando os seguintes exames: K: 5,6\nmEq/L; Na: 127 mEq/L. Assinale a alternativa CORRETA?","options":{"A":"A síndrome da secreção inapropriada do hormônio antidiurético é a causa mais comum de\nhiponatremia hipervolêmica.","B":"Caso o anti-DNA e o anti-SM da paciente sejam negativos, o diagnóstico de lúpus eritematoso\nsistêmico pode ser excluído.","C":"Insuficiência adrenal, hidroclorotiazida e hipotireoidismo são causas de hiponatremia.","D":"A paciente do caso necessita realizar hemodiálise com urgência."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-250258","number":"250258","sourceNumber":"250258","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança com 5 anos, com diagnóstico de tumor de hipófise, realiza neurocirurgia para\nressecção tumoral, apresenta no pós-operatório taquicardia, ressecamento das mucosas,\nhipotensão e aumento do volume urinário. Exames complementares evidenciam sódio sérico de\n130mEq/L e natriurese. Essa criança apresenta como hipótese diagnóstica:","options":{"A":"Diabetes Insipidus.","B":"Síndrome inapropriada do hormônio antidiurético.","C":"Síndrome cerebral perdedora de sal.","D":"Hiponatremia euvolêmica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-216430","number":"216430","sourceNumber":"216430","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Comparando os contextos clínicos a seguir, em qual deles o início imediato da infusão\nde solução salina hipertônica a 3% para\ncorreção da hiponatremia seria a conduta com,\nPROVAVELMENTE, o melhor benefício?","options":{"A":"Natremia em 125 mEq/L (exame de cinco dias atrás mostrava sódio sérico de 131 mEq/L).\n\nHistória de diarreia e vômitos frequentes nos últimos 7 dias. Ureia e creatinina atuais de 95 mg/dl\ne\n1,6 mg/dl, respectivamente. Sem edemas e apresentando hipotensão ortostática. No momento,\nGlasgow 13.","B":"Natremia de 125 mEq/L (exame de um mês atrás mostrava sódio sérico de 127 mEq/L). História\nde sonolência progressiva há várias semanas. No\nmomento, Glasgow 10. Ureia atual de 20 mg/dl,\nedema facial. Hipotérmico. Bradicárdico. TSH 70 mUI/L.","C":"Sódio sérico de 119 mEq/L (exame de um mês antes mostrava natremia em 120 mEq/L). DRC\nestágio V. Anasarca. No momento, Glasgow 15.","D":"Natremia em 122 mEq/L (exame do dia anterior mostrava sódio sérico de 135 mEq/L).\n\nDiagnóstico recente de neoplasia de pulmão. Ureia atual de 20 mg/dl. Sem edemas. No momento,\nGlasgow 9."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-176273","number":"176273","sourceNumber":"176273","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança com 2 anos de idade, em pós-operatório imediato de cirurgia para correção de\nComunicação Interventricular, tendo sido submetida a 120 minutos de circulação extracorpórea,\napresenta os seguintes resultados de exames laboratoriais: K: 2,0mmol/L; Na: 134mmol/L; HCO3-:\n13mmol/L; Ca Iônico: 0,8mmol/L. Qual a correção MAIS URGENTE nesse caso?","options":{"A":"Ca++","B":"K+","C":"HCO3-","D":"Na+","E":"Tanto faz, as correções podem acontecer ao mesmo tempo sem risco adicional para o paciente."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-155253","number":"155253","sourceNumber":"155253","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente renal crônico estágio 4, não dialítico apresenta Hb de 9,0 g/dl. Entre as\nopções, a causa MENOS PROVÁVEL da anemia é:","options":{"A":"Deficiência de ferro.","B":"Deficiência de ácido fólico.","C":"Hemólise.","D":"Hiperparatireoidismo.","E":"Inflamação."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-155272","number":"155272","sourceNumber":"155272","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente, 36 anos de idade, hipertenso, com cefaleia de início recente e tremores leves\nnas extremidades. Exame físico mostra paciente corado, hidratado, vígil e orientado, com pupilas\nisocóricas e fotorreagentes, além de força preservada nos quatro membros. PA = 130 x 80 mmHg;\nFC = 72 bpm; ausência de hipotensão postural. MMII sem edemas. A avaliação laboratorial mostra:\nsódio sérico = 126 mEq/L; osmolaridade urinária < 100 mOsm/L; sódio urinário = 16 mEq/L;\ncreatinina sérica = 1,2 mg/dl; creatinina urinária = 12,6 mg/dl. A partir desses dados, qual a causa\nMAIS PROVÁVEL de hiponatremia para esse paciente?","options":{"A":"Polidipsia primária.","B":"Diurético tiazídico.","C":"Insuficiência renal aguda parenquimatosa.","D":"Síndrome de secreção inapropriada do hormônio antidiurético.","E":"Desidratação por vômitos recentes."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-155438","number":"155438","sourceNumber":"155438","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que NÃO APRESENTA uma causa de acidose metabólica\nhiperclorêmica:","options":{"A":"Acidose láctica.","B":"Acidose tubular renal.","C":"Insuficiência renal (fase inicial).","D":"Doença diarreica.","E":"Drenagem de secreções bilares e pancreáticas."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-139244","number":"139244","sourceNumber":"139244","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente com 6 anos de idade e diagnóstico de craniofaringioma. Nas primeiras horas\napós admissão na UTI, apresenta diurese de\n220mL/h necessitando de reposição volêmica. O\ndiagnóstico MAIS PROVÁVEL e a terapêutica adequada, respectivamente, são:","options":{"A":"Síndrome cerebral perdedora de sal, reposição de sódio e cristaloides","B":"Síndrome de secreção inapropriada de ADH; desmopressina","C":"Diabetes insipidus central, desmopressina","D":"Diabetes insipidus central; restrição hídrica e aumento da oferta de sódio","E":"Síndrome cerebral perdedora de sal, desmopressina"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-139235","number":"139235","sourceNumber":"139235","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um pediatra foi chamado à enfermaria para avaliar os resultados laboratoriais de uma\ncriança de 5 anos com cetoacidose diabética. Os resultados foram: Na=128 mEq/L (VN = 135 A\n145 mEq/L); glicemia=350 mg/dL (VN=60 a 100 mg/dL); uréia=52 mg/dL (VN= 7 a 18 mg/dL). É\nCORRETO afirmar que:","options":{"A":"É provável que esse valor de sódio esteja diminuído.","B":"A hiponatremia nesse caso é hipertônica. A hipertonicidade é uma caractérística dos estados\nhiponatrêmicos.","C":"Se for calculada a osmolaridade sérica, nesse caso, ela estará diminuída.","D":"Caso haja hipertrigliceridemia, o nível de sódio sérico estará mais baixo que esse valor, pois o\naumento de triglicerídeos leva à hiponatremia verdadeira.","E":"A principal causa de hiponatremia com osmolaridade sérica normal (280 a 300 mOsm/L), em\npacientes internados, é a gastroenterite aguda."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-105676","number":"105676","sourceNumber":"105676","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Analisando a seguinte gasometria arterial de um paciente em ventilação espontânea\nem ar ambiente, qual a causa menos provável da\n(s) alteração (ões) apresentada (s)? pH 7.47.\nPaCO2 43 mmHg. PaO2 90 mmHg. HCO3- 31 mEq/L.","options":{"A":"Uso de sonda nasogástrica em sifonagem com resíduo de 800 ml em 24h.","B":"Uso de diurético de alça sem indução de hipovolemia.","C":"Contração volumétrica após sudorese excessiva.","D":"Insuficiência adrenal primária crônica.","E":"Transfusão maciça."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-105716","number":"105716","sourceNumber":"105716","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente masculino, 57 anos, trazido ao pronto-socorro por rebaixamento do nível de\nconsciência. Familiares informam que há alguns dias ele tem apresentado náuseas, constipação e\nfraqueza muscular. Nas últimas 48h, evoluiu com confusão, estupor e coma. Referem ainda que ele\nperdeu muito peso nos últimos meses, teve episódio de hemoptise há 20 dias e é tabagista 30\nmaços/ano. Ao exame físico, o paciente está com Glasgow 6. Exames complementares mostram:\nECG com intervalo QT reduzido e uma grave alteração de um eletrólito. Após suporte de vida\ninicial, qual o melhor tratamento, para a alteração aguda mais provável deste paciente?","options":{"A":"Reposição venosa de potássio, preferencialmente não ultrapassando a velocidade de 20 mEq/h\ne a concentração de 40 mEq/L em veia\nperiférica.","B":"Hidratação vigorosa com salina isotônica 0,9%, podendo acrescentar furosemida após repleção\nvolêmica e diurese abundante.","C":"Infusão de solução salina hipertônica 3%, podendo acrescentar furosemida simultaneamente.","D":"Infusão de soro ao meio 0,45%, podendo acrescentar água potável por SNE.","E":"Reposição de gluconato de cálcio."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-105643","number":"105643","sourceNumber":"105643","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher de 50 kg, com cefaleia e confusão mental, é trazida ao PS por familiares. Na\navaliação inicial, chama atenção um sódio sérico de 119 mEq/L. Há 5 dias, tinha recebido exames\nde rotina, com natremia normal. Calculando-se a reposição de sódio pela fórmula convencional, e\nrespeitando o limite máximo recomendado de subida do sódio para prevenção de síndrome de\ndesmielinização osmótica, a quantidade máxima de solução salina a 3% a ser ofertada para esta\npaciente nas próximas 24h, é:","options":{"A":"686 ml.","B":"1.254 ml.","C":"392 ml.","D":"490 ml.","E":"196 ml."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-80891","number":"80891","sourceNumber":"80891","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente 42 anos, hipertensa e diabética, faz uso de hidroclorotiazida, captopril e\nmetformina. Admitida com quadro de vômitos,\ndiarreia com muco e febre há 4 dias. Ao exame\nfísico, apresenta regular estado geral, desidratada, PA = 100 x 60 mmHg, FC = 100 bpm, FR = 28\nipm; abdome doloroso sem sinais de irritação peritoneal. Exames laboratoriais: Creatinina = 2,3\nmg/dl; Ureia = 132 mmol/ml; Potássio = 2,6 mmol/ml; Sódio = 130 mmol/ml; pH = 7,49; Bicarbonato\n(HCO3) = 26 mEq/L; PaCO2 = 46 mmHg, PO2 = 70 mmHg e SatO2 = 91%. As possíveis causas da\nhipocalemia são:","options":{"A":"Diarreia, diurético tiazídico e alcalose metabólica.","B":"Hipoxemia e insuficiência renal.","C":"Metformina, hiponatremia e perda de suco gástrico causado pelos vômitos.","D":"Hipoxemia, diurético tiazídico e captopril.","E":"Diarreia, metformina e uremia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-84890","number":"84890","sourceNumber":"84890","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Dentre as causas de doença renal crônica classe V com tamanho renal normal ou\naumentado ao exame de ultrassonografia temos, EXCETO:","options":{"A":"Amiloidose.","B":"Nefropatia hipertensiva.","C":"Nefropatia por HIV.","D":"Diabetes mellitus.","E":"Anemia falciforme."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-80949","number":"80949","sourceNumber":"80949","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre distúrbios acidobásicos, é INCORRETO afirmar que:","options":{"A":"As acidoses metabólicas com Ânion-Gap (AG) normal têm entre as suas principais causas:\ndiarreia, acidose tubular renal tipo I, II e IV, intoxicação por metanol e paraldeído.","B":"Nosso organismo dispõe de múltiplas linhas de defesa contra sobrecargas ácidas, como o\ntamponamento extracelular pelo bicarbonato, o tamponamento respiratório.","C":"Pela excreção aumentada de CO2 e o tamponamento ósseo e intracelular, assim como o\naumento na excreção renal de hidrogênio.","D":"A acidose metabólica é um distúrbio do equilíbrio acidobásico muito frequente em pacientes\ngravemente enfermos internados em unidades de terapia intensiva, sendo que o principal tipo de\nacidose metabólica encontrada nestes pacientes é a acidose lática secundária ao choque\ncirculatório.","E":"Riscos do tratamento com bicarbonato: hipernatremia, hiperosmolaridade, sobrecarga de\nvolume, hipercapnia e acidose intracelular, maior afinidade da Hb pelo O2, estímulo a enzimas\nglicolíticas, queda no cálcio ionizado e alcalose de rebote."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-80855","number":"80855","sourceNumber":"80855","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa que apresenta o diagnóstico compatível com o seguinte quadro:\nhiponatremia com sódio corporal normal, hematócrito normal, sódio urinário > 20 mEq/L e\nosmolaridade urinária hipertônica.","options":{"A":"Síndrome da secreção inapropriada de hormônio antidiurético.","B":"Síndrome perdedora de sal.","C":"Cirrose.","D":"Insuficiência cardíaca.","E":"Tubulopatia."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-62571","number":"62571","sourceNumber":"62571","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paralisia flácida, hiporreflexia, hipercapnia, tetania e rabdomiólise podem ocorrer em\ncasos de:","options":{"A":"Hipercalemia;","B":"Hipercalcemia;","C":"Hipocalcemia;","D":"Hipofosfatemia;","E":"Hipocalemia."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-35778","number":"35778","sourceNumber":"35778","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Desidratação caracterizada por sede intensa, mucosas muito secas, oligúria acentuada,\nfebre, crise convulsiva, opistótono,\nhiper-reflexia:","options":{"A":"Hipotônica.","B":"Hipertônica.","C":"Isonatônica.","D":"Hiponatrêmica.","E":"Isonatrêmica."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-11428","number":"11428","sourceNumber":"11428","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"O potássio é o principal cátion extracelular e o sódio o principal intracelular; para manutenção\ndessa distribuição, despende-se energia.","B":"A água se difunde livremente entre os compartimentos intra e extracelular de acordo com os\ngradientes de concentração de soluto.","C":"A concentração de soluto é a mesma nos vários compartimentos corporais, e a quantidade de\nágua depende de quantidade de soluto presente.","D":"Líquido isotônico não causa alteração do volume celular, se administrado por via intravenosa,\npermanecendo no compartimento extracelular.","E":"São isotônicos, solução salina (NaCl 0,9%), Ringer lactado e plasma."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-342406","number":"342406","sourceNumber":"342406","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Para uma paciente de 40 anos, diabética e hipertensa de longa data, que apresentaem\nconsultório um resultado de Creatinina de 2 mg/dl, sabendo-se que a mesma pesa72 kg, qual o\nclearance de creatinina estimado?","options":{"A":"42,50ml/min","B":"50 ml/min","C":"40 ml/min","D":"52,50 ml/min","E":"51 ml/min."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-308647","number":"308647","sourceNumber":"308647","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"São causas de acidose metabólica com ânion gap aumentado, EXCETO:","options":{"A":"cetoacidose diabética.","B":"acidose tubular renal.","C":"acidose láctica.","D":"intoxicação por salicilatos.","E":"intoxicação por metanol."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-278964","number":"278964","sourceNumber":"278964","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança de 4 anos de idade, previamente hígida, sem queixas recentes e deixada\ndesassistida em domicílio, é encontrada na garagem de sua casa desacordada e levada ao\npronto-socorro sem informações claras do ocorrido. A gasometria revelou pH=7,1; pCO2=12\nmmHg; HCO?=8mEq/L; Cl=104mEq/L; Na=140mEq/L. Sobre os diagnósticos etiológico e\ngasométrico mais adequados para o paciente, assinale a alternativa correta:","options":{"A":"Cetoacidose por jejum prolongado: acidose metabólica com ânion gap aumentado.","B":"Insuficiência respiratória aguda com acidose respiratória.","C":"Choque séptico com acidose metabólica hiperclorêmica.","D":"Intoxicação exógena: acidose metabólica e alcalose respiratória.","E":"Doença diarreica aguda: acidose mista."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-244659","number":"244659","sourceNumber":"244659","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual das medidas é menos eficaz para reduzir os níveis de potássio diante de um\npaciente com hipocalemia?","options":{"A":"Gluconato de cálcio","B":"Furosemida","C":"Salbutamol","D":"Solução de Insulina com Glicose (polarizante)","E":"Poliestirenossulfonato de cálcio (sorcal)"},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-203187","number":"203187","sourceNumber":"203187","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No contexto cirúrgico, são responsáveis pela hipocalemia as seguintes condições, com\nEXCEÇÃO de:","options":{"A":"Administração excessiva de diuréticos.","B":"Perdas gastrointestinais.","C":"Acidose metabólica a sepse abdominal.","D":"Hepatopatias crônicas.","E":"Alcalose metabólica prolongada."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-175022","number":"175022","sourceNumber":"175022","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Entre as medidas usadas no tratamento da hipercalemia, assinale a que NÃO tem\ncomo objetivo a troca de compartimento do potássio e nem a estabilização de membrana.","options":{"A":"Gluconato de cálcio a 10% -10 a 20mL + SF0,9%100mL EV","B":"Resina de troca","C":"Solução polarizante - insulina regular 10UI + glicose a 50% 100mL EV","D":"Beta 2 adrenérgico","E":"Bicarbonato de sódio a 8,4% 1meq/kg"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-177465","number":"177465","sourceNumber":"177465","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 32 anos, chegando hoje de viagem da cordilheira dos Andes, onde esteve\nacampado durante os últimos 15 dias, chega ao\npronto atendimento trazido por equipe médica do\naeroporto, relatando piora do estado geral, vômitos de repetição, parestesias intensas e tonteira.\nOs sintomas iniciaram-se há 72h. Refere ter feito uso recorrente de AAS para cefaleia nos dias em\nque esteve nas montanhas. Por recomendação de amigo montanhista, também fez uso de\nacetazolamida da segunda metade do período de acampamento até o embarque na aeronave para\no Brasil. Ao exame, apresenta-se bastante desidratado, lábios ressequidos, PA 100x50mmHg, com\nFC de 106 bpm. Bioquímica sérica mostra K+ de 3,4mEq/L; Na+ de 131 mEq/L; CI em 112mEq/L.\nHemograma com 12900 leucócitos. Gasometria venosa com pH 7,3; HCO3 18mEq/L; pCO2\n34mmHg. A acidose do paciente em questão mais provavelmente se deve a:","options":{"A":"Cetoacidose","B":"Vômitos de repetição","C":"Inibidor de anidrase carbônica","D":"Sepse","E":"Ácido acetilsalicílico"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-177475","number":"177475","sourceNumber":"177475","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Observe o ECG a seguir: Os achados nesse ECG podem estar presentes em pacientes\ncom qual das situações clínicas abaixo?","options":{"A":"Infusão rápida de insulina IV.","B":"Síndrome de Gitelman.","C":"Nefropatia diabética.","D":"Doença de Cushing.","E":"Síndrome de Fanconi."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-160410","number":"160410","sourceNumber":"160410","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um senhor de 70 anos, DPOC, apresenta febre há 3 dias, acompanhado de tosse\nprodutiva e dispneia. Há um mês fez uso de\namoxacilina / clavulanato por sinusite. No exame físico,\napresenta PA 100 x 60 mmHg, FC 110 bpm e FR 30 irpm. Há estertores na base pulmonar\nesquerda. É coletada a seguinte gasometria arterial (Conforme imagem do caderno de questões): O\ndistúrbio ácido-básico presente na gasometria arterial é:","options":{"A":"Acidose metabólica.","B":"Alcalose metabólica.","C":"Alcalose respiratória.","D":"Acidose respiratória.","E":"Hipoxemia."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-154435","number":"154435","sourceNumber":"154435","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Entre as causas de acidose metabólica abaixo, cursa com ânion-gap normal:","options":{"A":"Acidose láctica.","B":"Intoxicação por metanol.","C":"Acidose tubular renal.","D":"Intoxicação por salicilato.","E":"Cetoacidose diabética."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-103893","number":"103893","sourceNumber":"103893","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Hipercalemia aguda está associada a qual das seguintes alterações\neletrocardiográficas?","options":{"A":"Prolongamento do segmento ST.","B":"Diminuição do intervalo PR.","C":"Alargamento do QRS.","D":"Onda U proeminente.","E":"Achatamento da onda T."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-89236","number":"89236","sourceNumber":"89236","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Constitui causa de acidose metabólica com Anion gap normal:","options":{"A":"Acidose lática","B":"Cetoacidose diabética","C":"Uremia","D":"Intoxicação por salicilato","E":"Diarreia"},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-87490","number":"87490","sourceNumber":"87490","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente do sexo feminino, 64 anos, hipertensa e coronariopata, abriu quadro de dor\nabdominal moderada há 3 dias. Hoje pela manhã notou pronunciada piora da dor abdominal, iniciou\nsubitamente uma dor descrita como insuportável em primeiro pododáctilo esquerdo e começou a\napresentar vômitos recorrentes, cefaléia e confusão mental. Acompanhante comenta ainda não ter\nobservado exteriorização de diurese pela paciente hoje. Informa que há 11 dias foi submetida a\numa cineangiocoronariografia (caracterização femoral esquerda), com colocação de stent\n\nnão-farmacológico em 1/3 proximal da A. descendente anterior, e vinha evoluindo sem precordialgia\ndesde então. Faz uso de AAS 100mg/d,\nClopidogrel 75mg/d (este último recém-iniciado após o\nprocedimento descrito), Losartana 100mg/d, Atenolol 50mg/d e Atorvastatina 80mg/d. Exame físico\nrevela uma paciente corada, com edema bipalpebral e de MMII, acianótica, com FR de 24irpm, sem\nesforço. A PA é de 170 x100mmHg, FC de 68 bpm. Observam-se ainda pulmões limpos, e ausculta\ncardíaca com B4, sem sopros. Pulsos pediosos palpáveis. Perfusão capilar periférica lentificada em\nprimeiro pododáctilo esquerdo. Laboratório de entrada: Hb: 13,6; 13.800 leucócitos, sendo 74%\nPMN e 10% de eosinófilos, sem desvio à esquerda; 162.000 plaquetas; Na: 135meq/L; K: 6,6meq/L\nCreatinina: 3,1MG/dl; U: 96mg/dl; Gli:120mg/dl; amilase elevada. Troponina I normal; CK total\n(300U/L); CK-MB normal; EAS com cilindros granulosos e piúria. ECG: sobrecarga volumétrica do\nVE, apenas. RX tórax: hilos pulmonares ingurgitados, área cardíaca normal. Pergunta-se: Referente\nà hipercalemia, no caso em questão, a primeira medida a ser tomada é:","options":{"A":"Glicoinsulinoterapia IV;","B":"Gluconato de cálcio IV;","C":"Furosemida IV;","D":"Hemodiálise;","E":"Resina de troca VO."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-87535","number":"87535","sourceNumber":"87535","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação aos distúrbios eletrolíticos. É correto afirmar?","options":{"A":"Secreção inapropriada de HAD e hipotireoidismo são causas de hiponatremia com sódio\ncorpóreo total normal;","B":"Hiponatremia é definida como concentração sérica de sódio menor que 135 mEq/l;","C":"A hipercalemia com níveis séricos acima de 8 mEq/l deve ser tratada apenas com a suspensão\nde toda administração de potássio;","D":"Em crianças, o hipoparatireoidismo primário é uma das principais causas de hipercalcemia;","E":"A hipermagnesemia ocorre comumente em paciente com função renal normal."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-87549","number":"87549","sourceNumber":"87549","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Lactente de 6 meses de idade, nascido pré-termo e evoluindo com broncodisplasia\npulmonar é admitido no pronto-socorro\npediátrico com quadro de pneumonia. Não é dependente de\noxigênio. Faz uso prolongado de hidroclorotiazida e espironolactona. Na avaliação laboratorial,\napresenta seguinte gasometria arterial: pH 7,34; PO2 54 mmHg; PCO2 85 mmHg; (HCO3) 44\nmEq/L; Base excess 14; SATO2 90%. Qual o distúrbio ácido básico?","options":{"A":"Acidose respiratória crônica com alcalose metabólica;","B":"Acidose respiratória aguda descompensada;","C":"Acidose respiratória crônica compensada;","D":"Alcalose metabólica descompensada;","E":"Acidose metabólica aguda com alcalose respiratória."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-65565","number":"65565","sourceNumber":"65565","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na resposta endocrinometabólica ao trauma cirúrgico, o principal estímulo à secreção\ndo ADH é:","options":{"A":"Analgesia inadequada;","B":"Hemorragia;","C":"Osmolaridade plasmática;","D":"Redução da aldosterona;","E":"Aumento da angiotensina."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-65566","number":"65566","sourceNumber":"65566","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual o valor esperado de PaCO2 num paciente com ACIDOSE METABÓLICA que\napresenta HCO3 de 10 mEq/L?","options":{"A":"Entre 15 - 20;","B":"Entre 20 - 25;","C":"Entre 25 - 30;","D":"Maior que 30;","E":"Menor que 15."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-52223","number":"52223","sourceNumber":"52223","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Qual tratamento para correção do distúrbio acidobásico em um paciente que apresenta\nfístula digestiva de alto débito decorrente de\numa anastomose pancreatojejunal?","options":{"A":"Solução isotônica de cloreto de sódio.","B":"Solução de bicarbonato.","C":"Solução hipertônica de glicose a 50%.","D":"Solução hipertônica de cloreto de sódio.","E":"Reposição vigorosa de cloreto de potássio."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-330837","number":"330837","sourceNumber":"330837","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A classificação da Injúria Renal Aguda (IRA), de acordo com o \"Kidney Disease\nImproving Global Outcomes\" (KDIGO), é\nimportante ferramenta para prognóstico e gerenciamento\ndo manejo da doença. Assinale a alternativa que apresenta os parâmetros atualmente utilizados, no\nestadiamento da IRA.","options":{"A":"Variação da creatinina sérica e taxa de filtração glomerular.","B":"Taxa de filtração glomerular e albuminúria.","C":"Variação do débito urinário e albuminúria.","D":"Variação do débito urinário e variação da creatinina sérica."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-288146","number":"288146","sourceNumber":"288146","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação à insuficiência renal crônica, assinale a afirmativa INCORRETA:","options":{"A":"Anemia e trombocitopenia podem ocorrer na uremia.","B":"Expansão do volume circulante, hiponatremia e hipercalemia são distúrbios hidroeletrolíticos na\nuremia.","C":"Hipertensão arterial sistêmica, insuficiência cardíaca congestiva ou edema pulmonar são\ndistúrbios cardiovasculares e pulmonares na uremia.","D":"Acidose metabólica não é um distúrbio comum na doença renal crônica avançada."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-362885","number":"362885","sourceNumber":"362885","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher, 65 anos, no 5º pós operatório de revascularização do miocárdio apresenta\nníveis séricos de potássio de 2,6 mmol/L (VR: 3,5\na 5,1 mmol/L). Como a paciente está\nassintomática, foi realizado recoleta de material confirmando tal resultado. Qual a conduta para o\ncaso?","options":{"A":"Infusão de glicose (GH 50% 50ml) e insulina (R 10U);","B":"Uso oral de resina de troca (Sorcal) 15g 3x ao dia;","C":"Infusão de KCI EV a uma taxa de 10 MEq/h;","D":"Suplementação oral com KCL a uma taxa de 40mEq/dia."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-362851","number":"362851","sourceNumber":"362851","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 13 anos vítima de soterramento dá entrada na emergência pediátrica\nconsciente, com múltiplas escoriações e fratura\nexposta de perna direita. Além dos cuidados iniciais\nde atendimento ao paciente vítima de trauma, deve ser investigado o seguinte distúrbio\nhidroeletrolítico:","options":{"A":"hiponatremia","B":"hipercalemia","C":"hipomagnesemia","D":"hiperfosfatemia"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-346621","number":"346621","sourceNumber":"346621","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 22 anos, do sexo feminino, portadora de diabetes mellitus do tipo 1, deu\nentrada em serviço de pronto atendimento com quadro de cetoacidose diabética devido à\ndescontinuação do uso da insulina e transgressão dietética. Exames laboratoriais evidenciaram\nelevação significativa dos níveis séricos de glicose e o pH do sangue arterial era 7,27. Qual dos\nachados relacionados abaixo se espera encontrar no traçado eletrocardiográfico dessa paciente?","options":{"A":"Aumento da amplitude da onda P","B":"Ondas T apiculadas","C":"Ondas U","D":"Redução da duração do intervalo PR"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-313415","number":"313415","sourceNumber":"313415","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 50 anos, hipertenso e diabético, em uso prévio de clortalidona, enalapril, ácido\nacetil salicílico e metformina, admitido com quadro de vômitos, diarreia e febre há 3 dias. Ao exame\napresenta-se desidratado, hipotenso, FC de 120 bpm, FR 30 irpm e abdome doloroso. Exames de\nurgência com creatinina de 3,0 mg/dL, ureia 150 mg/dL, sódio 128 mmol/L, potássio 2,6 mmol/L, pH\n7,55, HCO3 32 mEq/L, PaCO 2 35 mmHg, PO 2 60 mmHg, SatO 2 90 em ar ambiente. Diante\ndesse caso, quais as possíveis causas da hipocalemia?","options":{"A":"Uso de tiazídico, diarreia, desidratação e vômitos levando a alcalose metabólica;","B":"Lesão renal aguda, diarréia, uso de metformina e enalapril;","C":"Uso de inibidor de enzima conversora de angiotensina (ieca), alcalose metabólica e diarréia;","D":"Uremia, alcalose respiratória, uso de tiazídico e de metformina."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-313422","number":"313422","sourceNumber":"313422","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na SIADH, é correto afirmar:","options":{"A":"Constitui-se de hipernatremia e euvolemia, geralmente com poliúria associada;","B":"É usual na síndrome: hiponatremia, hipouricemia, sódio urinário alto e osmolaridade urinária\nalta;","C":"A hipovolemia caracteriza a SIADH nos pacientes com HSA, diferenciando-a da Síndrome\nPerdedora de Sal;","D":"Deve-se evitar o uso de Furosemida em seu tratamento, pelo efeito natriurético daquele\ndiurético."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-283949","number":"283949","sourceNumber":"283949","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Mulher, 33 anos, vítima de trauma abdominal fechado, apresentando choque\nhemorrágico que foi levada para laparotomia\nexploratória de urgência sendo necessário reposição\nde 10 concentrados de hemácias durante o peri- operatório. Devido ao uso de citrato como\nanticoagulante do concentrado de hemácias, qual distúrbio eletrolítico grave e potencialmente fatal\npodemos esperar nessa paciente?","options":{"A":"Hipocalcemia","B":"Hipernatremia","C":"Hipofosfatemia","D":"Hipermagnesemia"},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-258935","number":"258935","sourceNumber":"258935","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Lactente, 1 ano e 4 meses, portador de doença pulmonar crônica, dependente de\noxigênio, deu entrada no pronto atendimento do Hospital Universitário com quadro dispneico, sem\nfebre. O resultado da gasometria arterial em FiO2 de 30% sob cateter nasal foi: pH: 7,20; pO2: 75\nmmHg; pCO2: 70 mmHg; bicarbonato: 26 mEq/L. Qual o distúrbio do equilíbrio ácido-básico\napresentado?","options":{"A":"Alcalose metabólica descompensada.","B":"Acidose respiratória com acidose metabólica.","C":"Acidose respiratória com alcalose metabólica.","D":"Alcalose metabólica compensada."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-283984","number":"283984","sourceNumber":"283984","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 31 anos, vem para consulta com nefrologista apresentando proteinúria\nsubnefrótica e clearance de creatinina de 50\nmL/min/1,73 m2. Relata que apresenta desde a\nadolescência ?crises? de dor insuportáveis em extremidades precipitadas por estresse, mudanças\nclimáticas e esforço físico. Ao exame físico apresenta angioqueratomas em região inguinal. Refere\nainda que seu avô materno fez hemodiálise desde os 38 anos e faleceu aos 45 por acidente\nvascular encefálico. Diante do diagnóstico mais provável, qual melhor abordagem terapêutica?","options":{"A":"Transplante de medula óssea","B":"Terapia de reposição enzimática","C":"Transplante renal com doador não relacionado","D":"Melfalan endovenoso e corticoterapia em pulso"},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-214604","number":"214604","sourceNumber":"214604","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente de 58 anos, masculino, com diagnóstico de cirrose hepática de etiologia\nalcoólica há dois anos. Em uso de furosemida\n80 mg vo/dia e espironolactona 100 mg vo/dia. Tal\npaciente procura PS apresentando piora do estado geral e redução do volume urinário há quatro\ndias. Exames de entrada mostram: TGO = 48 UI/L; TGP = 40 UI/L; bilirrubina total = 1,8 (BD = 1,2;\nBI = 0,6); INR = 1,8; albumina = 2,1 g/dl; ureia = 75 mg/dl; creatinina = 2,5 mg/dl; Na = 148 mEq/L\ne\nK = 5,5 mEq/L. Hemograma sem anormalidades relevantes. Considerando o quadro de injúria renal\nobservado, assinale a afirmativa CORRETA.","options":{"A":"Trata-se de síndrome hepatorrenal, devendo-se iniciar restrição hídrica, octreotide e albumina IV\nde imediato.","B":"A primeira possibilidade a ser considerada é de azotemia pré-renal. Suspensão de diuréticos e\nhidratação venosa devem ser as primeiras medidas.","C":"Biópsia renal é a mandatória para se estabelecer corretamente a etiologia.","D":"Dosagem do sódio urinário é essencial no caso, tendo alta acurácia nesse contexto clínico."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-214608","number":"214608","sourceNumber":"214608","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem de 54 anos, portador de hipertensão arterial sistêmica, veio encaminhado à\nnefrologia por creatinina de 3,2 mg/dl. Em análise do Exame Anormal de Sedimentoscopia (EAS),\nachados decorrentes da dilatação dos túbulos coletores em pacientes com doença renal crônica\nsão os cilindros:","options":{"A":"Hemáticos.","B":"Graxos.","C":"Céreos.","D":"Leucocitários."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-221385","number":"221385","sourceNumber":"221385","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Das alternativas citadas abaixo, qual NÃO representa uma indicação formal de diálise?","options":{"A":"Azotemia grave.","B":"Hipercalemia refratária.","C":"Hiponatremia grave.","D":"Hipervolemia refratária."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-214557","number":"214557","sourceNumber":"214557","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança de 5 anos de idade dá entrada no PS com quadro de dispneia e agitação. No\nexame físico, apresenta face angustiada,\nsudoreica, cianótica; temperatura = 37,9°C; FR = 45 irpm;\nFC = 144 bpm; extremidades frias; com acentuadas tiragens intercostais; diafragmática e retração\nda fúrcula esternal. Ausculta pulmonar com murmúrio vesicular diminuído, sem sibilos, SPO? =\n88%. A gasometria em ar ambiente apresentou os seguintes resultados: pH = 7,30; PaO? = 58\nmmHg; PCO? = 55 mmHg; bicarbonato = 18 mEq/L. Em relação ao quadro descrito, marque a\nafirmativa CORRETA.","options":{"A":"Trata-se de acidose respiratória.","B":"Deve-se administrar oxigênio por cateter nasal, fluidos endovenosos e bicarbonato\nimediatamente.","C":"Estão indicados intubação endotraqueal para ventilação mecânica invasiva, broncodilatadores e\nantibióticos como primeiras condutas de emergência.","D":"Trata-se de acidose mista."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-181570","number":"181570","sourceNumber":"181570","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"L.N.S., 72 anos, trazido por familiares ao Pronto Atendimento com queixa de anorexia,\nemagrecimento e tosse há 4 meses. Tabagista há 50 anos. Ao exame físico: desorientado,\nhipocorado 1+/4+, dispneico, PA 110 × 70 mmHg, FC 104bpm, FR 28 irpm. À ausculta cardíaca:\nritmo cardíaco regular e sopro sistólico 1+/6+, pancardíaco, e nos pulmões crepitações em\nhemitórax direito. Exames complementares: Hb: 11,5 g/dL; Ht 33%; Leucócitos: 11.800; plaquetas\n335.000/mm3; VHS 80 mm; glicemia 98 mg/dL; creatinina 0,8 mg/dL; ureia 23 mg/dL; sódio 112\nmEq/L; potássio 3,9 mEq/L; cloro 88 meq/L; Bicarbonato 24 mEq/L; ácido úrico 1,4 mg/dL; sódio\nurinário 92 mEq/L e creatinina urinária 84 mg/dL. EAS com densidade de 1028 e traços de\nproteínas. TSH e T4 livre normais. A causa da hiponatremia deste paciente é:","options":{"A":"Intoxicação hídrica.","B":"Hipotireoidismo.","C":"Síndrome de secreção inapropriada do hormônio antidiurético.","D":"Diabetes insipidus."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-181103","number":"181103","sourceNumber":"181103","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Homem, 50 anos, hipertenso e diabético, em uso prévio de clortalidona, enalapril, ácido\nacetil salicílico e metformina, admitido com quadro de vômitos, diarréia e febre há 3 dias. Ao exame\napresenta-se desidratado, hipotenso, FC de 120 bpm, FR 30 irpm e abdome dolorido. Exames de\nurgência com creatina de 3,0 mg/dL, ureia a 150 mg/dL, sódio 128 mmol/L, potássio 2,6 mmol/L, ph\n7,55, HCO3 32 mEq/L, PaCO 235 mmHg, PO 2 60 mmHg, SatO 290 em ar ambiente. Diante desse\ncaso, quais as possíveis causas da hipocalemia?","options":{"A":"Uso de tiazídico, diarreia e vômitos levando a alcalose metabólica;","B":"Lesão renal aguda, diarréia, uso de metformina e enalapril;","C":"Uso de inibidor de enzima conversora de angiotensina(IECA), alcalose metabólica e diarreia;","D":"Uremia, alcalose respiratória, uso de tiazidico e de metformina."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-181080","number":"181080","sourceNumber":"181080","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Na SIADH, é CORRETO afirmar que:","options":{"A":"Constitui-se de hipernatremia e euvolemia, geralmente com poliúria associada.","B":"É usual na síndrome: hiponatremia, hipouricemia, sódio urinário alto e osmolaridade urinária\nalta.","C":"A hipovolemia caracteriza a SIADH nos pacientes com HSA, diferenciando-a da síndrome\nperdedora de sal.","D":"Deve-se evitar o uso de furosemida em seu tratamento, pelo efeito natriurético daquele\ndiurético."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-177298","number":"177298","sourceNumber":"177298","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Um paciente previamente hígido, hospitalizado por sepse grave de foco pulmonar, em\nventilação mecânica controlada por pressão com FiO? = 0,8, FR = 12 irpm com PEEP = 5cmH?O e\nrelação I:E = 1:2, realizou a seguinte gasometria: pH = 7,06, pCO? = 28, pO? = 82 e Bic = 3,6. Com\nrelação ao caso, é correto afirmar que:","options":{"A":"a redução da frequência respiratória pode ser efetiva no controle da alteração acidobásica","B":"nesse caso, não há necessidade de aumento da PEEP, tendo em vista pO2 adequada","C":"está indicada a administração de bicarbonato intravenoso, com objetivo de pH \"maior que\" 7,2","D":"considerando a pO2, o paciente apresenta boa troca gasosa","E":"espera-se que o ânion-gap não esteja elevado"},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-158131","number":"158131","sourceNumber":"158131","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Em relação ao manejo da Doença Renal Crônica (DRC), segundo o KDIGO (Kidney\nDisease Improving Global Outcomes), é CORRETO afirmar:","options":{"A":"Sugere-se incentivar elevada ingestão proteica (>1,3g/kg/dia) em adultos com DRC e elevado\nrisco de progressão.","B":"Anemia é diagnosticada em adultos com DRC, quando Hb < 10g/dL - em homens e Hb < 9g/dL -\nem mulheres.","C":"Recomenda-se utilizar bloqueador de canal de cálcio em adultos diabéticos com DRC e\nexcreção de albumina urinária > 300mg/24h para prevenção da progressão da doença renal\ncrônica.","D":"Recomenda-se como alvo hemoglobina A1c (HbA1c) de = 7,0% para prevenir ou retardar a\nprogressão das complicações microvasculares do diabetes, incluindo a nefropatia diabética."},"answer":"D","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-156428","number":"156428","sourceNumber":"156428","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Existe aumento de risco de hipercalemia em pacientes usando drogas que interfiram\ncom o sistema\nrenina-angiotensina-aldosterona, como os inibidores de enzima de conversão (ECA),\nnas seguintes situações abaixo. Marque a alternativa em que isso NÃO ocorre:","options":{"A":"Doença renal crônica, especialmente quando o clearance é menor que 30 mL/min.","B":"Uso de diuréticos tiazídicos.","C":"Diabetes mellitus.","D":"Uso concomitante de betabloqueadores."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-136963","number":"136963","sourceNumber":"136963","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente desidratada grave, com 13 kg de peso, apresenta a seguinte gasometria: pH =\n7,34, pCO? = 28, pO? = 90, HCO? = 20, BE = - 2. Qual deve ser a composição do soro a ser\nprescrito?","options":{"A":"260 mL de bicarbonato de sódio a 8,4% na 1ª hora da fase de expansão.","B":"260 mL de soro fisiológico a 0,9% como fase de expansão.","C":"130 mL de soro glicosado 5%+130 mL de bicarbonato de sódio a 8,4% na 1ª hora da fase de\nexpansão.","D":"200 mL de soro glicosado 5%+60 mL de soro fisiológico 0,9% na 1ª hora da fase de expansão."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-85034","number":"85034","sourceNumber":"85034","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Sobre equilíbrio ácido-básico, enumere a coluna da direita de acordo com a da\nesquerda. 1 - Acidose metabólica; 2 -\nAlcalose metabólica; 3 - Acidose respiratória; 4 - Alcalose\nrespiratória; ( ) pH < 7,35; pCO2 > 45 mmHg. ( ) pH > 7,45; Bicarbonato > 26 mEq/L. ( ) pH > 7,45;\npCO2 < 35 mmHg. ( ) pH < 7,35; Bicarbonato < 22 mEq/L. Marque a sequência correta.","options":{"A":"1, 4, 2, 3.","B":"3, 2, 1, 4.","C":"3, 2, 4, 1.","D":"4, 1, 3, 2."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274853","number":"274853","sourceNumber":"274853","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"M.F.S., masculino, 45 anos, deu entrada no pronto-socorro com queixa de edema\ngeneralizado há 30 dias com piora progressiva há 2 semanas, associada à dispneia aos mínimos\nesforços. Relata ser portador de diabetes melito e hipertensão arterial sistêmica em\nacompanhamento no posto de saúde. Ao exame: PA: 180 x 100 mmHg; FC: 78 bpm; Fr: 25 irpm.\nAparelho respiratório murmúrio vesicular presente com estertores crepitantes até terço médio\nbilateralmente. Precórdio com bulhas normofonéticas, normorrítmicas em 2 tempos sem sopros.\nAbdome sem alts. Edema de MMII bilateral simétrico +3/+4. Exames laboratoriais: creatinina 5,0;\nureia 160; potássio 5,9; gasometria arterial com ph 7,22, pCO? 20, pO? 98, HCO 11; urina I com\npth +3 leuco 05 p/c hemácias 02 p/c nitrito negativo bactérias numerosas. Analisando esse caso,\nafirma-se tratar de um paciente:","options":{"A":"Portador de doença renal crônica devido à nefropatia diabética e que necessita de diálise de\nurgência em vista de hipervolemia e acidose metabólica.","B":"Com quadro de edema agudo de pulmão secundário à insuficiência cardíaca e lesão renal\naguda, sendo necessário o uso de diurético e vasodilatadores endovenosos para melhora.","C":"Com quadro de edema agudo de pulmão secundário à doença renal crônica sem urgência\ndialítica no momento, sendo necessário o uso de\ndiuréticos e vasodilatadores endovenosos para\nmanejo do quadro clínico.","D":"Portador de doença renal crônica estádio IV secundário à nefropatia diabética, necessitando de\ndiálise de urgência devido à acidose metabólica e hipervolemia.","E":"Portador de doença renal crônica devido à nefropatia diabética e que necessita de infusão de\nbicarbonato endovenoso para controle da acidose metabólica."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-360614","number":"360614","sourceNumber":"360614","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Consequente à propriedade osmótica da glicose, podemos indicar que:","options":{"A":"Hiperglicemia leva ao deslocamento de água livre para o espaço intracelular, provocando\nhemodiluição e queda da natremia.","B":"A hiperglicemia leva ao deslocamento de água livre para o espaço extracelular, provocando\nhemodiluição e queda da natremia.","C":"A hipoglicemia leva ao deslocamento de água livre para o espaço extracelular, provocando\nhemodiluição e aumento da natremia.","D":"Podemos afirmar que a hiperglicemia leva ao deslocamento de água livre para o espaço\nintracelular, provocando hemodiluição e queda da natremia."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-360612","number":"360612","sourceNumber":"360612","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Utiliza-se o fator de correção de redução de 1,6 meq/L na concentração sérica de\nsódio, sendo correto o item:","options":{"A":"Para cada aumento de 10 mg/dL na concentração orgânica de glicose.","B":"Considerando aumento de 100 mg/dL na concentração urinaria de glicose.","C":"Para cada aumento de 100 mg/dL na concentração plasmática de glicose.","D":"Na redução de 100 mg/dL na concentração urinária de glicose."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-309767","number":"309767","sourceNumber":"309767","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente diabético tipo 1, admitido com epigastralgia. Afirma história de vômitos com\nrestos alimentares no dia anterior. Ao exame\nencontra-se desidratado, eupneico, anicterico e\nafebril. Exame físico abdominal sem alterações. Devido a queixa de epigastralgia é solicitado\neletrocardiograma para realização de diagnóstico diferencial. Gasometria: Ph 7,40 Bicarbonato de\n\n22. Glicemia capilar 160mg/dl. Segue o traçado da derivação D2. Após análise do\neletrocardiograma assinale a conduta adequada para este caso:","options":{"A":"Soroterapia, reposição de potássio e insulinoterapia endovenosa.","B":"Soroterapia e reposição de potássio via oral.","C":"Soroterapia e reposição de potássio endovenosa.","D":"Soroterapia e correção glicêmica com insulina NPH.","E":"Acionamento imediato do serviço de hemodinâmica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274854","number":"274854","sourceNumber":"274854","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Com relação às Lesões Renais Agudas, assinale a alternativa correta.","options":{"A":"A Nefropatia do Contraste caracteriza-se pelo aumento de ureia e creatinina plasmáticas nas\nprimeiras 24 a 48 horas após a exposição ao contraste, apenas em pacientes portadores de\ndoença renal prévia.","B":"Quanto à nefrotoxicidade por drogas, afirma-se que a secundária ao uso de Anfotericina está\nassociada à dose e à duração do tratamento, e apresenta-se com poliúria, hipomagnesemia,\nhipocalemia e acidose metabólica com anion gap normal.","C":"Na lesão renal aguda secundária à sepse, os mecanismos fisiopatológicos envolvidos são\nvasoconstrição arteriolar eferente excessiva ou vasoconstrição renal causada pela ativação do\nsistema renina-angiotensina-aldosterona, do sistema nervoso simpático, da vasopressina e da\nendotelina.","D":"Esse tipo de lesão se relaciona à diminuição abrupta da função renal com aumento dos níveis\nséricos de ureia e creatinina, independentemente do volume de diurese.","E":"Todas as lesões renais agudas, independentemente das causas, precisam de terapia renal\nsubstitutiva."},"answer":"E","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-274855","number":"274855","sourceNumber":"274855","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"No que concerne à Doença Renal Crônica, assinale a alternativa correta.","options":{"A":"A doença real crônica abrange os processos fisiopatológicos do declínio progressivo da função\nrenal e pode ser classificada de acordo com\na taxa de filtração glomerular, independentemente da\npresença ou não de albuminúria.","B":"Vários fatores estão associados à perda progressiva da função renal, tais como anormalidades\ndo trato urinário, história familiar de doença\nrenal, hipertensão arterial sistêmica e diabetes melito.","C":"O distúrbio mineral ósseo presente nos pacientes com doença renal crônica está associado\nexclusivamente ao aumento dos níveis séricos de PTH.","D":"A anemia da doença renal crônica deve-se unicamente à deficiência de eritropoetina, sendo\nnecessária a sua reposição.","E":"No estádio IV da doença renal crônica, os pacientes devem iniciar terapia renal substitutiva,\ntais\ncomo hemodiálise ou diálise peritoneal."},"answer":"B","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-247119","number":"247119","sourceNumber":"247119","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Criança de 2 anos com queixa de aumento da ingestão de água de forma compulsiva e\npoliúria de início há 4 dias. Há 24 horas, iniciou com letargia, anorexia e vômitos. Mãe refere que\na\ncriança é previamente hígida e sem outras queixas atuais. Nega quadro infeccioso recente. Ao\nexame, a criança apresenta-se sonolenta, responsiva ao comando verbal, hidratada, com auscultas\ncardíaca e pulmonar normais, PA 92 x 58 mmHg (P50 - 93 x 50 mmHg/P90 - 107 x 65 mmHg/P95\n112 x 70 mmHg). Exames séricos: Hb 12,5 Ht 38; leuc. 12.000 B1 S50 L40 M9; plaq. 278.000; Ur\n\n26 mg/dl; Cr 0,7 mg/dl; Na 129 mEq/L; K 4,0 mEq/L; Ca 9 mEq/L; Mg 1,9 mEq/L; osmolalidade 90\n\n(referência 280 e 295 mOsm/kg H2O); Na urinário 12 (referência 15 a 20 mEq/L). Qual o\ndiagnóstico para esse caso?","options":{"A":"Síndrome perdedora de sal cerebral.","B":"Insuficiência suprarrenal.","C":"Polidipsia primária.","D":"Fase poliúrica da insuficiência renal.","E":"Pseudo-hipoaldosteronismo tipo I."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-216850","number":"216850","sourceNumber":"216850","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Paciente do sexo masculino, 45 anos, hipertenso em uso de enalapril. Refere ter usado\ndiclofenaco diariamente no último mês devido a dores musculares. Retorna em sua consulta de\nseguimento de hipertensão trazendo eletrocardiograma que havia sido solicitado por seu médico.\n\nAssinale a associação CORRETA entre o distúrbio hidroeletrolítico responsável pelas alterações\neletrocardiográficas encontradas e o tratamento recomendado:","options":{"A":"Hipercalemia: deve-se administrar 10 ml de gluconato de cálcio 10% via endovenosa em 2 a 5\nminutos.","B":"Hipercalemia: deve-se administrar 10 ml de sulfato de magnésio 10% via endovenosa em 2 a 5\nminutos.","C":"Hipocalemia: deve-se administrar 10 ml de gluconato de cálcio 10% via endovenosa em 2 a 5\nminutos.","D":"Hipocalemia: deve-se administrar 10 ml de sulfato de magnésio 10% via endovenosa em 2 a 5\nminutos."},"answer":"A","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-216827","number":"216827","sourceNumber":"216827","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"A Doença Renal Crônica (DRC) é acompanhada de uma série de distúrbios\nhidroeletrolíticos e metabólicos. Quanto a\nesses distúrbios assinale a alternativa CORRETA:","options":{"A":"A deficiência de vitamina D ocorre devido ao deficit da absorção intestinal dessa vitamina.","B":"A anemia é multifatorial e parece reduzir o risco cardiovascular dos pacientes.","C":"A hiperfosfatemia pode aumentar o risco cardiovascular na DRC.","D":"O acúmulo de ureia é o principal responsável pelos sintomas da síndrome urêmica."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-3-221273","number":"221273","sourceNumber":"221273","collectionBlock":"medcurso:medcurso-nefrologia-nef-3","collectionLabel":"Medcurso · NEF 3","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 3","subtopic":"","stem":"Das alternativas citadas abaixo, qual NÃO representa uma indicação formal de diálise?","options":{"A":"Azotemia grave.","B":"Hipercalemia refratária.","C":"Hiponatremia grave.","D":"Hipervolemia refratária."},"answer":"C","source":"Nefrologia/NEF 3/NEF 3.txt","sourceLabel":"Medcurso · NEF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
